if(!Array.isArray(state.page1Apps)) state.page1Apps=[];

// 桌面旧“人设”入口迁移为短信；人设创建仍保留在 Chat 的 Contacts 中。
state.page1Apps.forEach(function(app){
  if(app&&app.id==="persona"){
    app.label="短信";
    app.action="sms";
  }
});

state.page1Apps.forEach(function(app){
  if((!app.icon || !String(app.icon).trim()) && minimalPage1Icons[app.id]) app.icon=minimalPage1Icons[app.id];
});

