function bbAestheticThemeMap(){
  return {
    page1: {
      chat: bbAestheticPhotoIcon('cat'),
      persona: bbAestheticPhotoIcon('manga'),
      world: bbAestheticPhotoIcon('three'),
      user: bbAestheticPhotoIcon('flower'),
      settings: bbAestheticPhotoIcon('wireheart'),
      phonecheck: bbAestheticPhotoIcon('door'),
      music: bbAestheticPhotoIcon('vinyl'),
      beautify: bbAestheticPhotoIcon('butterfly')
    },
    page2: {
      mail: bbAestheticPhotoIcon('sky'),
      shop: bbAestheticPhotoIcon('cup'),
      delivery: bbAestheticPhotoIcon('crowd'),
      calendar: bbAestheticPhotoIcon('alarm'),
      anniv: bbAestheticPhotoIcon('clap'),
      couple: bbAestheticPhotoIcon('floppy'),
      phonecheck: bbAestheticPhotoIcon('door')
    }
  };
}

function applyAestheticIconTheme(force){
  const maps = bbAestheticThemeMap();
  if(!Array.isArray(state.page1Apps)) state.page1Apps = [];
  if(!Array.isArray(state.page2Apps)) state.page2Apps = [];
  state.page1Apps.forEach(app=>{
    if(!app || !maps.page1[app.id]) return;
    if(force || !String(app.icon || '').trim()) app.icon = maps.page1[app.id];
  });
  state.page2Apps.forEach(app=>{
    if(!app || !maps.page2[app.id]) return;
    if(force || !String(app.icon || '').trim()) app.icon = maps.page2[app.id];
  });
  state.iconThemeVersion = 'ins_ref_v3';
}

if(state.iconThemeVersion !== 'ins_ref_v3'){
  applyAestheticIconTheme(true);
}


const PAGE1_POLAROID_WIDGET_BG = "data:image/png;base64,";
const PAGE1_POLAROID_FRONT_MASK = "data:image/png;base64,";
const PAGE1_POLAROID_BACK_MASK = "data:image/png;base64,";


function normalizeDesktopAppSets(){
  const page1Order = ["chat","world","music","beautify"];
  const page2Order = ["mail","shop","delivery","calendar","anniv","couple","phonecheck"];
  const defaults = {
    chat: { id:"chat", icon:minimalPage1Icons.chat, label:"Chat", action:"chat" },
    world: { id:"world", icon:minimalPage1Icons.world, label:"世界书", action:"worldbook" },
    music: { id:"music", icon:minimalPage1Icons.music, label:"音乐", action:"music" },
    beautify: { id:"beautify", icon:minimalPage1Icons.beautify, label:"美化", action:"beautify" },
    settings: { id:"settings", icon:minimalPage1Icons.settings, label:"设置", action:"settings" },
    persona: { id:"persona", icon:minimalPage1Icons.persona, label:"短信", action:"sms" },
    user: { id:"user", icon:minimalPage1Icons.user, label:"User", action:"placeholder" },
    phonecheck: { id:"phonecheck", icon:minimalPage1Icons.phonecheck, label:"查手机", action:"subjects" },
    mail: { id:"mail", icon:"", label:"X", action:"placeholder" },
    shop: { id:"shop", icon:"", label:"购物", action:"placeholder" },
    delivery: { id:"delivery", icon:"", label:"外卖", action:"placeholder" },
    calendar: { id:"calendar", icon:"", label:"抖音", action:"placeholder" },
    anniv: { id:"anniv", icon:"", label:"小红书", action:"placeholder" },
    couple: { id:"couple", icon:"", label:"情侣空间", action:"placeholder" }
  };
  const seen = new Map();
  (Array.isArray(state.page1Apps)?state.page1Apps:[]).forEach(app=>{ if(app&&app.id&&!seen.has(app.id)) seen.set(app.id, app); });
  (Array.isArray(state.page2Apps)?state.page2Apps:[]).forEach(app=>{ if(app&&app.id&&!seen.has(app.id)) seen.set(app.id, app); });

  state.page1Apps = page1Order.map(id=>{
    const source = seen.get(id) || defaults[id] || {id, icon:"", label:id, action:"placeholder"};
    return {...defaults[id], ...source, id};
  });
  state.page2Apps = page2Order.map(id=>{
    const source = seen.get(id) || defaults[id] || {id, icon:"", label:id, action:"placeholder"};
    return {...defaults[id], ...source, id};
  });
}
normalizeDesktopAppSets();

