function buildPage1PolaroidWidget(){
  ensurePage1PolaroidWidgetStyle();
  const widget = document.createElement("section");
  widget.className = "bb-page1-polaroid-widget";
  widget.setAttribute("aria-label","双层可换图拍立得组件");
  const frontPhoto = state.page1PolaroidPhoto || "";
  const backPhoto = state.page1PolaroidBackPhoto || "";
  widget.innerHTML = `
    <div class="bb-page1-polaroid-photo-layer bb-page1-polaroid-photo-back">${backPhoto ? `<img src="${backPhoto}" alt="后层拍立得照片">` : ""}</div>
    <div class="bb-page1-polaroid-photo-layer bb-page1-polaroid-photo-front">${frontPhoto ? `<img src="${frontPhoto}" alt="前层拍立得照片">` : ""}</div>
    <div class="bb-page1-polaroid-surface" aria-hidden="true"></div>
    <button type="button" class="bb-page1-polaroid-hit bb-page1-polaroid-front-hit" aria-label="更换前层照片"></button>
    <button type="button" class="bb-page1-polaroid-hit bb-page1-polaroid-back-hit-right" aria-label="更换后层照片"></button>
    <button type="button" class="bb-page1-polaroid-hit bb-page1-polaroid-back-hit-bottom" aria-label="更换后层照片"></button>
    <input type="file" class="bb-page1-polaroid-front-input" accept="image/*" hidden>
    <input type="file" class="bb-page1-polaroid-back-input" accept="image/*" hidden>
  `;
  const frontInput = widget.querySelector('.bb-page1-polaroid-front-input');
  const backInput = widget.querySelector('.bb-page1-polaroid-back-input');
  const frontLayer = widget.querySelector('.bb-page1-polaroid-photo-front');
  const backLayer = widget.querySelector('.bb-page1-polaroid-photo-back');
  const frontHit = widget.querySelector('.bb-page1-polaroid-front-hit');
  const backHits = widget.querySelectorAll('.bb-page1-polaroid-back-hit-right,.bb-page1-polaroid-back-hit-bottom');

  const stop = event=>{
    if(!event) return;
    event.preventDefault();
    event.stopPropagation();
    if(typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation();
  };
  const openFront = event=>{
    stop(event);
    setTimeout(()=>frontInput.click(),0);
  };
  const openBack = event=>{
    stop(event);
    setTimeout(()=>backInput.click(),0);
  };
  ['pointerdown','mousedown','touchstart'].forEach(type=>{
    frontHit.addEventListener(type,event=>event.stopPropagation(),{passive:true});
    backHits.forEach(hit=>hit.addEventListener(type,event=>event.stopPropagation(),{passive:true}));
  });
  frontHit.addEventListener('click',openFront);
  backHits.forEach(hit=>hit.addEventListener('click',openBack));
  frontInput.addEventListener('click',event=>event.stopPropagation());
  backInput.addEventListener('click',event=>event.stopPropagation());

  const installPhotoChange = (input, stateKey, layer, label)=>{
    input.addEventListener('change', async event=>{
      event.stopPropagation();
      const file = input.files && input.files[0];
      input.value = '';
      if(!file) return;
      try{
        const data = await compressImageToBudget(file,{
          maxDim:1000,
          minDim:480,
          quality:.88,
          minQuality:.58,
          maxChars:240000,
          mime:'image/webp'
        });
        state[stateKey] = data;
        layer.innerHTML = `<img src="${data}" alt="${label}">`;
        saveLocal();
        if(typeof showToast === 'function') showToast('照片已更换');
      }catch(error){
        if(typeof showToast === 'function') showToast('照片读取失败', true);
      }
    });
  };
  installPhotoChange(frontInput,'page1PolaroidPhoto',frontLayer,'前层拍立得照片');
  installPhotoChange(backInput,'page1PolaroidBackPhoto',backLayer,'后层拍立得照片');
  return widget;
}

function baobaoStorageSnapshot(){
  const snapshot={...state};

  if(snapshot.activeChatId&&snapshot.chatRecords&&Array.isArray(snapshot.chatRecords[snapshot.activeChatId])){
    snapshot.chatMessages=[];
  }

  if(snapshot.avatar&&snapshot.charAvatar&&snapshot.avatar===snapshot.charAvatar){
    snapshot.avatar="__BB_CHAR_AVATAR__";
  }
  if(snapshot.lockWallpaper&&snapshot.wallpaper&&snapshot.lockWallpaper===snapshot.wallpaper){
    snapshot.lockWallpaper="__BB_WALLPAPER__";
  }
  if(snapshot.wechatProfile&&snapshot.wechatProfile.avatar&&snapshot.wechatProfile.avatar===snapshot.charAvatar){
    snapshot.wechatProfile={...snapshot.wechatProfile,avatar:"__BB_CHAR_AVATAR__"};
  }
  if(snapshot.chatBackground&&snapshot.chatBackground.type==="image"&&snapshot.chatBackground.value===snapshot.wallpaper){
    snapshot.chatBackground={...snapshot.chatBackground,value:"__BB_WALLPAPER__"};
  }
  if(Array.isArray(snapshot.userMasks)){
    snapshot.userMasks=snapshot.userMasks.map(mask=>{
      if(!mask)return mask;
      const copy={...mask};
      if(copy.avatar&&copy.avatar===snapshot.charAvatar) copy.avatar="__BB_CHAR_AVATAR__";
      else if(copy.avatar&&copy.avatar===snapshot.avatar) copy.avatar="__BB_DESKTOP_AVATAR__";
      return copy;
    });
  }

  return snapshot;
}

function baobaoCleanupTemporaryStorage(){
  try{
    const tails=[];
    for(let i=0;i<localStorage.length;i++){
      const key=localStorage.key(i);
      if(key&&key.indexOf("bb_reentry_tail_")===0) tails.push(key);
    }
    tails.sort().reverse().slice(3).forEach(key=>localStorage.removeItem(key));
    localStorage.removeItem("baobao_manual_restore");
  }catch(e){}
}

function saveLocal(){
  const payload=JSON.stringify(baobaoStorageSnapshot());
  try{
    localStorage.setItem("baobao_state",payload);
    return true;
  }catch(e){
    console.warn("首次保存超出空间，正在整理临时缓存：",e);
    baobaoCleanupTemporaryStorage();
    try{
      localStorage.setItem("baobao_state",payload);
      return true;
    }catch(err){
      console.error("保存失败：",err);
      return false;
    }
  }
}

// ===== 提示条（Toast） =====
function showToast(msg, isError){
  let toast = document.getElementById("toastMsg");
  if(!toast){
    toast = document.createElement("div");
    toast.id = "toastMsg";
    toast.style.cssText = "position:absolute;left:50%;top:24px;transform:translateX(-50%);max-width:80%;text-align:center;padding:10px 18px;border-radius:20px;font-size:13px;color:#fff;z-index:999;opacity:0;transition:opacity .25s ease;pointer-events:none";
    document.querySelector(".phone").appendChild(toast);
  }
  toast.textContent = msg;
  toast.style.background = isError ? "rgba(200,60,60,.92)" : "rgba(0,0,0,.8)";
  toast.style.opacity = "1";
  clearTimeout(toast._hideTimer);
  toast._hideTimer = setTimeout(()=>{ toast.style.opacity = "0"; }, 1800);
}

// ===== 美化面板：保存当前美化（带成功/失败提示） =====
function saveBeautify(){
  const ok = saveLocal();
  if(ok){
    showToast(" 美化已保存");
  }else{
    showToast(" 保存失败，图片太大，试试换小一点的图片", true);
  }
}

