function buildPage2(){
  const pageDiv = document.createElement("div");
  pageDiv.className = "apps-page page2-only";

  pageDiv.appendChild(buildPage2ProfileWidget());

  state.page2Apps.forEach((app, aIdx) => {
    const appDiv = document.createElement("div");
    appDiv.className = "app";
    const iconInner = app.icon.startsWith("data:")
      ? `<img src="${app.icon}" style="width:100%;height:100%;border-radius:16px;object-fit:cover">`
      : app.icon;

    appDiv.innerHTML = `<div class="icon">${iconInner}</div>${app.label}`;

    bindSafeDesktopAppPress(
      appDiv,
      () => handleAppActionP2(state.page2Apps[aIdx]),
      () => openIconEditP2(aIdx)
    );

    pageDiv.appendChild(appDiv);
  });

  pageDiv.appendChild(buildPage2MiniProfileCard());
  pageDiv.appendChild(buildPage2MiniSongCard());
  return pageDiv;
}

function renderDots(){
  const dots = $("dots");
  dots.innerHTML = "";
  for (let i = 0; i < TOTAL_PAGES; i++){
    const dot = document.createElement("div");
    dot.className = "dot" + (i === state.page ? " active" : "");
    dots.appendChild(dot);
  }
}

function goToPage(idx, animate){
  idx = Math.max(0, Math.min(TOTAL_PAGES - 1, idx));
  state.page = idx;
  saveLocal();
  const container = $("pagesContainer");
  container.style.transition = animate === false ? "none" : "transform .28s cubic-bezier(.22,1,.36,1)";
  container.style.transform = `translateX(${-idx * 100}%)`;

  // 第二页是真正独立桌面：隐藏第一页状态板/组件
  const desktop = $("desktop");
  if(idx === 1){
    desktop.classList.add("page-two-mode");
  }else{
    desktop.classList.remove("page-two-mode");
  }

  renderDots();
}

// ===== 第一页：长按 / 点击 处理（原有逻辑，未改动） =====
function startPress(aIdx){
  longPressTriggered = false;
  longPressTimer = setTimeout(() => {
    longPressTriggered = true;
    openIconEdit(aIdx);
  }, 550);
}
function endPress(aIdx){
  clearTimeout(longPressTimer);
  if (!longPressTriggered){
    handleAppAction(state.page1Apps[aIdx]);
  }
}
function cancelPress(){
  clearTimeout(longPressTimer);
}

function getAppById(id){
  const found = state.page1Apps.find((a) => a.id === id) || state.page2Apps.find((a) => a.id === id);
  if(found) return found;
  const fallbackMap = {
    settings: { id:"settings", icon:minimalPage1Icons.settings, label:"设置", action:"settings" },
    chat: { id:"chat", icon:minimalPage1Icons.chat, label:"Chat", action:"chat" },
    persona: { id:"persona", icon:minimalPage1Icons.persona, label:"短信", action:"sms" },
    user: { id:"user", icon:minimalPage1Icons.user, label:"User", action:"placeholder" }
  };
  return fallbackMap[id] || null;
}

function handleAppAction(app){
  if(!app) return;
  if (app.id === "music" || app.action === "music" || app.label === "音乐"){
    if(typeof window.openBaobaoMusicApp === "function"){
      window.openBaobaoMusicApp();
    }else{
      openAppModal("音乐");
    }
    return;
  }
  if (app.id === "world" || app.action === "worldbook" || app.label === "世界书"){
    if(typeof window.openBaobaoWorldBook === "function"){
      window.openBaobaoWorldBook("app");
    }else{
      openAppModal("世界书");
    }
    return;
  }
  if (app.action === "chat"){
    try{ if(typeof renderWeChatApp === "function") renderWeChatApp(); }catch(error){}
    document.getElementById("chatDemo").style.display="block";
  } else if (app.action === "settings"){
    syncFullScreenToggle();
    openPanel("settings");
  } else if (app.action === "beautify"){
    openPanel("beautify");
  } else if (app.action === "subjects"){
    openSubjectsPanel();
  } else if (app.action === "sms" || app.id === "persona"){
    if(typeof window.openSmsApp==="function") window.openSmsApp();
    else openAppModal("短信");
  } else {
    openAppModal(app.label);
  }
}

// ===== 第二页：完全独立的长按 / 点击 处理，不复用第一页的函数与状态变量 =====
let page2LongPressTimer = null;
let page2LongPressTriggered = false;
let page2EditingApp = null; // aIdx

function startPressP2(aIdx){
  page2LongPressTriggered = false;
  page2LongPressTimer = setTimeout(() => {
    page2LongPressTriggered = true;
    openIconEditP2(aIdx);
  }, 550);
}
function endPressP2(aIdx){
  clearTimeout(page2LongPressTimer);
  if (!page2LongPressTriggered){
    handleAppActionP2(state.page2Apps[aIdx]);
  }
}
function cancelPressP2(){
  clearTimeout(page2LongPressTimer);
}

function handleAppActionP2(app){
  if(!app) return;
  if(app.action === "subjects" || app.id === "phonecheck"){
    openSubjectsPanel();
    return;
  }
  openAppModal(app.label);
}

// ===== 通用 App 占位弹窗 =====
function openAppModal(label){
  if((label === "世界书" || label === "挂载世界书") &&
     typeof window.openBaobaoWorldBook === "function"){
    window.openBaobaoWorldBook("app");
    return;
  }
  state.lastPageBeforeApp = state.page;
  $("modalTitle").innerHTML = label;
  $("modalBody").innerHTML = "这个功能还在开发中，敬请期待～";
  openPanel("modal");
}

// ===== 线下剧情：字数限制设置（"小纸条"入口）=====
function openOfflineWordLimitSettings(){
  state.lastPageBeforeApp = state.page;
  $("modalTitle").innerHTML = "线下剧情字数限制";
  $("modalBody").innerHTML = `
    <div class="bb-setting-field" style="margin-top:0">
      <div class="bb-setting-label">每次线下剧情生成的目标字数（正文+心里合计）</div>
      <input type="text" id="offlineWordLimitInput" class="bb-setting-input" inputmode="numeric" value="${state.offlineWordLimit}" placeholder="例如 750">
    </div>
    <div class="bb-setting-actions">
      <div class="option" onclick="saveOfflineWordLimit()">保存</div>
      <div class="option secondary-option" onclick="closePanel('modal')">取消</div>
    </div>
    <div class="bb-setting-tip">AI 会尽量把这次输出写到这个字数附近（允许有小幅浮动），不会为了凑数硬截断或注水。</div>
  `;
  openPanel("modal");
}

function saveOfflineWordLimit(){
  const input = $("offlineWordLimitInput");
  const n = parseInt(input?.value, 10);
  if(!n || n < 50){ showToast("请输入一个不小于50的数字", true); return; }
  state.offlineWordLimit = n;
  saveLocal();
  showToast("字数目标已保存为 " + n + " 字");
  closePanel("modal");
}

// ===== 线下剧情：多预设管理（"更多"入口）=====
let offlinePresetEditingId = null;

function openOfflinePresetManager(){
  state.lastPageBeforeApp = state.page;
  offlinePresetEditingId = null;
  $("modalTitle").innerHTML = "线下剧情预设";
  renderOfflinePresetManagerBody();
  openPanel("modal");
}

function renderOfflinePresetManagerBody(){
  const list = state.offlinePresets || [];
  const noneActive = !list.some(p=>p && p.enabled);
  const editing = list.find(p=>p.id===offlinePresetEditingId);
  const rows = [`
    <div class="op-preset-row">
      <div class="op-preset-check ${noneActive?"checked":""}" onclick="disableAllOfflinePresets()">${noneActive?"✓":""}</div>
      <div class="op-preset-info" onclick="disableAllOfflinePresets()">
        <div class="op-preset-name">不使用预设</div>
        <div class="op-preset-preview">使用默认的剧情模式设置</div>
      </div>
    </div>
  `].concat(list.map(p=>`
    <div class="op-preset-row">
      <div class="op-preset-check ${p.enabled?"checked":""}" onclick="toggleOfflinePreset('${p.id}')">${p.enabled?"✓":""}</div>
      <div class="op-preset-info" onclick="toggleOfflinePreset('${p.id}')">
        <div class="op-preset-name">${escapeHtml(p.name||"未命名预设")}</div>
        <div class="op-preset-preview">${escapeHtml((p.content||"").slice(0,26))}${(p.content||"").length>26?"...":""}</div>
      </div>
      <div class="op-preset-actions">
        <div class="op-preset-icon-btn" onclick="editOfflinePreset('${p.id}')">✎</div>
        <div class="op-preset-icon-btn danger" onclick="deleteOfflinePreset('${p.id}')">🗑</div>
      </div>
    </div>
  `)).join("");

  $("modalBody").innerHTML = `
    <div class="op-preset-section-title" style="margin-top:0">已保存的预设</div>
    <div class="op-preset-list">${rows}</div>
    <div class="bb-setting-field">
      <div class="bb-setting-label">预设名称</div>
      <input type="text" id="offlinePresetNameInput" class="bb-setting-input" value="${escapeHtml(editing?editing.name:"")}" placeholder="为这个预设起个名字...">
    </div>
    <div class="bb-setting-field">
      <div class="bb-setting-label">剧情预设内容</div>
      <textarea id="offlinePresetContentInput" class="bb-setting-textarea" style="min-height:160px" placeholder="请输入线下剧情模式的预设内容，这将决定AI的文风、字数、视角等">${escapeHtml(editing?editing.content:"")}</textarea>
    </div>
    <div class="bb-setting-actions">
      <div class="option secondary-option" onclick="closePanel('modal')">取消</div>
      <div class="option secondary-option" onclick="clearOfflinePresetForm()">清空表单</div>
      <div class="option" onclick="saveOfflinePresetForm()">保存预设</div>
    </div>
    <div class="bb-setting-tip">可以同时勾选多个预设，内容会按顺序一起发给AI；勾选"不使用预设"会关闭所有预设。</div>
  `;
}

function toggleOfflinePreset(id){
  const p = (state.offlinePresets||[]).find(x=>x.id===id);
  if(!p) return;
  p.enabled = !p.enabled;
  saveLocal();
  renderOfflinePresetManagerBody();
}

function disableAllOfflinePresets(){
  (state.offlinePresets||[]).forEach(p=>{ p.enabled = false; });
  saveLocal();
  renderOfflinePresetManagerBody();
}

function editOfflinePreset(id){
  offlinePresetEditingId = id;
  renderOfflinePresetManagerBody();
}

function deleteOfflinePreset(id){
  state.offlinePresets = (state.offlinePresets||[]).filter(x=>x.id!==id);
  if(offlinePresetEditingId===id) offlinePresetEditingId = null;
  saveLocal();
  renderOfflinePresetManagerBody();
}

function clearOfflinePresetForm(){
  offlinePresetEditingId = null;
  renderOfflinePresetManagerBody();
}

function saveOfflinePresetForm(){
  const nameInput = $("offlinePresetNameInput");
  const contentInput = $("offlinePresetContentInput");
  const name = (nameInput?.value || "").trim();
  const content = (contentInput?.value || "").trim();
  if(!name || !content){ showToast("请填写预设名称和内容", true); return; }
  if(offlinePresetEditingId){
    const p = (state.offlinePresets||[]).find(x=>x.id===offlinePresetEditingId);
    if(p){ p.name = name; p.content = content; }
  }else{
    state.offlinePresets.push({ id:"preset_"+Date.now()+"_"+Math.random().toString(36).slice(2,7), name, content, enabled:true });
  }
  offlinePresetEditingId = null;
  saveLocal();
  renderOfflinePresetManagerBody();
  showToast("预设已保存");
}


function switchStickerTab(tab){
  document.querySelectorAll(".sticker-import-tab").forEach(el=>el.classList.toggle("active", el.dataset.tab===tab));
  document.querySelectorAll(".sticker-import-panel").forEach(el=>el.classList.toggle("active", el.dataset.panel===tab));
}

// ===== 表情包管理：单个URL导入 / 批量URL导入 / 文件导入 / 改名 / 删除 =====
function openStickerManager(){
  state.lastPageBeforeApp = state.page;
  $("modalTitle").innerHTML = "表情包管理";
  $("modalBody").innerHTML = `
    <div class="sticker-import-tabs">
      <div class="sticker-import-tab active" data-tab="single" onclick="switchStickerTab('single')">单个URL</div>
      <div class="sticker-import-tab" data-tab="batch" onclick="switchStickerTab('batch')">批量URL</div>
      <div class="sticker-import-tab" data-tab="file" onclick="switchStickerTab('file')">文件导入</div>
    </div>
    <div class="sticker-import-panel active" data-panel="single">
      <div class="sticker-import-row">
        <input type="text" id="stickerUrlInput" placeholder="支持直接粘贴：名称 -- https://... 或只粘贴链接">
        <div class="btn" onclick="addStickerFromUrl()">导入</div>
      </div>
    </div>
    <div class="sticker-import-panel" data-panel="batch">
      <textarea id="stickerBatchInput" class="bb-setting-textarea" style="min-height:100px" placeholder="支持整段粘贴：每行可写“名称 -- 链接”，也支持只放链接"></textarea>
      <div class="option" onclick="addStickersBatch()" style="margin-top:8px">批量导入</div>
    </div>
    <div class="sticker-import-panel" data-panel="file">
      <div class="option" onclick="triggerStickerFileImport()">选择图片文件（可多选）</div>
    </div>
    <div class="sticker-count" id="stickerCount"></div>
    <div class="sticker-grid" id="stickerGrid"></div>
  `;
  renderStickerGrid();
  openPanel("modal");
}

function renderStickerGrid(){
  const grid = $("stickerGrid");
  const count = $("stickerCount");
  if(!grid) return;
  if(count) count.textContent = "共 " + state.stickers.length + " 个表情";
  if(!state.stickers.length){
    grid.innerHTML = '<div class="sticker-empty">还没有表情包，导入几个吧～</div>';
    return;
  }
  grid.innerHTML = state.stickers.map(s => `
    <div class="sticker-item">
      <div class="sticker-delete" onclick="deleteSticker('${s.id}')">×</div>
      <div class="sticker-thumb">${s.url ? `<img src="${s.url}" onerror="this.parentElement.textContent='加载失败'">` : ""}</div>
      <input class="sticker-name-input" value="${escapeHtml(s.name||"")}" onchange="renameSticker('${s.id}', this.value)">
    </div>
  `).join("");
}

function extractStickerEntries(raw){
  const text = String(raw || "").replace(/\r/g, "\n").trim();
  if(!text) return [];
  const lines = text.split(/\n+/).map(s=>s.trim()).filter(Boolean);
  const entries = [];

  function fallbackNameFromUrl(url, offset){
    let name = "表情" + (state.stickers.length + 1 + (offset || 0));
    try{
      const clean = String(url || "").split("?")[0];
      const last = clean.substring(clean.lastIndexOf("/") + 1);
      if(last) name = decodeURIComponent(last.replace(/\.[a-zA-Z0-9]+$/, "")) || name;
    }catch(e){}
    return name;
  }

  function cleanStickerName(name){
    return String(name || "")
      .replace(/https?:\/\/\S+/gi, "")
      .replace(/[—–-]{2,}/g, " ")
      .replace(/[|｜]/g, " ")
      .replace(/[：:]+/g, " ")
      .replace(/\s+/g, " ")
      .replace(/^[\s\-—–:：|｜.,，;；、]+|[\s\-—–:：|｜.,，;；、]+$/g, "")
      .trim();
  }

  lines.forEach((line) => {
    const found = Array.from(String(line).matchAll(/https?:\/\/[^\s，,]+/gi)).map(m=>m[0]);
    if(found.length){
      const baseName = cleanStickerName(String(line).replace(/https?:\/\/[^\s，,]+/gi, " "));
      found.forEach((url, idx) => {
        const name = baseName || fallbackNameFromUrl(url, entries.length + idx);
        entries.push({ url, name: found.length > 1 && baseName ? (name + ' ' + (idx + 1)) : name });
      });
      return;
    }
    String(line).split(/[\s,，]+/).map(s=>s.trim()).filter(Boolean).forEach((url, idx) => {
      if(/^https?:\/\//i.test(url)) entries.push({ url, name: fallbackNameFromUrl(url, entries.length + idx) });
    });
  });

  return entries;
}

function addStickerFromUrl(){
  const input = $("stickerUrlInput");
  const raw = (input?.value || "").trim();
  const entries = extractStickerEntries(raw);
  if(!entries.length){ showToast("请先粘贴图片链接，或使用“文字 -- 链接”格式", true); return; }
  addStickerEntries(entries);
  if(input) input.value = "";
}

function addStickersBatch(){
  const input = $("stickerBatchInput");
  const raw = input?.value || "";
  const entries = extractStickerEntries(raw);
  if(!entries.length){ showToast("请先粘贴至少一个链接，也支持“文字 -- 链接”整段粘贴", true); return; }
  addStickerEntries(entries);
  if(input) input.value = "";
}

function addStickerEntries(items){
  const list = Array.isArray(items) ? items : [];
  let added = 0;
  list.forEach((item, idx)=>{
    const url = typeof item === 'string' ? String(item || '').trim() : String(item && item.url || '').trim();
    if(!/^https?:\/\//i.test(url)) return;
    let name = typeof item === 'string' ? '' : String(item && item.name || '').trim();
    if(!name){
      try{
        const clean = url.split("?")[0];
        const last = clean.substring(clean.lastIndexOf("/")+1);
        name = last ? (decodeURIComponent(last.replace(/\.[a-zA-Z0-9]+$/, "")) || '') : '';
      }catch(e){}
    }
    if(!name) name = "表情" + (state.stickers.length + 1 + idx);
    state.stickers.push({ id: "sticker_" + Date.now() + "_" + Math.random().toString(36).slice(2,7), url, name });
    added++;
  });
  if(!added){ showToast("没有识别到有效的图片链接（支持文字+链接一起导入）", true); return; }
  saveLocal();
  renderStickerGrid();
  showToast("已导入 " + added + " 个表情");
}

function triggerStickerFileImport(){
  $("stickerFileInput")?.click();
}

function stickerFilesChosen(input){
  const files = Array.from(input.files || []);
  if(!files.length) return;
  let remaining = files.length;
  files.forEach(file=>{
    const reader = new FileReader();
    reader.onload = function(e){
      const name = file.name.replace(/\.[^.]+$/, "") || ("表情" + (state.stickers.length + 1));
      state.stickers.push({ id: "sticker_" + Date.now() + "_" + Math.random().toString(36).slice(2,7), url: e.target.result, name });
      remaining--;
      if(remaining <= 0){
        saveLocal();
        renderStickerGrid();
        showToast("已导入 " + files.length + " 个表情");
      }
    };
    reader.readAsDataURL(file);
  });
  input.value = "";
}

function renameSticker(id, name){
  const s = state.stickers.find(x=>x.id===id);
  if(!s) return;
  s.name = (name||"").trim() || s.name;
  saveLocal();
}

function deleteSticker(id){
  state.stickers = state.stickers.filter(x=>x.id!==id);
  saveLocal();
  renderStickerGrid();
}

