function openWalletManager(){
  state.lastPageBeforeApp = state.page;
  $("modalTitle").innerHTML = "我的钱包";
  $("modalBody").innerHTML = `
    <div class="wallet-balance-card">
      <div class="wallet-balance-label">当前余额</div>
      <div class="wallet-balance-value" id="walletBalanceValue">¥0.00</div>
    </div>
    <div class="wallet-recharge-title">快速充值</div>
    <div class="wallet-chip-row">
      <div class="wallet-chip" onclick="rechargeWallet(6)">+¥6</div>
      <div class="wallet-chip" onclick="rechargeWallet(18)">+¥18</div>
      <div class="wallet-chip" onclick="rechargeWallet(50)">+¥50</div>
      <div class="wallet-chip" onclick="rechargeWallet(98)">+¥98</div>
      <div class="wallet-chip" onclick="rechargeWallet(198)">+¥198</div>
    </div>
    <div class="wallet-custom-row">
      <input type="text" id="walletCustomAmount" placeholder="自定义金额">
      <div class="btn" onclick="rechargeWalletCustom()">充值</div>
    </div>
    <div class="wallet-history-title">账单记录</div>
    <div class="wallet-history" id="walletHistory"></div>
  `;
  renderWalletManager();
  openPanel("modal");
}

function renderWalletManager(){
  const balEl = $("walletBalanceValue");
  if(balEl) balEl.textContent = "¥" + state.wallet.balance.toFixed(2);
  const hist = $("walletHistory");
  if(!hist) return;
  if(!state.wallet.history.length){
    hist.innerHTML = '<div class="wallet-history-empty">还没有账单记录</div>';
    return;
  }
  hist.innerHTML = state.wallet.history.slice().reverse().map(h => `
    <div class="wallet-history-item">
      <div>
        <div>${escapeHtml(h.label||"充值")}</div>
        <div class="wallet-history-time">${h.time||""}</div>
      </div>
      <div class="wallet-history-amount ${h.amount>=0?"in":""}">${h.amount>=0?"+":""}¥${Math.abs(h.amount).toFixed(2)}</div>
    </div>
  `).join("");
}

function rechargeWallet(amount){
  const n = Number(amount);
  if(!n || n<=0){ showToast("请输入有效的充值金额", true); return; }
  state.wallet.balance = Math.round((state.wallet.balance + n) * 100) / 100;
  state.wallet.history.push({ label:"充值", amount:n, time: formatWalletTime() });
  saveLocal();
  renderWalletManager();
  showToast("充值成功 +¥" + n.toFixed(2));
}

function rechargeWalletCustom(){
  const input = $("walletCustomAmount");
  const n = Number(input?.value);
  if(!n || n<=0){ showToast("请输入有效的充值金额", true); return; }
  rechargeWallet(n);
  if(input) input.value = "";
}

function formatWalletTime(){
  const d = new Date();
  const p = x => String(x).padStart(2,"0");
  return `${d.getFullYear()}/${p(d.getMonth()+1)}/${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

