// ===== 文案编辑面板：确认保存（根据 textEditMode 分流） =====
function confirmTextEdit(){
  const v1 = $("textEditInput1").value.trim();
  const v2 = $("textEditInput2").value.trim();

  if(textEditMode === "profile"){
    if(v1) state.name = v1;
    if(v2) state.status = v2;
    renderProfile();
    renderWeChatApp();
    saveLocal();
    closePanel("textEdit");
    showToast(" 已保存");

  }else if(textEditMode === "charProfile"){
    if(v1) state.name = v1;
    if(v2) state.status = v2;
    renderProfile();
    renderWeChatApp();
    saveLocal();
    closePanel("textEdit");
    showToast(" 已保存");

  }else if(textEditMode === "persona"){
    if(v1) state.name = v1;
    if(v2) state.status = v2;
    renderProfile();
    renderWeChatApp();
    saveLocal();
    closePanel("textEdit");
    showToast(" 人设已保存");

  }else if(textEditMode === "ins"){
    if(v1) state.insLine1 = v1;
    if(v2) state.insLine2 = v2;
    renderIns();
    saveLocal();
    closePanel("textEdit");
    showToast(" 已保存");

  }else if(textEditMode === "imagegen"){
    if(!v1){ showToast(" 请输入画面描述", true); return; }
    closePanel("textEdit");
    runImageGeneration(v1);

  }else if(textEditMode === "lockpw"){
    if(!/^\d{4}$/.test(v1)){ showToast(" 密码必须是4位数字", true); return; }
    if(v1 !== v2){ showToast(" 两次输入的密码不一致", true); return; }
    state.lockPassword = v1;
    saveLocal();
    closePanel("textEdit");
    showToast(" 锁屏密码已更新");

  }else if(textEditMode.indexOf("preset_") === 0){
    const type = textEditMode.slice("preset_".length);
    if(!v1){ showToast(" 请输入预设名称", true); return; }
    const current = readFormValues(type);
    const list = getPresets(type).filter((p) => p.name !== v1);
    list.push(Object.assign({ name:v1 }, current));
    savePresets(type, list);
    closePanel("textEdit");
    renderPresetChips(type);
    showToast(" 预设已保存：" + v1);
  }
}

