// ===== 桌面左右滑动翻页 =====
let deskStartX = 0, deskStartY = 0;
let deskMoving = false;
let deskIsSwipe = false;
let deskDragDX = 0;
let deskStartTime = 0;
let deskViewportWidth = 0;

function initSwipe(){
  const container = $("desktop");
  const pagesContainer = $("pagesContainer");
  const viewport = pagesContainer.parentElement; // .pages-viewport

  container.addEventListener("touchstart", (e) => {
    deskStartX = e.touches[0].clientX;
    deskStartY = e.touches[0].clientY;
    deskMoving = true;
    deskIsSwipe = false;
    deskDragDX = 0;
    deskStartTime = Date.now();
    deskViewportWidth = viewport.clientWidth || 1;
    // 拖动开始前先关掉过渡动画，让位移直接跟手，不要有延迟感
    pagesContainer.style.transition = "none";
  }, {passive:true});

  container.addEventListener("touchmove", (e) => {
    if(!deskMoving) return;

    const dx = e.touches[0].clientX - deskStartX;
    const dy = e.touches[0].clientY - deskStartY;

    if(!deskIsSwipe){
      if(Math.abs(dx) > 10 && Math.abs(dx) > Math.abs(dy)){
        deskIsSwipe = true;
      } else if(Math.abs(dy) > 10){
        // 判断为纵向滑动，本次不当作翻页处理
        deskMoving = false;
        return;
      }
    }

    if(deskIsSwipe){
      e.preventDefault();
      let drag = dx;
      // 已经在第一页/最后一页时继续往外拖，加阻尼，模拟到边界的手感
      if((state.page === 0 && dx > 0) || (state.page === TOTAL_PAGES - 1 && dx < 0)){
        drag = dx * 0.35;
      }
      deskDragDX = drag;
      const basePercent = -state.page * 100;
      const dragPercent = (drag / deskViewportWidth) * 100;
      pagesContainer.style.transform = `translateX(${basePercent + dragPercent}%)`;
    }
  }, {passive:false});

  container.addEventListener("touchend", () => {
    if(!deskMoving){ return; }
    deskMoving = false;

    if(deskIsSwipe){
      const elapsed = Date.now() - deskStartTime;
      const velocity = deskDragDX / Math.max(elapsed, 1); // px/ms，判断快速轻扫
      const threshold = deskViewportWidth * 0.18;
      let target = state.page;

      if(deskDragDX <= -threshold || velocity < -0.35){
        target = state.page + 1;
      } else if(deskDragDX >= threshold || velocity > 0.35){
        target = state.page - 1;
      }
      goToPage(target); // 未达到阈值时 target 等于当前页，会自动回弹
    }

    deskIsSwipe = false;
    deskDragDX = 0;
  }, {passive:true});

  container.addEventListener("touchcancel", () => {
    deskMoving = false;
    if(deskIsSwipe){ goToPage(state.page); }
    deskIsSwipe = false;
    deskDragDX = 0;
  }, {passive:true});
}

// ===== 锁屏上滑解锁 =====
function initLockSwipe(){
  let startY = 0;
  $("lock").addEventListener("touchstart", (e) => {
    startY = e.touches[0].clientY;
  });
  $("lock").addEventListener("touchend", (e) => {
    if($("passcodeOverlay").classList.contains("show")) return;
    const endY = e.changedTouches[0].clientY;
    if (startY - endY > 80) unlock();
  });
  $("lock").addEventListener("click", (e) => {
    if($("passcodeOverlay").classList.contains("show")) return;
    unlock();
  });
}


