// ===== 对话 API：调用 OpenAI 兼容的 /chat/completions =====
async function sendChatCompletion(messages, apiOverride){
  const api = apiOverride || getChatAPI();
  if(!api.endpoint || !api.key){
    throw new Error("请先在「API 设置 → 对话 API」里填写接口地址和 Key");
  }
  // Gemini 原生接口适配：支持在豹豹机里直接填写 Gemini API
  if((api.endpoint || "").includes("generativelanguage.googleapis.com")){
    const base = api.endpoint.replace(/\/$/, "");
    const model = api.model || "gemini-2.5-flash";
    const url = `${base}/models/${model}:generateContent?key=${api.key}`;
    const contents = messages.map(m=>({
      role: m.role === "assistant" ? "model" : "user",
      parts:[{text: typeof m.content === "string" ? m.content : JSON.stringify(m.content)}]
    }));
    try{
      const res = await fetch(url,{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({contents})
      });
      if(!res.ok){
        const errText = await res.text().catch(()=> "");
        throw new Error(`Gemini 返回错误 ${res.status}：${errText.slice(0,150)}`);
      }
      const data = await res.json();
      return data?.candidates?.[0]?.content?.parts?.[0]?.text || "";
    }catch(e){
      throw e;
    }
  }

  const url = api.endpoint.replace(/\/$/, "") + "/chat/completions";
  let res;
  try{
    res = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": "Bearer " + api.key
      },
      body: JSON.stringify({
        model: api.model || "gpt-3.5-turbo",
        messages
      })
    });
  }catch(e){
    throw new Error("请求失败，可能是网络问题或接口不支持浏览器跨域(CORS)");
  }
  if(!res.ok){
    const errText = await res.text().catch(() => "");
    throw new Error(`接口返回错误 ${res.status}：${errText.slice(0,150)}`);
  }
  const data = await res.json();
  const content = data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
  if(!content){
    throw new Error("接口返回了空内容，请检查模型名称/接口地址是否正确");
  }
  return content.trim();
}

