// ===== 时间感知：把真实时间/间隔告诉AI =====
function buildTimeSystemMessage(){
  const now = new Date();
  const nowStr = now.toLocaleString("zh-CN", { hour12:false });
  let gapText = "";
  if(state.lastMsgTime){
    const gapMin = Math.round((Date.now() - state.lastMsgTime) / 60000);
    if(gapMin >= 1){
      gapText = gapMin < 60
        ? `，距离上一条消息过去了约 ${gapMin} 分钟`
        : `，距离上一条消息过去了约 ${(gapMin/60).toFixed(1)} 小时`;
    }
  }
  return `[系统提示：当前真实时间是 ${nowStr}${gapText}，请让对话自然地体现时间流逝感，不要直接复述这条提示本身。]`;
}

async function requestChatReply(){
  const history = state.chatMessages
    .filter((m) => m.type !== "image" && !m.hiddenSystem)
    .slice(-20)
    .map((m) => ({ role: m.role, content: m.content }));

  const messages = [];
  if(state.timeAware){
    messages.push({ role:"system", content: buildTimeSystemMessage() });
  }
  messages.push(...history);

  state.lastMsgTime = Date.now();
  saveLocal();

  try{
    return await sendChatCompletion(messages);
  }catch(e){
    showToast(" " + e.message, true);
    return null;
  }
}

