// ===== 聊天气泡渲染 & 发送 =====
function escapeHtml(s){
  const div = document.createElement("div");
  div.textContent = s;
  return div.innerHTML;
}

function formatMsgTime(ts){
  if(!ts) return "";
  const d = new Date(ts);
  return String(d.getHours()).padStart(2,"0") + ":" + String(d.getMinutes()).padStart(2,"0");
}
function renderChatMessages(){
  const wrap = $("chatMsgs");
  if(!wrap) return;
  const p = window.currentChatPersona;
  const partnerAvatar = p && p.photo ? `<img src="${p.photo}">` : "";
  const selfAvatar = state.charAvatar ? `<img src="${state.charAvatar}">` : "";

  wrap.innerHTML = state.chatMessages.filter(m => !m.hiddenSystem).map((m, i) => {
    if(!m.id) m.id = "msg_" + (m.time || Date.now()) + "_" + i;

    if(m.recalled){
      const who = m.role === "user" ? "你" : ((p && p.name) || "对方");
      return `<div class="msg-row msg-recalled-row">
        <div style="width:100%;text-align:center">
          <div class="msg-recalled" onclick="toggleRecalledOriginal(${i})">
            ${escapeHtml(who)}撤回了一条消息
            <span class="msg-recalled-hint">点一下查看原文 · 仅自己可见</span>
          </div>
          <div class="msg-recalled-original" id="recalledOriginal_${i}">
            原文：${escapeHtml(m.originalContent || m.content || "")}
          </div>
        </div>
      </div>`;
    }

    const isMe = m.role === "user";
    const cls = isMe ? "bubble me" : "bubble ai";
    const rowCls = isMe ? "msg-row me" : "msg-row";
    const avatarHtml = `<div class="msg-avatar">${isMe ? selfAvatar : partnerAvatar}</div>`;
    const timeHtml = (state.showTimestamp && m.time) ? `<div class="msg-time">${formatMsgTime(m.time)}</div>` : "";
    const edited = m.edited ? `<span class="msg-edited">已编辑</span>` : "";
    const delivery = isMe ? `<span class="msg-delivery ${m.delivery || "sent"}">${deliveryText(m)}</span>` : "";
    const meta = (isMe || m.edited) ? `<div class="msg-meta-line">${delivery}${edited}</div>` : "";

    let bubbleHtml;
    if(m.type === "image"){
      bubbleHtml = `<div class="${cls}" data-msg-index="${i}"><img src="${m.content}"></div>`;
    }else{
      const speakBtn = m.role === "assistant"
        ? `<span class="bubble-speak" onclick="event.stopPropagation();speakMessage(${i})"></span>` : "";
      bubbleHtml = `<div class="${cls} ${m.type==="voice"?"bb-voice-msg":""}" data-msg-index="${i}" onclick="${m.type==="voice"?`toggleVoiceText(${i})`:``}">${escapeHtml(m.content)}${speakBtn}${m.type==="voice"?`<div class="bb-voice-text" id="bbVoiceText_${i}" style="display:none">${escapeHtml(m.text||m.content)}</div>`:``}</div>`;
    }

    return `${timeHtml}<div class="${rowCls}" data-msg-row="${i}">
      ${avatarHtml}
      <div class="msg-content-wrap">${bubbleHtml}${meta}</div>
    </div>`;
  }).join("");

  bindMessageGestures();
  wrap.scrollTop = wrap.scrollHeight;
}

