function importCurrentChat(input){
  if(!input.files || !input.files[0]) return;
  const id = state.activeChatId;
  if(!id){ showToast("请先进入一个聊天", true); return; }
  const reader = new FileReader();
  reader.onload = function(e){
    try{
      const data = JSON.parse(e.target.result);
      const msgs = Array.isArray(data.messages) ? data.messages : (Array.isArray(data) ? data : null);
      if(!msgs) throw new Error("格式不对");
      if(!state.chatRecords) state.chatRecords = {};
      state.chatRecords[id] = msgs;
      state.chatMessages = state.chatRecords[id];
      renderChatMessages();
      saveLocal();
      renderChatList();
      showToast("已导入");
    }catch(err){
      showToast("导入失败：" + err.message, true);
    }
  };
  reader.readAsText(input.files[0]);
  input.value = "";
}
function clearCurrentChatRecords(){
  const id = state.activeChatId;
  if(!id){ showToast("请先进入一个聊天", true); return; }
  if(!confirm("确定要清空当前聊天记录吗？此操作不可恢复。")) return;
  state.chatRecords[id] = [];
  state.chatMessages = state.chatRecords[id];
  renderChatMessages();
  saveLocal();
  renderChatList();
  closeChatSettings();
  showToast("已清空聊天记录");
}

function sendUserMessage(){
  const input = $("chatInputBox");
  const text = input.value.trim();
  if(!text) return;

  const pendingQuote = state.pendingQuotedMessage
    ? {
        id: state.pendingQuotedMessage.id || "",
        name: state.pendingQuotedMessage.name || "",
        text: state.pendingQuotedMessage.text || ""
      }
    : null;

  input.value = "";
  state.chatMessages.push({
    role:"user",
    type:"text",
    content:text,
    time:Date.now(),
    id:"msg_"+Date.now()+"_"+Math.random().toString(36).slice(2,7),
    delivery:"sending",
    replyTo:pendingQuote
  });

  if(pendingQuote){
    state.pendingQuotedMessage = null;
    document.getElementById("msgQuoteBar")?.classList.remove("show");
    document.getElementById("chatRoom")?.classList.remove("quote-active");
  }

  saveLocal();
  renderChatMessages();
  generateInnerVoiceForCurrentPersona();
}

// ===== 手动触发 AI 回复（发送后不再自动回复，需要点这个按键）=====
let aiReplyPending = false;
async function triggerAIReply(){
  if(aiReplyPending) return;
  if(!state.chatMessages || !state.chatMessages.length){
    showToast("先发一条消息吧", true);
    return;
  }
  aiReplyPending = true;
  const btn = $("chatReplyBtn");
  if(btn) btn.classList.add("loading");
  try{
    const reply = await requestChatReply();
    if(reply){
      state.chatMessages.push({ role:"assistant", type:"text", content:reply, time:Date.now() });
      saveLocal();
      renderChatMessages();
      if(typeof renderChatList==="function") renderChatList();
      if(typeof window.baobaoNotifyIncomingReply === "function"){
        window.baobaoNotifyIncomingReply(reply);
      }
    }
  } finally {
    aiReplyPending = false;
    if(btn) btn.classList.remove("loading");
  }
}

