// ===== 后端代理地址：部署后端后，把这里改成你的后端地址（不要带结尾斜杠） =====
// 例如本地: "http://localhost:3000"；线上: "https://your-backend.example.com"
window.BAOBAO_BACKEND = window.BAOBAO_BACKEND || "http://localhost:3000";

// ===== 生图 API：通过后端代理转发到 /images/generations，绕开浏览器CORS =====
async function generateImageFromAPI(prompt, apiOverride){
  const api = apiOverride || getImageAPI();
  if(!api.endpoint || !api.key){
    throw new Error("请先在「API 设置 → 生图 API」里填写接口地址和 Key");
  }
  const url = window.BAOBAO_BACKEND.replace(/\/$/, "") + "/api/image/generate";
  let res;
  try{
    res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        endpoint: api.endpoint,
        key: api.key,
        model: api.model || "dall-e-3",
        prompt,
        size: "1024x1024"
      })
    });
  }catch(e){
    throw new Error("请求失败，可能是网络问题或后端代理没启动");
  }
  const data = await res.json().catch(() => null);
  if(!res.ok){
    throw new Error((data && data.error) || `接口返回错误 ${res.status}`);
  }
  const item = data && data.data && data.data[0];
  if(!item) throw new Error("接口没有返回图片数据");
  if(item.url) return item.url;
  if(item.b64_json) return "data:image/png;base64," + item.b64_json;
  throw new Error("无法识别的返回格式");
}

async function runImageGeneration(promptText){
  showToast(" 正在生成图片…");
  try{
    const imgUrl = await generateImageFromAPI(promptText);
    state.chatMessages.push({ role:"user", type:"text", content:"[让AI画：" + promptText + "]", time:Date.now() });
    state.chatMessages.push({ role:"assistant", type:"image", content: imgUrl, time:Date.now() });
    saveLocal();
    renderChatMessages();
    showToast(" 图片已生成");
  }catch(e){
    showToast(" " + e.message, true);
  }
}

