// ===== 拉取模型列表（对话 / 生图，OpenAI 兼容的 GET /models） =====
async function fetchModelList(type){
  const wrap = $(type + "ModelPicker");
  if(wrap && wrap.innerHTML.trim()){
    wrap.innerHTML = "";
    showToast(" 已收起模型列表");
    return;
  }
  showToast(" 正在拉取模型列表…");
  try{
    let endpoint, key;
    if(type === "chatAPI"){ endpoint = $("chatEndpoint").value.trim(); key = $("chatApiKey").value.trim(); }
    if(type === "imageAPI"){ endpoint = $("imageEndpoint").value.trim(); key = $("imageApiKey").value.trim(); }
    if(!endpoint || !key){ throw new Error("请先填写接口地址和 Key"); }

    const url = window.BAOBAO_BACKEND.replace(/\/$/, "") + "/api/models?endpoint=" + encodeURIComponent(endpoint) + "&key=" + encodeURIComponent(key);
    const res = await fetch(url);
    const data = await res.json().catch(() => null);
    if(!res.ok){
      throw new Error((data && data.error) || `接口返回错误 ${res.status}`);
    }
    const list = data.data || data.models || [];
    const ids = list.map((m) => (typeof m === "string" ? m : (m.id || m.name))).filter(Boolean);
    if(ids.length === 0) throw new Error("没有拉取到模型，接口返回格式可能不兼容");
    renderModelPicker(type, ids);
    showToast(` 拉取到 ${ids.length} 个模型，点选一个`);
  }catch(e){
    showToast(" " + e.message, true);
  }
}
function renderModelPicker(type, ids){
  const wrap = $(type + "ModelPicker");
  if(!wrap) return;
  wrap.innerHTML = "";
  ids.forEach((id) => {
    const span = document.createElement("span");
    span.className = "preset-chip";
    span.textContent = id;
    span.addEventListener("click", () => pickModel(type, id));
    wrap.appendChild(span);
  });
}
function pickModel(type, id){
  if(type === "chatAPI") $("chatModel").value = id;
  if(type === "imageAPI") $("imageModel").value = id;
  if(type === "visionAPI") $("visionModel").value = id;
  const wrap = $(type + "ModelPicker");
  if(wrap) wrap.innerHTML = "";
  showToast(" 已选择模型：" + id);
}

