// ===== API 预设：同一类接口可以保存多套（比如"官方"和"中转站A"），随时切换 =====
function getPresets(type){
  try{ return JSON.parse(localStorage.getItem(type + "Presets") || "[]"); }
  catch(e){ return []; }
}
function savePresets(type, list){
  localStorage.setItem(type + "Presets", JSON.stringify(list));
}
function readFormValues(type){
  if(type === "chatAPI"){
    return {
      provider: $("chatProvider").value.trim(),
      key: $("chatApiKey").value.trim(),
      endpoint: $("chatEndpoint").value.trim(),
      model: $("chatModel").value.trim()
    };
  }
  if(type === "imageAPI"){
    return {
      provider: $("imageProvider").value.trim(),
      key: $("imageApiKey").value.trim(),
      endpoint: $("imageEndpoint").value.trim(),
      model: $("imageModel").value.trim()
    };
  }
  if(type === "minimaxAPI"){
    return {
      apiKey: $("minimaxApiKey").value.trim(),
      groupId: $("minimaxGroupId").value.trim(),
      model: $("minimaxModel").value.trim(),
      voiceId: $("minimaxVoiceId").value.trim()
    };
  }
  return {};
}
function applyPresetToForm(type, preset){
  if(type === "chatAPI"){
    $("chatProvider").value = preset.provider || "";
    $("chatApiKey").value = preset.key || "";
    $("chatEndpoint").value = preset.endpoint || "";
    $("chatModel").value = preset.model || "";
    saveChatAPI();
  }else if(type === "imageAPI"){
    $("imageProvider").value = preset.provider || "";
    $("imageApiKey").value = preset.key || "";
    $("imageEndpoint").value = preset.endpoint || "";
    $("imageModel").value = preset.model || "";
    saveImageAPI();
  }else if(type === "minimaxAPI"){
    $("minimaxApiKey").value = preset.apiKey || "";
    $("minimaxGroupId").value = preset.groupId || "";
    $("minimaxModel").value = preset.model || "";
    $("minimaxVoiceId").value = preset.voiceId || "";
    saveMinimaxAPI();
  }
  showToast(" 已切换到预设：" + preset.name);
}
function renderPresetChips(type){
  const wrap = $(type + "PresetList");
  if(!wrap) return;
  const list = getPresets(type);
  if(list.length === 0){
    wrap.innerHTML = `<div style="font-size:12px;color:#999">还没有保存的预设</div>`;
    return;
  }
  wrap.innerHTML = list.map((p, i) =>
    `<span class="preset-chip" onclick="applyPresetByIndex('${type}',${i})">${escapeHtml(p.name)}<b onclick="event.stopPropagation();deletePreset('${type}',${i})"></b></span>`
  ).join("");
}
function applyPresetByIndex(type, i){
  const list = getPresets(type);
  if(list[i]) applyPresetToForm(type, list[i]);
}
function deletePreset(type, i){
  const list = getPresets(type);
  list.splice(i, 1);
  savePresets(type, list);
  renderPresetChips(type);
  showToast(" 已删除预设");
}
function openSavePresetEdit(type){
  openTextEdit({
    mode: "preset_" + type,
    title: "保存为预设",
    label1: "给这套配置起个名字（如：官方 / 中转站A）",
    value1: ""
  });
}

// ===== 锁屏密码键盘 =====
let passcodeBuffer = "";
function showPasscodePad(){
  passcodeBuffer = "";
  renderPasscodeDots();
  $("passcodeOverlay").classList.add("show");
}
function hidePasscodePad(e){
  if(e) e.stopPropagation();
  $("passcodeOverlay").classList.remove("show");
  passcodeBuffer = "";
}
function renderPasscodeDots(){
  document.querySelectorAll("#passcodeDots .passcode-dot").forEach((d, i) => {
    d.classList.toggle("filled", i < passcodeBuffer.length);
    d.classList.remove("error");
  });
}
function passcodeInput(digit){
  if(passcodeBuffer.length >= 4) return;
  passcodeBuffer += digit;
  renderPasscodeDots();
  if(passcodeBuffer.length === 4){
    setTimeout(checkPasscode, 150);
  }
}
function passcodeBackspace(){
  passcodeBuffer = passcodeBuffer.slice(0, -1);
  renderPasscodeDots();
}
function checkPasscode(){
  if(passcodeBuffer === (state.lockPassword || "0601")){
    $("passcodeOverlay").classList.remove("show");
    passcodeBuffer = "";
    unlockReal();
  }else{
    document.querySelectorAll("#passcodeDots .passcode-dot").forEach((d) => d.classList.add("error"));
    showToast(" 密码错误", true);
    setTimeout(() => {
      passcodeBuffer = "";
      renderPasscodeDots();
    }, 350);
  }
}

