// ===== 初始化 =====
function restoreScreenMode(){
  const mode = localStorage.getItem("screenMode");
  if(mode === "full"){
    document.body.classList.add("fullscreen-mode");
    const phone = document.querySelector(".phone");
    phone.style.width = "100vw";
    phone.style.height = "100dvh";
    phone.style.border = "0";
    phone.style.borderRadius = "0";
  }
  syncFullScreenToggle();
}

let bbStartupDoneV285 = false;
function bbSafeStartupCallV285(fn){
  try{ if(typeof fn === "function") fn(); }catch(error){ console.warn("豹豹机启动步骤已跳过", error); }
}
function bbIdleV285(fn, timeout){
  if(typeof requestIdleCallback === "function"){
    requestIdleCallback(function(){ bbSafeStartupCallV285(fn); },{timeout:timeout||900});
  }else{
    setTimeout(function(){ bbSafeStartupCallV285(fn); },Math.min(timeout||350,500));
  }
}
function init(){
  if(bbStartupDoneV285)return;
  bbStartupDoneV285 = true;

  // 第一阶段：只做锁屏和解锁真正需要的内容，让桌面版尽快可操作。
  bbSafeStartupCallV285(restoreScreenMode);
  bbSafeStartupCallV285(updateTime);
  setInterval(function(){ bbSafeStartupCallV285(updateTime); },1000);
  bbSafeStartupCallV285(renderWallpaper);
  bbSafeStartupCallV285(renderAvatar);
  bbSafeStartupCallV285(initLockSwipe);
  bbSafeStartupCallV285(initSwipe);

  // 第二阶段：下一帧补齐桌面，避免和锁屏首帧争抢。
  requestAnimationFrame(function(){
    bbSafeStartupCallV285(renderIns);
    bbSafeStartupCallV285(renderPages);
    bbSafeStartupCallV285(syncTimeAwareToggle);
    requestAnimationFrame(function(){ bbSafeStartupCallV285(renderProfile); });
  });

  // 第三阶段：隐藏页面按空闲时间准备。聊天记录不再在启动时全部绘制。
  bbIdleV285(applyChatBackground,700);
}

document.addEventListener("DOMContentLoaded", init,{once:true});


