async function aiGenerateBriefPersona(){
  const name = $("archiveNameInput").value.trim();
  const persona = $("archivePersonaTextarea").value.trim();
  const personality = $("archivePersonalityTextarea").value.trim();
  if(!persona && !personality){
    showToast(" 请先填写 PERSONA / TRAITS 或 PERSONALITY 再生成简介", true);
    return;
  }
  showToast(" 正在生成简量人设…");
  try{
    const reply = await sendChatCompletion([
      { role: "system", content: "你是一个角色设定压缩助手，请把用户提供的角色背景与性格信息，压缩成100~200字的中文「简量人设」，用于注入给同世界观中与该角色有关系的其他角色，帮助对方提到TA时不会OOC（不出戏）。只输出压缩后的简介正文，不要输出任何解释、标题或引号。" },
      { role: "user", content: `角色名/代号：${name || "（未命名）"}\n背景/人设：${persona || "（无）"}\n性格：${personality || "（无）"}` }
    ]);
    $("archiveBriefTextarea").value = reply;
    showToast(" 简量人设已生成");
  }catch(e){
    showToast(" " + e.message, true);
  }
}

