function renderContactsQuickRow(){
  const row = $("contactsQuickRow");
  if(!row) return;
  const maxPersonasInRow = 2;
  const shown = state.personas.slice(0, maxPersonasInRow);
  const overflow = state.personas.slice(maxPersonasInRow);

  const defaultAvatarHtml = state.charAvatar ? `<img src="${state.charAvatar}">` : "";
  let html = `<div class="contacts-quick-item">
    <div class="contacts-quick-avatar" id="contactsQuickAvatar" onclick="triggerWechatAvatarUpload(event)" style="cursor:pointer">${defaultAvatarHtml}</div>
    <div class="contacts-quick-name">&nbsp;</div>
  </div>`;

  html += shown.map(p => {
    const avatarHtml = p.photo ? `<img src="${p.photo}">` : "";
    return `<div class="contacts-quick-item">
      <div class="contacts-quick-avatar persona-quick-avatar" onclick="openEditPersonaPanel('${p.id}')">${avatarHtml}</div>
      <div class="contacts-quick-name">${escapeHtml(p.name || "")}</div>
    </div>`;
  }).join("");

  html += `<div class="contacts-quick-item">
    <div class="contacts-add-circle" onclick="openCreatePersonaPanel()">＋</div>
    <div class="contacts-quick-name">&nbsp;</div>
  </div>`;

  row.innerHTML = html;

  const listWrap = $("archiveContactList");
  if(listWrap){
    if(!overflow.length){
      listWrap.innerHTML = "";
    }else{
      const label = `<div class="contacts-group-label">更多联系人</div>`;
      const rows = overflow.map(p => {
        const avatarHtml = p.photo ? `<img src="${p.photo}">` : "";
        return `<div class="contacts-list-item" onclick="openEditPersonaPanel('${p.id}')">
          <div class="contacts-list-avatar">${avatarHtml}</div>
          <div class="contacts-list-name">${escapeHtml(p.name || "未命名")}</div>
        </div>`;
      }).join("");
      listWrap.innerHTML = label + rows;
    }
  }
}

function savePersonaArchive(){
  const name = $("archiveNameInput").value.trim();
  if(!name){
    showToast(" 请先填写 Name or Codename", true);
    return;
  }
  const data = {
    name,
    photo: archivePendingPhoto,
    tags: [...archiveTempTags],
    timezone: $("archiveTimezoneInput").value.trim() || "SYSTEM",
    persona: $("archivePersonaTextarea").value,
    personality: $("archivePersonalityTextarea").value,
    brief: $("archiveBriefTextarea").value,
    chatStyleMode: $("archiveChatStyleMode") ? $("archiveChatStyleMode").value : "auto",
    updatedAt: formatArchiveDate()
  };

  if(archiveEditingId){
    const p = state.personas.find(x => x.id === archiveEditingId);
    if(p) Object.assign(p, data);
  }else{
    const wechat = $("archiveWechatValue").textContent;
    const charId = state.personaIdCounter;
    state.personaIdCounter = charId + 1;
    state.personas.push({
      id: "persona_" + Date.now(),
      charId,
      wechat,
      ...data
    });
  }
  const savedPersona = state.personas.find(x => x.id === archiveEditingId) || state.personas[state.personas.length - 1] || null;
  if(savedPersona && String(state.activeChatId || "") === String(savedPersona.id || "")){
    window.currentChatPersona = savedPersona;
    state.currentChatPersona = savedPersona;
  }
  if(savedPersona){
    const cacheKey = String(savedPersona.id || savedPersona.name || "");
    ["hceProfiles","hceEmotion","hceRelationship","hceRuntime"].forEach(storeName => {
      if(state[storeName] && cacheKey) delete state[storeName][cacheKey];
    });
  }
  saveLocal();
  renderContactsQuickRow();
  showToast(" 人设已保存并重新读取");
  closeArchivePanel();
}

function deletePersonaArchive(){
  if(!archiveEditingId) return;
  state.personas = state.personas.filter(x => x.id !== archiveEditingId);
  saveLocal();
  renderContactsQuickRow();
  showToast(" 人设已删除");
  closeArchivePanel();
}

// ===== 人设文件导入（JSON 人设文件 / 简易角色卡） =====
function closeAntiReconBeforePersonaImport(){
  const ids = ["antiReconOverlay","antiReconV2","antiReconV2Settings","antiReconV3Night","antiReconV3Log"];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if(!el) return;
    el.classList.remove("show");
    if(id === "antiReconOverlay") el.style.display = "none";
  });
}
function triggerPersonaImport(e){
  if(e){
    e.preventDefault();
    e.stopPropagation();
    if(e.stopImmediatePropagation) e.stopImmediatePropagation();
  }
  closeAntiReconBeforePersonaImport();
  const input = $("personaImportInput");
  if(input) input.click();
  return false;
}
function personaImportChosen(input){
  closeAntiReconBeforePersonaImport();
  if(!input.files || !input.files[0]) return;
  const file = input.files[0];
  const reader = new FileReader();
  reader.onload = (e) => {
    let raw;
    try{
      raw = JSON.parse(e.target.result);
    }catch(err){
      showToast(" 导入失败：不是有效的 JSON 人设文件", true);
      input.value = "";
      return;
    }
    applyImportedPersonaData(raw);
    showToast(" 人设已导入，请检查内容后点「保存人设」");
    input.value = "";
  };
  reader.onerror = () => { showToast(" 文件读取失败", true); input.value = ""; };
  reader.readAsText(file);
}
function applyImportedPersonaData(raw){
  // 兼容 {spec:"chara_card_v2", data:{...}} 结构，以及本项目自己导出的扁平结构
  const d = (raw && raw.data && typeof raw.data === "object") ? raw.data : raw;
  const name = d.name || d.char_name || d.codename || "";
  const joinUnique = (...values) => [...new Set(values.flatMap(value => Array.isArray(value) ? value : [value]).map(value => String(value || "").trim()).filter(Boolean))].join("\n\n");
  const persona = joinUnique(d.persona, d.description, d.background, d.scenario);
  const personality = joinUnique(d.personality, d.traits);
  const brief = joinUnique(
    d.brief, d.brief_persona, d.creator_notes, d.system_prompt,
    d.post_history_instructions,
    d.mes_example ? "【对话示例】\n" + d.mes_example : "",
    d.first_mes ? "【初始消息参考】\n" + d.first_mes : ""
  );
  const timezone = d.timezone || "SYSTEM";
  const photo = d.photo || d.avatar || null;
  let tags = d.tags || d.tag || [];
  if(!Array.isArray(tags)) tags = String(tags).split(/[,，]/).map(s => s.trim()).filter(Boolean);

  if(name) $("archiveNameInput").value = name;
  if(persona) $("archivePersonaTextarea").value = persona;
  if(personality) $("archivePersonalityTextarea").value = personality;
  if(brief) $("archiveBriefTextarea").value = brief;
  $("archiveTimezoneInput").value = timezone;
  if(tags.length){
    archiveTempTags = tags.map(String);
    renderArchiveTags();
  }
  if(photo){
    archivePendingPhoto = photo;
    $("archivePhotoBox").innerHTML = `<img src="${photo}">`;
  }
}

