let customFontData = localStorage.getItem("customFontData") || "";
let customFontUrl = localStorage.getItem("customFontUrl") || "";

function applyCustomFont(src){
  let style=document.getElementById("customFontStyle");
  if(!style){
    style=document.createElement("style");
    style.id="customFontStyle";
    document.head.appendChild(style);
  }
  style.innerHTML=`@font-face{font-family:CustomFont;src:url("${src}")}*{font-family:CustomFont,-apple-system,BlinkMacSystemFont,sans-serif!important;}`;
}


function openFontPicker(){
  const input=document.getElementById("fontFileInput");
  if(input) input.click();
}


async function openFontPicker(){
  const input=document.getElementById("fontFileInput");
  if(input) input.click();
}

async function fontFileChosen(input){
  if(!input.files || !input.files[0]) return;
  const file=input.files[0];

  if(file.size > 30 * 1024 * 1024){
    if(typeof showToast==="function") showToast(" 字体文件超过30MB", true);
    return;
  }

  try{
    await saveBigFont(file);
    const url=URL.createObjectURL(file);
    applyCustomFont(url);
    localStorage.setItem("customFontInstalled","indexeddb");
    if(typeof showToast==="function") showToast(" 字体导入成功");
  }catch(e){
    console.error(e);
    if(typeof showToast==="function") showToast(" 字体保存失败", true);
  }
}

function applyFontSetting(){
  const url=document.getElementById("fontUrlInput").value.trim();
  if(url){
    localStorage.setItem("customFontUrl",url);
    applyCustomFont(url);
  }else if(customFontData){
    applyCustomFont(customFontData);
  }
  if(typeof showToast==="function") showToast(" 字体已应用");
}

function resetFontSetting(){
  localStorage.removeItem("customFontData");
  localStorage.removeItem("customFontUrl");
  const style=document.getElementById("customFontStyle");
  if(style) style.remove();
  if(typeof showToast==="function") showToast("已恢复默认字体");
}

window.addEventListener("load",()=>{
  let u=localStorage.getItem("customFontUrl");
  let d=localStorage.getItem("customFontData");
  if(u) applyCustomFont(u);
  else if(d) applyCustomFont(d);
});
