/* v28 字体大文件存储 */
const FONT_DB_NAME="baobaoFontDB";
const FONT_STORE="fonts";

function openFontDB(){
 return new Promise((resolve,reject)=>{
  const req=indexedDB.open(FONT_DB_NAME,1);
  req.onupgradeneeded=e=>{
   const db=e.target.result;
   if(!db.objectStoreNames.contains(FONT_STORE)){
    db.createObjectStore(FONT_STORE);
   }
  };
  req.onsuccess=e=>resolve(e.target.result);
  req.onerror=e=>reject(e);
 });
}

async function saveBigFont(file){
 const db=await openFontDB();
 return new Promise((resolve,reject)=>{
  const tx=db.transaction(FONT_STORE,"readwrite");
  tx.objectStore(FONT_STORE).put(file,"currentFont");
  tx.oncomplete=resolve;
  tx.onerror=reject;
 });
}

async function loadBigFont(){
 const db=await openFontDB();
 return new Promise((resolve,reject)=>{
  const tx=db.transaction(FONT_STORE,"readonly");
  const req=tx.objectStore(FONT_STORE).get("currentFont");
  req.onsuccess=()=>resolve(req.result);
  req.onerror=reject;
 });
}

async function deleteBigFont(){
 const db=await openFontDB();
 const tx=db.transaction(FONT_STORE,"readwrite");
 tx.objectStore(FONT_STORE).delete("currentFont");
}
