(function(){
 const oldStart=window.startPersonaChat;
 window.startPersonaChat=function(id){
   const p=(state.personas||[]).find(x=>String(x.id)===String(id));
   if(!p)return;
   window.currentChatPersona=p;
   state.activeChatId=p.id;
   if(!state.chatRecords) state.chatRecords={};
   if(!state.chatRecords[p.id]) state.chatRecords[p.id]=[];
   state.chatMessages=state.chatRecords[p.id];
   if(typeof touchChatOrder==='function') touchChatOrder(p.id);
   if(typeof saveLocal==='function')saveLocal();
   if(typeof updateChatHead==='function') updateChatHead(p);
   document.getElementById('personaSelectPanel').style.display='none';
   document.getElementById('chatDemo').style.display='none';
   document.getElementById('chatRoom').style.display='block';
   renderChatMessages();
   requestAnimationFrame(function(){
     const wrap=document.getElementById('chatMsgs');
     if(wrap) wrap.scrollTop=wrap.scrollHeight;
   });
   if(typeof renderChatList==='function') renderChatList();
 };
 const oldSend=window.sendUserMessage;
 window.sendUserMessage=function(){
   if(!state.activeChatId)return oldSend&&oldSend();
   const input=document.getElementById('chatInputBox');
   const t=input&&input.value.trim();
   if(!t)return;
   if(!state.chatRecords)state.chatRecords={};
   if(!state.chatRecords[state.activeChatId])state.chatRecords[state.activeChatId]=[];
   const pendingQuote=state.pendingQuotedMessage
     ?{
        id:state.pendingQuotedMessage.id||'',
        name:state.pendingQuotedMessage.name||'',
        text:state.pendingQuotedMessage.text||''
      }
     :null;

   state.chatRecords[state.activeChatId].push({
     role:'user',
     type:'text',
     content:t,
     time:Date.now(),
     id:'msg_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),
     delivery:'sending',
     replyTo:pendingQuote
   });

   state.chatMessages=state.chatRecords[state.activeChatId];
   input.value='';

   if(pendingQuote){
     state.pendingQuotedMessage=null;
     document.getElementById('msgQuoteBar')?.classList.remove('show');
     document.getElementById('chatRoom')?.classList.remove('quote-active');
   }
   if(typeof touchChatOrder==='function') touchChatOrder(state.activeChatId);
   renderChatMessages();
   if(typeof saveLocal==='function')saveLocal();
   if(typeof renderChatList==='function') renderChatList();
   renderWeChatApp&&renderWeChatApp();
 };
 window.closeChatRoom=function(){
   document.getElementById('chatRoom').style.display='none';
   document.getElementById('chatDemo').style.display='block';
   renderWeChatApp&&renderWeChatApp();
 };
})();
