/* baobao-msg-quote-favorite-v1 */
(function(){
  "use strict";

  const oldCustom = window.customBubble;
  if(typeof oldCustom === "function" && !oldCustom.__quoteWrapped){
    const wrapped = function(m){
      let html = oldCustom(m);
      if(m && m.replyTo && m.replyTo.text){
        const head = '<div class="bb-msg-quote"><div class="bb-msg-quote-name">'
          + escapeHtml(m.replyTo.name || '')
          + '</div><div class="bb-msg-quote-text">'
          + escapeHtml(m.replyTo.text || '')
          + '</div></div>';
        html = head + html;
      }
      return html;
    };
    wrapped.__quoteWrapped = true;
    window.customBubble = wrapped;
  }

  const oldSend = window.sendUserMessage;
  if(typeof oldSend === "function" && !oldSend.__quoteFavoriteWrapped){
    const wrapped = function(){
      const before = Array.isArray(state.chatMessages) ? state.chatMessages.length : 0;
      const result = oldSend.apply(this, arguments);
      const after = Array.isArray(state.chatMessages) ? state.chatMessages.length : 0;

      if(after > before && state.pendingQuotedMessage){
        const msg = state.chatMessages[after - 1];
        if(msg && msg.role === "user"){
          msg.replyTo = {
            id: state.pendingQuotedMessage.id,
            name: state.pendingQuotedMessage.name,
            text: state.pendingQuotedMessage.text
          };
          if(typeof persist === "function") persist();
          if(typeof renderChatMessages === "function") renderChatMessages();
        }
        state.pendingQuotedMessage = null;
        document.getElementById("msgQuoteBar")?.classList.remove("show");
      }
      return result;
    };
    wrapped.__quoteFavoriteWrapped = true;
    window.sendUserMessage = wrapped;
  }

  document.addEventListener("DOMContentLoaded", ()=>{
    const bar = document.getElementById("msgQuoteBar");
    const inputBar = document.querySelector("#chatRoom .chat-input-bar");
    if(bar && inputBar && bar.parentNode !== inputBar.parentNode){
      inputBar.parentNode.insertBefore(bar, inputBar);
    }
  });
})();
;

