/* baobao-vision-recognition */
(function(){
  // 调用后端代理，让视觉模型描述一张图片
  window.baobaoRecognizeImage = function(msg){
    if(!msg || msg._visionPromise) return msg && msg._visionPromise;
    msg._visionPromise = (async () => {
      try{
        const api = typeof getChatAPI === "function" ? getChatAPI() : null;
        if(!api || api.enableImageRecognition === false) return;
        if(!api.visionModel || !api.endpoint || !api.key) return;
        const url = (window.BAOBAO_BACKEND || "http://localhost:3000").replace(/\/$/, "") + "/api/vision/recognize";
        const res = await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            endpoint: api.endpoint,
            key: api.key,
            model: api.visionModel,
            imageDataUrl: msg.content
          })
        });
        const data = await res.json().catch(() => null);
        if(res.ok && data && data.description){
          msg.visionDesc = data.description;
          if(typeof persist === "function") persist();
        }
      }catch(e){
        // 识别失败就静默放弃，AI退化成"看不懂图片"，不影响正常聊天
      }
    })();
    return msg._visionPromise;
  };

  // 包一层 requestChatReply：临时把图片消息替换成文字描述，请求完再还原
  const oldRequest = window.requestChatReply;
  if(typeof oldRequest === "function" && !oldRequest.__visionWrapped){
    const wrapped = async function(){
      const arr = (window.state && state.chatMessages) || [];
      const pendingImgs = arr.filter(m => m.type === "image" && m._visionPromise && !m.visionDesc);
      if(pendingImgs.length){
        await Promise.race([
          Promise.all(pendingImgs.map(m => m._visionPromise)),
          new Promise(r => setTimeout(r, 4000)) // 最多等4秒，避免识别慢卡住回复
        ]);
      }
      const backup = arr.map(m => ({ type: m.type, content: m.content }));
      arr.forEach(m => {
        if(m.type === "image"){
          m.type = "text";
          m.content = m.visionDesc ? ("[图片，识别到的内容：" + m.visionDesc + "]") : "[发来一张图片，暂未识别出内容]";
        }
      });
      try{
        return await oldRequest.apply(this, arguments);
      } finally {
        arr.forEach((m, i) => { m.type = backup[i].type; m.content = backup[i].content; });
      }
    };
    wrapped.__visionWrapped = true;
    if(window.__bbPersonaCoreReadyV391)return;
    window.requestChatReply = wrapped;
  }
})();
;

/* baobao-gemini-final-fix */
(function(){
  const oldSend = window.sendChatCompletion;
  window.sendChatCompletion = async function(messages, apiOverride){
    const api = apiOverride || (typeof getChatAPI==="function" ? getChatAPI() : {});
    if(!api.endpoint || !api.key) return oldSend.apply(this, arguments);

    if(api.endpoint.includes("generativelanguage.googleapis.com")){
      const base = api.endpoint.replace(/\/$/,"");
      const model = api.model || "gemini-2.5-flash";
      const url = base + "/models/" + model + ":generateContent?key=" + encodeURIComponent(api.key);
      const contents = (messages||[]).map(m=>({
        role:m.role==="assistant"?"model":"user",
        parts:[{text:String(m.content||"")}]
      }));
      const res = await fetch(url,{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({
          contents,
          generationConfig:{
            temperature:Number(api.temperature ?? 0.75),
            maxOutputTokens:1200
          }
        })
      });
      if(!res.ok){
        throw new Error("Gemini接口错误 "+res.status+"："+(await res.text()).slice(0,120));
      }
      const data = await res.json();
      return data?.candidates?.[0]?.content?.parts?.map(p=>p.text||"").join("") || "";
    }

    return oldSend.apply(this, arguments);
  };
})();
;

/* baobao-cn-relay-final-v153 */
(function(){
  'use strict';
  const $id=(id)=>document.getElementById(id);
  const normalizeBase=(v)=>{
    let s=String(v||'').trim().replace(/\/+$/,'');
    if(!s) return '';
    if(!/\/v\d+(?:beta\d+)?$/i.test(s) && !/\/openai$/i.test(s)) s += '/v1';
    return s;
  };
  const parseText=(data)=>{
    const choice=data?.choices?.[0]||{};
    const message=choice?.message||{};
    let c=
      message?.content ??
      choice?.text ??
      data?.output_text ??
      data?.response ??
      data?.result ??
      data?.text ??
      data?.data?.content ??
      data?.data?.text ??
      '';

    if(Array.isArray(c)){
      c=c.map(x=>{
        if(typeof x==='string')return x;
        return x?.text?.value||x?.text||x?.content||x?.value||'';
      }).join('');
    }else if(c&&typeof c==='object'){
      c=c?.text?.value||c?.text||c?.content||c?.value||'';
    }

    // 某些中转站把最终文本放在 output 数组中。
    if(!String(c||'').trim()&&Array.isArray(data?.output)){
      c=data.output.flatMap(x=>Array.isArray(x?.content)?x.content:[])
        .map(x=>x?.text||x?.value||'')
        .join('');
    }

    return String(c||'').trim();
  };
  const currentConfig=()=>{
    let api={}, imageApi={};
    try{ api=JSON.parse(localStorage.getItem('chatAPI')||'{}'); }catch(e){}
    try{ imageApi=JSON.parse(localStorage.getItem('imageAPI')||'{}'); }catch(e){}
    api.endpoint=normalizeBase(api.endpoint);
    api.temperature=Number.isFinite(Number(api.temperature))?Number(api.temperature):0.7;
    api.visionModel=imageApi.visionModel||api.visionModel||api.model||'';
    api.visionEndpoint=normalizeBase(imageApi.endpoint||api.endpoint);
    api.visionKey=imageApi.key||api.key||'';
    return api;
  };

  // 保存时只使用一个中转站配置；聊天和识图共用同一地址、Key、模型。
  window.saveChatAPI=function(){
    const api={
      provider:($id('chatProvider')?.value||'中转站').trim(),
      key:($id('chatApiKey')?.value||'').trim(),
      endpoint:normalizeBase($id('chatEndpoint')?.value||''),
      model:($id('chatModel')?.value||'').trim(),
      visionModel:($id('chatModel')?.value||'').trim(),
      temperature:Number($id('chatTemperature')?.value||0.7),
      enableEmojiRecognition:$id('emojiRecognitionToggle')?.checked!==false,
      enableImageRecognition:$id('imageRecognitionToggle')?.checked!==false
    };
    localStorage.setItem('chatAPI',JSON.stringify(api));
    if($id('chatEndpoint')) $id('chatEndpoint').value=api.endpoint;
    if(typeof showToast==='function') showToast(' 中转站 API 已保存');
  };

  // 统一的 OpenAI 兼容聊天请求，不再走 Gemini 官方原生地址。
  window.sendChatCompletion=async function(messages,apiOverride){
    const api=Object.assign({},currentConfig(),apiOverride||{});
    api.endpoint=normalizeBase(api.endpoint);
    if(!api.endpoint||!api.key||!api.model) throw new Error('请先填写 API 地址、API Key 和模型');
    let res;
    try{
      res=await fetch(api.endpoint+'/chat/completions',{
        method:'POST',
        headers:{'Content-Type':'application/json','Authorization':'Bearer '+api.key},
        body:JSON.stringify({
          model:api.model,
          messages:Array.isArray(messages)?messages:[],
          temperature:Number.isFinite(Number(api.temperature))?Number(api.temperature):0.7,
          max_tokens:Number(apiOverride&&(apiOverride.max_tokens||apiOverride.maxTokens))||3000,
          stream:false
        })
      });
    }catch(e){
      throw new Error('连接失败：请检查网络、API 地址或中转站是否允许浏览器访问');
    }
    const raw=await res.text();
    let data={};
    try{data=raw?JSON.parse(raw):{};}catch(e){}
    if(!res.ok) throw new Error((data?.error?.message||data?.message||raw||('接口错误 '+res.status)).slice(0,220));
    const text=parseText(data);
    if(!text) throw new Error('接口返回了空内容，请更换模型或检查中转站兼容性');
    return text;
  };

  // 直接从用户填写的中转站 GET /models，不再依赖单独后端。
  window.fetchModelList=async function(type){
    const wrap=$id(type+'ModelPicker');
    if(wrap&&wrap.innerHTML.trim()){
      wrap.innerHTML='';
      if(typeof showToast==='function')showToast(' 已收起模型列表');
      return;
    }

    let endpoint='',key='';
    if(type==='chatAPI'){
      endpoint=normalizeBase($id('chatEndpoint')?.value||'');
      key=($id('chatApiKey')?.value||'').trim();
    }else{
      endpoint=normalizeBase($id('imageEndpoint')?.value||'');
      key=($id('imageApiKey')?.value||'').trim();
    }

    if(!endpoint||!key){
      if(typeof showToast==='function')showToast(' 请先填写 API 地址和 Key',true);
      return;
    }

    if(typeof showToast==='function')showToast(type==='visionAPI'?' 正在拉取识图模型…':' 正在拉取模型…');

    try{
      const res=await fetch(endpoint+'/models',{
        headers:{'Authorization':'Bearer '+key,'Accept':'application/json'}
      });
      const raw=await res.text();
      let data={};
      try{data=JSON.parse(raw)}catch(e){}
      if(!res.ok) throw new Error(data?.error?.message||data?.message||raw||('接口错误 '+res.status));

      const list=data?.data||data?.models||data?.result||[];
      let ids=(Array.isArray(list)?list:[])
        .map(m=>typeof m==='string'?m:(m?.id||m?.name||m?.model))
        .filter(Boolean);

      if(!ids.length) throw new Error('没有获取到模型列表');

      ids=[...new Set(ids)];

      if(type==='visionAPI'){
        const visionPattern=/(^|[-_.])(mm|vl|vision|visual)([-_.]|$)|gemini|gpt-4o|gpt-4\.1|qwen.*vl|glm.*v/i;
        const likely=ids.filter(id=>visionPattern.test(String(id)));
        const others=ids.filter(id=>!visionPattern.test(String(id)));
        ids=likely.concat(others);
      }

      if(typeof renderModelPicker==='function'){
        renderModelPicker(type,ids);
      }else if(wrap){
        wrap.innerHTML=ids.map(id=>'<span class="preset-chip">'+String(id).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]))+'</span>').join('');
      }

      if(typeof showToast==='function'){
        showToast(type==='visionAPI'
          ? ' 已拉取 '+ids.length+' 个模型，可能支持识图的已排在前面'
          : ' 已拉取 '+ids.length+' 个模型');
      }
    }catch(e){
      if(typeof showToast==='function')showToast(' '+e.message,true);
    }
  };

  window.testChatAPI=function(){
    const api={endpoint:normalizeBase($id('chatEndpoint')?.value||''),key:($id('chatApiKey')?.value||'').trim(),model:($id('chatModel')?.value||'').trim(),temperature:Number($id('chatTemperature')?.value||0.7)};
    if(typeof showToast==='function')showToast(' 正在测试中转站…');
    window.sendChatCompletion([{role:'user',content:'回复“连接成功”四个字。'}],api)
      .then(r=>{if(typeof showToast==='function')showToast(' '+r.slice(0,30));})
      .catch(e=>{if(typeof showToast==='function')showToast(' '+e.message,true);});
  };

  // 图片识别也走同一个中转站的 /chat/completions 多模态格式。
  window.baobaoRecognizeImage=function(msg){
    if(!msg||msg._visionPromise) return msg&&msg._visionPromise;
    msg._visionPromise=(async()=>{
      const api=currentConfig();
      if(api.enableImageRecognition===false||!api.endpoint||!api.key||!api.model||!msg.content) return;
      try{
        const visionEndpoint=api.visionEndpoint||api.endpoint;
        const visionKey=api.visionKey||api.key;
        const res=await fetch(visionEndpoint+'/chat/completions',{
          method:'POST',
          headers:{'Content-Type':'application/json','Authorization':'Bearer '+visionKey},
          body:JSON.stringify({
            model:api.visionModel||api.model,
            messages:[{role:'user',content:[
              {type:'text',text:'请简洁描述这张图片的主体、动作、场景、文字和情绪，供聊天角色理解。不要编造看不到的内容。'},
              {type:'image_url',image_url:{url:msg.content}}
            ]}],
            temperature:0.2,
            max_tokens:500,
            stream:false
          })
        });
        const raw=await res.text();let data={};try{data=JSON.parse(raw)}catch(e){}
        if(!res.ok) throw new Error(data?.error?.message||raw||'识图失败');
        const text=parseText(data);
        if(text){msg.visionDesc=text;if(typeof persist==='function')persist();if(typeof saveLocal==='function')saveLocal();}
      }catch(e){msg.visionError=String(e.message||e);}
    })();
    return msg._visionPromise;
  };

  // 打开 API 页面时给地址自动补 /v1，并提示聊天和识图共用一套配置。
  document.addEventListener('DOMContentLoaded',()=>{
    const title=document.querySelector('#chatAPI h1');if(title)title.textContent='API 设置';
    const hint=document.querySelector('#chatAPI h1 + div');if(hint)hint.textContent='填写中国可用的 OpenAI 兼容中转站；聊天、拉取模型和识图共用这一套配置。';
    const provider=$id('chatProvider');if(provider&&!provider.value)provider.value='中转站';
    const ep=$id('chatEndpoint');if(ep)ep.placeholder='https://你的中转站地址/v1';
    const model=$id('chatModel');if(model)model.placeholder='先拉取模型，再选择或填写';
    const imageRow=document.querySelector('[data-label="生图/视觉 API"]');if(imageRow)imageRow.style.display='none';
  });
})();
;

/* bb-anti-recon-final-button-fix */
(function(){
  'use strict';
  const shield='<svg viewBox="0 0 24 24"><path d="M12 3 20 6v5c0 5.1-3.2 8.4-8 10-4.8-1.6-8-4.9-8-10V6z"/><path d="M9.2 12.2 11 14l4-4"/></svg>';

  function ensureAntiReconButton(){
    const grid=document.querySelector('#bbToolSheet .bb-tool-grid');
    if(!grid || grid.querySelector('.bb-anti-recon-tool')) return;
    const item=document.createElement('div');
    item.className='bb-tool-item bb-anti-recon-tool';item.dataset.bbReconEntry='1';
    item.innerHTML='<div class="bb-tool-icon">'+shield+'</div>反侦察';
    item.dataset.bbReconEntry='1';
    item.onclick=function(e){
      return window.baobaoOpenAntiReconExplicit(this,e);
    };
    grid.appendChild(item);
  }

  function watchGrid(){
    const grid=document.querySelector('#bbToolSheet .bb-tool-grid');
    if(!grid || grid.__antiReconWatched) return;
    grid.__antiReconWatched=true;
    new MutationObserver(function(){ensureAntiReconButton()}).observe(grid,{childList:true});
  }

  document.addEventListener('DOMContentLoaded',function(){
    ensureAntiReconButton();
    watchGrid();
    setTimeout(function(){ensureAntiReconButton();watchGrid()},600);
    setTimeout(function(){ensureAntiReconButton();watchGrid()},1800);
  });

  const oldOpenTools=window.openTools;
  window.openTools=function(){
    ensureAntiReconButton();
    const result=oldOpenTools&&oldOpenTools.apply(this,arguments);
    requestAnimationFrame(function(){ensureAntiReconButton();watchGrid()});
    return result;
  };

  setTimeout(function(){ensureAntiReconButton();watchGrid()},2800);
})();
;

/* bb-persona-import-anti-recon-guard */
(function(){
  "use strict";

  function personaArchiveVisible(){
    const panel=document.getElementById("personaArchive");
    return !!panel && getComputedStyle(panel).display!=="none";
  }

  function closeReconGhosts(){
    ["antiReconOverlay","antiReconV2","antiReconV2Settings","antiReconV3Night","antiReconV3Log"].forEach(function(id){
      const el=document.getElementById(id);
      if(!el)return;
      el.classList.remove("show");
      if(id==="antiReconOverlay")el.style.display="none";
    });
  }

  function guardOpenAntiRecon(){
    const current=window.openAntiRecon;
    if(typeof current!=="function" || current.__personaImportGuarded)return;
    const wrapped=function(){
      if(personaArchiveVisible()){
        closeReconGhosts();
        return false;
      }
      return current.apply(this,arguments);
    };
    wrapped.__personaImportGuarded=true;
    window.openAntiRecon=wrapped;
  }

  document.addEventListener("click",function(e){
    const input=e.target && e.target.closest && e.target.closest("#personaImportInput");
    if(!input)return;
    e.stopPropagation();
    closeReconGhosts();
  },true);

  document.addEventListener("DOMContentLoaded",function(){
    guardOpenAntiRecon();
    setTimeout(guardOpenAntiRecon,500);
    setTimeout(guardOpenAntiRecon,1500);
  });

  setInterval(guardOpenAntiRecon,5000);
})();
;

/* baobao-anti-recon-v1-settings-link-v4 */
(function(){
  "use strict";
  window.openAntiReconV1Settings=function(){
    const v2=document.getElementById("antiReconV2Settings");
    if(v2)v2.classList.remove("show");

    const overlay=document.getElementById("antiReconOverlay");
    const settings=document.getElementById("antiReconSettings");
    if(!overlay||!settings)return;

    const saved=(()=>{
      try{return JSON.parse(localStorage.getItem("baobao_anti_recon_v1")||"{}")}
      catch(e){return {}}
    })();

    const permissions=Object.assign({
      chat:true,moments:true,contacts:true,album:true,me:true,activity:true
    },saved.permissions||{});

    const allow=document.getElementById("arAllow");
    const ask=document.getElementById("arAsk");
    const grab=document.getElementById("arGrab");
    if(allow)allow.checked=saved.allow!==false;
    if(ask)ask.checked=saved.ask!==false;
    if(grab)grab.checked=saved.grab!==false;

    document.querySelectorAll("#arPermissions .ar-permission").forEach(x=>{
      x.classList.toggle("on",permissions[x.dataset.key]!==false);
    });

    overlay.style.display="";
    overlay.classList.add("show");
    settings.style.display="block";

    ["antiReconRequest","antiReconSession","antiReconResult"].forEach(id=>{
      const el=document.getElementById(id);
      if(el)el.classList.remove("show");
    });
  };
})();
;

/* baobao-memory-leak-final-guard-v1 */
(function(){
  "use strict";

  function leak(text){
    return /^[\s]*[\[【]\s*(?:隐性记忆|长期记忆系统|仅供角色内部思考的记忆|系统提示|角色记忆)/.test(String(text||""));
  }

  function cleanExisting(){
    try{
      let changed=false;
      const groups=[];
      if(typeof state!=="undefined"&&Array.isArray(state.chatMessages))groups.push(state.chatMessages);
      if(typeof state!=="undefined"&&state.chatRecords){
        Object.values(state.chatRecords).forEach(arr=>{
          if(Array.isArray(arr)&&!groups.includes(arr))groups.push(arr);
        });
      }
      groups.forEach(arr=>arr.forEach(m=>{
        if(m&&m.role==="assistant"&&!m.hiddenSystem&&leak(m.content)){
          m.hiddenSystem=true;
          m.memoryLeak=true;
          changed=true;
        }
      }));
      if(changed){
        if(typeof saveLocal==="function")saveLocal();
        if(typeof renderChatMessages==="function")renderChatMessages();
      }
    }catch(e){}
  }

  const oldPush=Array.prototype.push;
  // 不改全局 push，避免影响其他功能；通过定时清理和每次渲染前清理处理。
  const oldRender=window.renderChatMessages;
  if(typeof oldRender==="function"&&!oldRender.__memoryLeakGuard){
    const wrapped=function(){
      cleanExisting();
      return oldRender.apply(this,arguments);
    };
    wrapped.__memoryLeakGuard=true;
    window.renderChatMessages=wrapped;
  }

  document.addEventListener("DOMContentLoaded",()=>setTimeout(cleanExisting,500));
  setTimeout(cleanExisting,1600);
})();
;

/* baobao-anti-recon-memory-card-v1 */
(function(){
  "use strict";

  function esc(v){
    return String(v==null?"":v).replace(/[&<>"']/g,m=>({
      "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"
    })[m]);
  }

  function timeText(ts){
    const n=Number(ts||0);
    if(!n)return "";
    const d=Math.max(0,Date.now()-n);
    if(d<60000)return "刚刚";
    if(d<3600000)return Math.floor(d/60000)+"分钟前";
    if(d<86400000)return Math.floor(d/3600000)+"小时前";
    return new Date(n).toLocaleString();
  }

  function isRawMemoryLeak(m){
    const s=String(m&&m.content||"").trim();
    return /^[\[【]\s*(?:隐性记忆|长期记忆系统|仅供角色内部思考的记忆|系统提示|角色记忆)/.test(s);
  }

  function applyCards(){
    const wrap=document.getElementById("chatMsgs");
    if(!wrap||typeof state==="undefined"||!Array.isArray(state.chatMessages))return;

    state.chatMessages.forEach((m,i)=>{
      const row=wrap.querySelector('[data-msg-row="'+i+'"]');
      if(!row)return;

      if((m.hiddenSystem&&!m.antiReconCard)||isRawMemoryLeak(m)){
        row.style.display="none";
        return;
      }

      if(!m.antiReconCard)return;

      const tags=(Array.isArray(m.cardAreas)?m.cardAreas:["手机内容"])
        .map(x=>'<span class="bb-ar-memory-tag">'+esc(x)+'</span>')
        .join("");

      row.className="bb-ar-memory-row";
      row.style.display="flex";
      row.innerHTML=
        '<div class="bb-ar-memory-card">'+
          '<div class="bb-ar-memory-head">'+
            '<div class="bb-ar-memory-icon">◉</div>'+
            '<div class="bb-ar-memory-main">'+
              '<div class="bb-ar-memory-kicker">MEMORY EVENT</div>'+
              '<div class="bb-ar-memory-title">'+esc(m.cardTitle||"反侦察记录")+'</div>'+
              '<div class="bb-ar-memory-sub">'+esc(m.cardSubtitle||"这次事件已被记录")+'</div>'+
            '</div>'+
            '<div class="bb-ar-memory-arrow">›</div>'+
          '</div>'+
          '<div class="bb-ar-memory-tags">'+tags+'</div>'+
          '<div class="bb-ar-memory-detail">'+esc(m.cardDetail||"").replace(/\n/g,"<br>")+'</div>'+
          '<div class="bb-ar-memory-foot">'+
            '<b>'+esc(m.cardStatus||"已写入角色记忆")+'</b>'+
            '<span>'+esc(timeText(m.time))+' · 点击查看</span>'+
          '</div>'+
        '</div>';

      const card=row.querySelector(".bb-ar-memory-card");
      if(card)card.onclick=function(){card.classList.toggle("open")};
    });

    wrap.scrollTop=wrap.scrollHeight;
  }

  function install(){
    const old=window.renderChatMessages;
    if(typeof old!=="function"||old.__antiReconMemoryCard)return;

    const wrapped=function(){
      const result=old.apply(this,arguments);
      applyCards();
      return result;
    };
    wrapped.__antiReconMemoryCard=true;
    wrapped.__previous=old;
    window.renderChatMessages=wrapped;
  }

  document.addEventListener("DOMContentLoaded",()=>{
    install();
    setTimeout(()=>{install();applyCards()},500);
    setTimeout(()=>{install();applyCards()},1500);
  });

  setTimeout(()=>{install();applyCards()},2400);
})();
;

/* baobao-current-persona-compat-v1 */
(function(){
  "use strict";

  function hashName(name){
    let h=0;
    const s=String(name||"当前角色");
    for(let i=0;i<s.length;i++)h=((h<<5)-h+s.charCodeAt(i))|0;
    return Math.abs(h).toString(36);
  }

  function ensureActivePersona(){
    const p=window.currentChatPersona||
      (window.state&&state.currentChatPersona)||
      null;
    if(!p||!String(p.name||"").trim())return null;

    if(!p.id){
      p.id="active_"+hashName(p.name);
    }

    window.currentChatPersona=p;
    if(window.state)state.currentChatPersona=p;
    return p;
  }

  document.addEventListener("click",function(e){
    const trigger=e.target&&e.target.closest&&e.target.closest(
      ".bb-anti-recon-tool,.anti-recon-tool,.ar2-tool,.anti-recon-settings-entry,.ar2-command-now"
    );
    if(trigger)ensureActivePersona();
  },true);

  document.addEventListener("DOMContentLoaded",ensureActivePersona);
  setTimeout(ensureActivePersona,800);
})();
;

/* baobao-memory-leak-migration-v2 */
(function(){
  "use strict";

  function migrate(){
    try{
      if(typeof state==="undefined")return;
      const groups=[];
      if(Array.isArray(state.chatMessages))groups.push(state.chatMessages);
      if(state.chatRecords){
        Object.values(state.chatRecords).forEach(arr=>{
          if(Array.isArray(arr)&&!groups.includes(arr))groups.push(arr);
        });
      }

      let changed=false;
      groups.forEach(arr=>arr.forEach(m=>{
        if(!m)return;
        const s=String(m.content||"").trim();
        if(/^[\[【]\s*(?:隐性记忆|长期记忆系统|仅供角色内部思考的记忆|系统提示|角色记忆)/.test(s)){
          if(!m.hiddenSystem||!m.memoryLeak){
            m.hiddenSystem=true;
            m.memoryLeak=true;
            changed=true;
          }
        }
      }));

      if(changed&&typeof saveLocal==="function")saveLocal();
      if(typeof renderChatMessages==="function")renderChatMessages();
    }catch(e){}
  }

  document.addEventListener("DOMContentLoaded",()=>setTimeout(migrate,300));
  setTimeout(migrate,1000);
})();
;

