window.baobaoAI = {
  mode: localStorage.getItem("baobao_ai_mode") || "relay",
  server: localStorage.getItem("baobao_relay_url") || "",
  token: localStorage.getItem("baobao_token") || ""
};

function setBaobaoRelay(url, token){
  localStorage.setItem("baobao_relay_url", url || "");
  localStorage.setItem("baobao_token", token || "");
}

async function baobaoChat(payload){
  if(!window.baobaoAI.server){
    throw new Error("未设置豹豹机中转地址");
  }
  const r = await fetch(window.baobaoAI.server + "/api/chat",{
    method:"POST",
    headers:{
      "Content-Type":"application/json",
      "Authorization":"Bearer " + window.baobaoAI.token
    },
    body:JSON.stringify(payload)
  });
  return await r.json();
}

async function baobaoVision(payload){
  if(!window.baobaoAI.server){
    throw new Error("未设置豹豹机视觉中转地址");
  }
  const r = await fetch(window.baobaoAI.server + "/api/vision",{
    method:"POST",
    headers:{
      "Content-Type":"application/json",
      "Authorization":"Bearer " + window.baobaoAI.token
    },
    body:JSON.stringify(payload)
  });
  return await r.json();
}
;

/* baobao-me-modal-layer-fix-v1-js */
(function(){
  "use strict";

  var originalOpenPanel = window.openPanel;
  if(typeof originalOpenPanel === "function" && !originalOpenPanel.__meModalLayerFixed){
    var fixedOpenPanel = function(id){
      if(id === "modal"){
        var modal = document.getElementById("modal");
        if(modal){
          modal.style.zIndex = "90";
          modal.style.pointerEvents = "auto";

          /* 之前进入过聊天设置二级页时，关闭按钮的 onclick 可能被改写。
             普通 Me 页弹窗打开时恢复为真正关闭 modal。 */
          if(!modal.classList.contains("chat-setting-subpage")){
            var closeBtn = modal.querySelector(".close-btn");
            if(closeBtn){
              closeBtn.onclick = function(){
                if(typeof window.closePanel === "function") window.closePanel("modal");
                else modal.style.display = "none";
              };
              closeBtn.setAttribute("aria-label", "关闭");
            }
          }
        }
      }
      return originalOpenPanel.apply(this, arguments);
    };
    fixedOpenPanel.__meModalLayerFixed = true;
    window.openPanel = fixedOpenPanel;
  }
})();
;

/* baobao-user-mask-v1-script */
(function(){
  "use strict";
  const $=id=>document.getElementById(id);

  function save(){
    if(typeof saveLocal==="function") saveLocal();
  }

  function uid(){
    return "umask_" + Date.now() + "_" + Math.random().toString(36).slice(2,7);
  }

  function esc(v){
    return typeof escapeHtml==="function" ? escapeHtml(String(v==null?"":v)) : String(v==null?"":v)
      .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
  }

  function mkMaskFromState(){
    const wp=state.wechatProfile||{};
    return {
      id: uid(),
      name: state.name || wp.name || "未设置昵称",
      alias: "",
      avatar: wp.avatar || state.charAvatar || "",
      summary: state.status || wp.bio || "点击设置个人资料",
      bio: wp.bio || state.status || "",
      wechatId: wp.id || "cline_123",
      note: "这是当前同步出来的默认面具。",
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
  }

  function ensureMaskState(){
    state.userMasks = Array.isArray(state.userMasks) ? state.userMasks : [];
    if(!state.userMasks.length){
      const first = mkMaskFromState();
      state.userMasks = [first];
      state.activeUserMaskId = first.id;
      save();
    }
    if(!state.activeUserMaskId || !state.userMasks.some(m=>m.id===state.activeUserMaskId)){
      state.activeUserMaskId = state.userMasks[0].id;
    }
    return state.userMasks;
  }

  function masks(){
    return ensureMaskState();
  }

  function currentMask(){
    ensureMaskState();
    return state.userMasks.find(m=>m.id===state.activeUserMaskId) || state.userMasks[0];
  }

  function maskById(id){
    return masks().find(m=>m.id===id);
  }

  function avatarHTML(src, name, cls){
    const c = cls ? 'user-mask-avatar ' + cls : 'user-mask-avatar';
    if(src){
      return '<div class="'+c+'"><img src="'+esc(src)+'" alt=""></div>';
    }
    return '<div class="'+c+'">'+esc(String(name||"U").slice(0,1).toUpperCase())+'</div>';
  }

  function syncUserAppLabel(){
    let changed = false;
    if(Array.isArray(state.page1Apps)){
      state.page1Apps.forEach(app=>{
        if(app && app.id==="user" && app.label!=="User"){
          app.label="User";
          changed = true;
        }
      });
    }
    document.querySelectorAll(".dock-icon small").forEach(el=>{
      if(el.textContent.trim()==="用户") el.textContent="User";
    });
    if(changed && typeof renderPages==="function"){
      renderPages();
    }
  }

  function applyMask(id, silent){
    const m = maskById(id);
    if(!m) return;
    state.activeUserMaskId = m.id;
    state.name = m.name || state.name;
    state.status = m.summary || m.bio || state.status || "点击设置个人资料";
    if(m.avatar) state.charAvatar = m.avatar;
    state.wechatProfile = state.wechatProfile || {};
    state.wechatProfile.name = m.name || state.wechatProfile.name || state.name;
    state.wechatProfile.id = m.wechatId || state.wechatProfile.id || "cline_123";
    state.wechatProfile.bio = m.bio || m.summary || state.wechatProfile.bio || state.status;
    state.wechatProfile.avatar = m.avatar || state.wechatProfile.avatar || state.charAvatar || "";
    save();
    if(typeof renderProfile==="function") renderProfile();
    if(typeof renderWechatIdentity==="function") renderWechatIdentity();
    if(typeof renderWeChatApp==="function") renderWeChatApp();
    syncUserAppLabel();
    if(!silent && typeof showToast==="function") showToast("已切换到面具：" + (m.name || "未命名"));
    renderUserMaskApp();
    renderWechatMaskPage();
  }

  function syncCurrentMaskFromState(){
    ensureMaskState();
    const m = currentMask();
    if(!m) return;
    const wp = state.wechatProfile || {};
    m.name = state.name || wp.name || m.name;
    m.avatar = wp.avatar || state.charAvatar || m.avatar;
    m.summary = state.status || wp.bio || m.summary;
    m.bio = wp.bio || state.status || m.bio;
    m.wechatId = wp.id || m.wechatId;
    m.updatedAt = Date.now();
    save();
    renderUserMaskApp();
    renderWechatMaskPage();
  }

  function ensureUI(){
    const root = document.querySelector(".phone") || document.body;
    if($("userMaskApp")) return;

    const app = document.createElement("div");
    app.id = "userMaskApp";
    app.className = "user-mask-app";
    app.innerHTML = '<div class="user-mask-shell"><div class="user-mask-top"><button class="user-mask-back" onclick="closeUserMaskApp()">‹</button><div class="user-mask-title-wrap"><div class="user-mask-title">User</div><div class="user-mask-sub">Mask Library · Identity Vault</div></div><button class="user-mask-add" onclick="openUserMaskEditor()">＋</button></div><div id="userMaskAppBody"></div></div>';

    const wechat = document.createElement("div");
    wechat.id = "userMaskWechat";
    wechat.className = "user-mask-wechat";
    wechat.innerHTML = '<div class="user-mask-shell"><div class="user-mask-top"><button class="user-mask-back" onclick="closeWechatMaskPage()">‹</button><div class="user-mask-title-wrap"><div class="user-mask-title">我的人设</div><div class="user-mask-sub">WeChat · Quick Switch</div></div><button class="user-mask-top-action" onclick="openUserMaskAppFromWechat()">User</button></div><div id="userMaskWechatBody"></div></div>';

    const editor = document.createElement("div");
    editor.id = "userMaskEditor";
    editor.className = "user-mask-editor";
    editor.innerHTML = '<div class="user-mask-shell"><div class="user-mask-top"><button class="user-mask-back" onclick="closeUserMaskEditor()">‹</button><div class="user-mask-title-wrap"><div class="user-mask-title" id="userMaskEditorTitle">新建面具</div><div class="user-mask-sub">Mask Editor · Keep It Pretty</div></div><button class="user-mask-top-action" onclick="saveUserMaskEditor()">保存</button></div><div class="user-mask-form-card"><div class="user-mask-upload">'+avatarHTML("", "U", "small")+'<div><button class="user-mask-upload-btn" onclick="document.getElementById(\'userMaskAvatarFile\').click()">更换头像</button><div class="user-mask-upload-tip">建议 1:1 图片，会同步到当前面具的微信资料和 User App。</div></div></div><input type="file" id="userMaskAvatarFile" class="hidden-input" accept="image/*" onchange="userMaskAvatarChosen(this)"><div class="user-mask-field"><div class="user-mask-label">面具名字</div><input id="userMaskNameInput" class="user-mask-input" type="text" maxlength="24" placeholder="例如：未设置昵称"></div><div class="user-mask-field"><div class="user-mask-label">备注 / 小代号</div><input id="userMaskAliasInput" class="user-mask-input" type="text" maxlength="24" placeholder="例如：现实版 / 女主版 / 学生版"></div><div class="user-mask-field"><div class="user-mask-label">状态文案</div><input id="userMaskSummaryInput" class="user-mask-input" type="text" maxlength="50" placeholder="一句最能代表这个面具的状态"></div><div class="user-mask-field"><div class="user-mask-label">微信号</div><input id="userMaskWechatIdInput" class="user-mask-input" type="text" maxlength="30" placeholder="例如 cline_123"></div><div class="user-mask-field"><div class="user-mask-label">微信签名 / 个签</div><input id="userMaskBioInput" class="user-mask-input" type="text" maxlength="80" placeholder="展示在微信资料里的签名"></div><div class="user-mask-field"><div class="user-mask-label">面具简介</div><textarea id="userMaskNoteInput" class="user-mask-textarea" placeholder="写一点这个版本的你：外在感觉、性格、设定、给人的印象……"></textarea></div><div class="user-mask-editor-actions"><button class="user-mask-btn primary" onclick="saveUserMaskEditor()">保存面具</button><button class="user-mask-btn ghost" onclick="closeUserMaskEditor()">取消</button></div></div></div>';

    root.appendChild(app);
    root.appendChild(wechat);
    root.appendChild(editor);
  }

  function renderUserMaskApp(){
    ensureUI();
    ensureMaskState();
    syncUserAppLabel();
    const body = $("userMaskAppBody");
    if(!body) return;
    const list = masks();
    const active = currentMask();
    body.innerHTML = `
      <div class="user-mask-hero">
        <div class="user-mask-hero-badge">CURRENT MASK</div>
        <div class="user-mask-hero-main">
          ${avatarHTML(active.avatar, active.name)}
          <div style="min-width:0;flex:1">
            <div class="user-mask-hero-name">${esc(active.name || "未命名面具")}</div>
            <div class="user-mask-hero-meta">${esc(active.alias || "全局使用中")} · ${esc(active.summary || "点击设置个人资料")}</div>
          </div>
        </div>
        <div class="user-mask-hero-chips">
          <span class="user-mask-chip">微信号 @${esc(active.wechatId || "cline_123")}</span>
          <span class="user-mask-chip">${esc(active.bio || "可同步到微信资料")}</span>
        </div>
      </div>
      <div class="user-mask-section">
        <div class="user-mask-section-title">我的面具</div>
        <div class="user-mask-section-meta">共 ${list.length} 个</div>
      </div>
      <div class="user-mask-list" id="userMaskCardList"></div>
    `;
    const wrap = $("userMaskCardList");
    if(!wrap) return;
    if(!list.length){
      wrap.innerHTML = '<div class="user-mask-empty">还没有面具，点右上角的 ＋ 创建一个吧。</div>';
      return;
    }
    wrap.innerHTML = list.map(m=>`
      <div class="user-mask-card">
        <div class="user-mask-card-top">
          ${avatarHTML(m.avatar, m.name, "small")}
          <div class="user-mask-card-main">
            <div class="user-mask-card-name">
              <span>${esc(m.name || "未命名面具")}</span>
              ${m.id===state.activeUserMaskId ? '<span class="user-mask-current-tag">Using</span>' : ''}
            </div>
            <div class="user-mask-card-sub">${esc(m.alias || "未填写备注")} · @${esc(m.wechatId || "cline_123")}</div>
          </div>
        </div>
        <div class="user-mask-card-bio">${esc(m.note || m.bio || m.summary || "还没有写面具简介。")}</div>
        <div class="user-mask-card-actions">
          <button class="user-mask-btn primary" onclick="applyUserMask('${m.id}')">${m.id===state.activeUserMaskId?'当前使用中':'设为当前'}</button>
          <button class="user-mask-btn" onclick="openUserMaskEditor('${m.id}')">编辑</button>
          <button class="user-mask-btn ghost" onclick="duplicateUserMask('${m.id}')">复制</button>
          <button class="user-mask-btn danger" onclick="deleteUserMask('${m.id}')">删除</button>
        </div>
      </div>
    `).join("");
  }

  function renderWechatMaskPage(){
    ensureUI();
    ensureMaskState();
    const body = $("userMaskWechatBody");
    if(!body) return;
    const active = currentMask();
    const list = masks();
    body.innerHTML = `
      <div class="user-mask-wechat-header">
        <div class="user-mask-wechat-headline">这里显示你的所有面具</div>
        <div class="user-mask-wechat-desc">微信里的“我的人设”现在读取 User App 的同一套面具数据。你可以在这里快速查看和切换，也可以去 User 里集中管理。</div>
        <div class="user-mask-quick-current">
          <span>当前使用：<b>${esc(active.name || "未命名面具")}</b></span>
          <span class="user-mask-pill">@${esc(active.wechatId || "cline_123")}</span>
        </div>
      </div>
      <div class="user-mask-section">
        <div class="user-mask-section-title">全部面具</div>
        <div class="user-mask-section-meta">${list.length} 个</div>
      </div>
      <div class="user-mask-mini-grid" id="userMaskWechatGrid"></div>
    `;
    const grid = $("userMaskWechatGrid");
    grid.innerHTML = list.map(m=>`
      <div class="user-mask-mini">
        ${avatarHTML(m.avatar, m.name)}
        <div class="user-mask-mini-name">${esc(m.name || "未命名面具")}</div>
        <div class="user-mask-mini-meta">${esc(m.alias || m.summary || "这个面具还没有备注")}</div>
        <div class="user-mask-mini-actions">
          <button class="user-mask-btn ${m.id===state.activeUserMaskId?'ghost':'primary'}" onclick="applyUserMask('${m.id}')">${m.id===state.activeUserMaskId?'使用中':'使用'}</button>
          <button class="user-mask-btn" onclick="openUserMaskAppFromWechatAndEdit('${m.id}')">编辑</button>
        </div>
      </div>
    `).join("");
  }

  let editingMaskId = null;
  let pendingAvatar = "";

  function fillEditor(m){
    $("userMaskEditorTitle").textContent = editingMaskId ? "编辑面具" : "新建面具";
    $("userMaskNameInput").value = m?.name || "";
    $("userMaskAliasInput").value = m?.alias || "";
    $("userMaskSummaryInput").value = m?.summary || "";
    $("userMaskWechatIdInput").value = m?.wechatId || "";
    $("userMaskBioInput").value = m?.bio || "";
    $("userMaskNoteInput").value = m?.note || "";
    const wrap = document.querySelector("#userMaskEditor .user-mask-upload .user-mask-avatar");
    if(wrap){
      wrap.outerHTML = avatarHTML(pendingAvatar, m?.name || "U", "small");
    }
  }

  window.openUserMaskEditor = function(id){
    ensureUI();
    ensureMaskState();
    editingMaskId = id || null;
    const m = id ? maskById(id) : null;
    pendingAvatar = m?.avatar || "";
    fillEditor(m);
    $("userMaskEditor").classList.add("show");
  };

  window.closeUserMaskEditor = function(){
    $("userMaskEditor")?.classList.remove("show");
    editingMaskId = null;
    pendingAvatar = "";
  };

  window.userMaskAvatarChosen = function(input){
    if(!input.files || !input.files[0]) return;
    compressImage(input.files[0], 540, .88).then(data=>{
      pendingAvatar = data;
      const old = document.querySelector("#userMaskEditor .user-mask-upload .user-mask-avatar");
      if(old) old.outerHTML = avatarHTML(data, $("userMaskNameInput")?.value || "U", "small");
    });
  };

  function safeWechatId(v){
    return String(v||"").trim().replace(/^@+/,"").replace(/[^a-zA-Z0-9_-]/g,"").slice(0,30);
  }

  window.saveUserMaskEditor = function(){
    ensureMaskState();
    const name = ($("userMaskNameInput")?.value || "").trim();
    const alias = ($("userMaskAliasInput")?.value || "").trim();
    const summary = ($("userMaskSummaryInput")?.value || "").trim();
    const wechatId = safeWechatId($("userMaskWechatIdInput")?.value || "");
    const bio = ($("userMaskBioInput")?.value || "").trim();
    const note = ($("userMaskNoteInput")?.value || "").trim();
    if(!name){
      if(typeof showToast==="function") showToast("请先填写面具名字", true);
      return;
    }
    const data = {
      id: editingMaskId || uid(),
      name,
      alias,
      avatar: pendingAvatar || "",
      summary: summary || bio || "点击设置个人资料",
      wechatId: wechatId || "cline_123",
      bio: bio || summary || "",
      note,
      createdAt: editingMaskId ? (maskById(editingMaskId)?.createdAt || Date.now()) : Date.now(),
      updatedAt: Date.now()
    };

    if(editingMaskId){
      const idx = state.userMasks.findIndex(m=>m.id===editingMaskId);
      if(idx>=0) state.userMasks[idx] = data;
    }else{
      state.userMasks.unshift(data);
      state.activeUserMaskId = data.id;
    }

    save();
    closeUserMaskEditor();
    applyMask(data.id, true);
    renderUserMaskApp();
    renderWechatMaskPage();
    if(typeof showToast==="function") showToast(editingMaskId ? "面具已保存" : "面具已创建");
  };

  window.duplicateUserMask = function(id){
    const m = maskById(id);
    if(!m) return;
    const copy = {...m, id:uid(), name:(m.name || "未命名面具") + " 副本", createdAt:Date.now(), updatedAt:Date.now()};
    state.userMasks.unshift(copy);
    save();
    renderUserMaskApp();
    renderWechatMaskPage();
    if(typeof showToast==="function") showToast("已复制一个面具");
  };

  window.deleteUserMask = function(id){
    ensureMaskState();
    if(state.userMasks.length<=1){
      if(typeof showToast==="function") showToast("至少保留一个面具哦", true);
      return;
    }
    state.userMasks = state.userMasks.filter(m=>m.id!==id);
    if(state.activeUserMaskId===id){
      state.activeUserMaskId = state.userMasks[0].id;
      applyMask(state.activeUserMaskId, true);
    }
    save();
    renderUserMaskApp();
    renderWechatMaskPage();
    if(typeof showToast==="function") showToast("已删除面具");
  };

  window.applyUserMask = function(id){
    applyMask(id, false);
  };

  window.openUserMaskApp = function(){
    ensureUI();
    renderUserMaskApp();
    $("userMaskApp").classList.add("show");
  };

  window.closeUserMaskApp = function(){
    $("userMaskApp")?.classList.remove("show");
  };

  window.openWechatMaskPage = function(){
    ensureUI();
    renderWechatMaskPage();
    $("userMaskWechat").classList.add("show");
  };

  window.closeWechatMaskPage = function(){
    $("userMaskWechat")?.classList.remove("show");
  };

  window.openUserMaskAppFromWechat = function(){
    closeWechatMaskPage();
    openUserMaskApp();
  };

  window.openUserMaskAppFromWechatAndEdit = function(id){
    closeWechatMaskPage();
    openUserMaskApp();
    setTimeout(()=>openUserMaskEditor(id), 80);
  };

  function wrapInteractions(){
    const oldOpenPersonaEdit = window.openPersonaEdit;
    window.openPersonaEdit = function(){
      openWechatMaskPage();
    };

    const oldHandle = window.handleAppAction;
    if(typeof oldHandle==="function" && !oldHandle.__userMaskWrapped){
      const wrapped = function(app){
        if(app && app.id==="user"){
          openUserMaskApp();
          return;
        }
        return oldHandle.apply(this, arguments);
      };
      wrapped.__userMaskWrapped = true;
      window.handleAppAction = wrapped;
    }

    const oldModal = window.openAppModal;
    if(typeof oldModal==="function" && !oldModal.__userMaskWrapped){
      const wrapped = function(label){
        if(label==="User" || label==="用户"){
          openUserMaskApp();
          return;
        }
        return oldModal.apply(this, arguments);
      };
      wrapped.__userMaskWrapped = true;
      window.openAppModal = wrapped;
    }

    const oldSaveWechat = window.saveWechatProfileEditor;
    if(typeof oldSaveWechat==="function" && !oldSaveWechat.__userMaskSyncWrapped){
      const wrapped = function(){
        const result = oldSaveWechat.apply(this, arguments);
        syncCurrentMaskFromState();
        return result;
      };
      wrapped.__userMaskSyncWrapped = true;
      window.saveWechatProfileEditor = wrapped;
    }

    const oldConfirmTextEdit = window.confirmTextEdit;
    if(typeof oldConfirmTextEdit==="function" && !oldConfirmTextEdit.__userMaskSyncWrapped){
      const wrapped = function(){
        const modeNow = window.textEditMode;
        const result = oldConfirmTextEdit.apply(this, arguments);
        if(modeNow==="profile" || modeNow==="charProfile" || modeNow==="persona"){
          syncCurrentMaskFromState();
        }
        return result;
      };
      wrapped.__userMaskSyncWrapped = true;
      window.confirmTextEdit = wrapped;
    }
  }

  document.addEventListener("DOMContentLoaded", function(){
    ensureMaskState();
    ensureUI();
    wrapInteractions();
    syncUserAppLabel();
    applyMask(state.activeUserMaskId, true);
  });

  setTimeout(function(){
    ensureMaskState();
    ensureUI();
    wrapInteractions();
    syncUserAppLabel();
  }, 400);

  window.BaobaoUserMask = {
    ensure: ensureMaskState,
    current: currentMask,
    openApp: openUserMaskApp,
    openWechat: openWechatMaskPage,
    apply: applyMask,
    syncCurrent: syncCurrentMaskFromState
  };
})();
;

/* baobao-quote-position-final-v1-script */
(function(){
  "use strict";

  function mountQuoteBar(){
    const room=document.getElementById("chatRoom");
    const bar=document.getElementById("msgQuoteBar");
    const input=document.querySelector("#chatRoom .chat-input-bar");
    if(!room||!bar||!input)return;

    if(bar.parentNode!==room){
      room.insertBefore(bar,input);
    }else if(bar.nextElementSibling!==input){
      room.insertBefore(bar,input);
    }

    room.classList.toggle("quote-active",bar.classList.contains("show"));
  }

  function watchQuoteBar(){
    const bar=document.getElementById("msgQuoteBar");
    if(!bar||bar.__quotePositionWatched)return;
    bar.__quotePositionWatched=true;

    new MutationObserver(()=>{
      const room=document.getElementById("chatRoom");
      if(room)room.classList.toggle("quote-active",bar.classList.contains("show"));
    }).observe(bar,{attributes:true,attributeFilter:["class"]});
  }

  const oldQuote=window.quoteChatMessage;
  if(typeof oldQuote==="function"&&!oldQuote.__positionFixed){
    const wrapped=function(){
      const result=oldQuote.apply(this,arguments);
      mountQuoteBar();
      document.getElementById("chatRoom")?.classList.add("quote-active");
      return result;
    };
    wrapped.__positionFixed=true;
    window.quoteChatMessage=wrapped;
  }

  const oldClear=window.clearQuotedMessage;
  if(typeof oldClear==="function"&&!oldClear.__positionFixed){
    const wrapped=function(){
      const result=oldClear.apply(this,arguments);
      document.getElementById("chatRoom")?.classList.remove("quote-active");
      return result;
    };
    wrapped.__positionFixed=true;
    window.clearQuotedMessage=wrapped;
  }

  document.addEventListener("DOMContentLoaded",()=>{
    mountQuoteBar();
    watchQuoteBar();
    setTimeout(()=>{mountQuoteBar();watchQuoteBar()},500);
  });

  setTimeout(()=>{mountQuoteBar();watchQuoteBar()},1500);
})();
;

/* baobao-edit-message-v2-migration */
(function(){
  "use strict";
  function cleanEditedLabels(){
    try{
      if(typeof state==="undefined") return;
      const groups=[];
      if(Array.isArray(state.chatMessages)) groups.push(state.chatMessages);
      if(state.chatRecords){
        Object.values(state.chatRecords).forEach(arr=>{
          if(Array.isArray(arr) && !groups.includes(arr)) groups.push(arr);
        });
      }
      groups.forEach(arr=>arr.forEach(m=>{
        if(m && m.edited){
          m.edited=false;
        }
      }));
      if(typeof saveLocal==="function") saveLocal();
    }catch(e){}
  }
  document.addEventListener("DOMContentLoaded",()=>setTimeout(cleanEditedLabels,300));
})();
;

/* baobao-transfer-p23-v1-script */
(function(){
  "use strict";

  function normalizeTransferStatus(status){
    if(status==="已收款"||status==="received") return "received";
    if(status==="已退回"||status==="returned"||status==="reject") return "returned";
    return "pending";
  }

  function transferStatusText(status){
    if(status==="received") return "已收款";
    if(status==="returned") return "已退回";
    return "待收款";
  }

  function transferNoteText(msg){
    const raw=String(msg.note||"转账给你");
    return raw.replace(/\s*·\s*(已收款|已退回)\s*$/,"");
  }

  function transferCardHTML(msg,index){
    const money=Number(msg.amount||msg.content||0);
    const amount=Number.isFinite(money)?money.toFixed(2):"0.00";
    const status=normalizeTransferStatus(msg.transferStatus);
    return ''+
      '<div class="bb-transfer-card is-'+status+'" data-transfer-index="'+index+'">'+
        '<div class="bb-transfer-main">'+
          '<div class="bb-transfer-icon">¥</div>'+
          '<div class="bb-transfer-content">'+
            '<div class="bb-transfer-money">¥ '+amount+'</div>'+
            '<div class="bb-transfer-note">'+(typeof escapeHtml==="function"?escapeHtml(transferNoteText(msg)):transferNoteText(msg))+'</div>'+
          '</div>'+
        '</div>'+
        '<div class="bb-transfer-foot">'+
          '<span class="bb-transfer-foot-label">转账</span>'+
          '<span class="bb-transfer-foot-status">'+transferStatusText(status)+'</span>'+
        '</div>'+
      '</div>';
  }

  function decorateTransferCards(){
    const wrap=document.getElementById("chatMsgs");
    if(!wrap || !Array.isArray(state.chatMessages)) return;
    state.chatMessages.forEach((msg,index)=>{
      if(!msg || msg.type!=="transfer") return;
      msg.transferStatus=normalizeTransferStatus(msg.transferStatus);
      const bubble=wrap.querySelector('[data-msg-index="'+index+'"]');
      if(!bubble) return;
      bubble.innerHTML=transferCardHTML(msg,index);
    });
  }

  function ensureTransferModalExtras(){
    const detail=document.querySelector("#bbTransferDetailMask .bb-transfer-detail");
    if(!detail) return;
    if(!document.getElementById("bbTransferDetailStatus")){
      const status=document.createElement("div");
      status.id="bbTransferDetailStatus";
      const note=document.getElementById("bbTransferDetailNote");
      if(note && note.parentNode) note.parentNode.insertBefore(status, note.nextSibling);
    }
  }

  window.closeTransferDetail=function(){
    document.getElementById("bbTransferDetailMask")?.classList.remove("show");
    window.bbCurrentTransferIndex=null;
  };

  window.openTransferDetail=function(index){
    const msg=(state.chatMessages||[])[index];
    if(!msg || msg.type!=="transfer") return;

    ensureTransferModalExtras();
    window.bbCurrentTransferIndex=index;

    const status=normalizeTransferStatus(msg.transferStatus);
    msg.transferStatus=status;

    if(state.activeChatId&&state.chatRecords&&Array.isArray(state.chatRecords[state.activeChatId])){
      const stored=msg.id
        ?state.chatRecords[state.activeChatId].find(item=>item&&item.id===msg.id)
        :state.chatRecords[state.activeChatId][index];
      if(stored&&stored.type==="transfer")stored.transferStatus=status;
    }

    const money=Number(msg.amount||msg.content||0);
    document.getElementById("bbTransferDetailMoney").textContent='¥ ' + (Number.isFinite(money)?money.toFixed(2):"0.00");
    document.getElementById("bbTransferDetailNote").textContent=transferNoteText(msg);

    const title=document.querySelector("#bbTransferDetailMask .bb-transfer-detail h3");
    const statusEl=document.getElementById("bbTransferDetailStatus");
    const backBtn=document.querySelector("#bbTransferDetailMask .bb-transfer-back");
    const okBtn=document.querySelector("#bbTransferDetailMask .bb-transfer-ok");

    if(title) title.textContent = status==="pending" ? "收到一笔转账" : "转账详情";
    if(statusEl) statusEl.textContent = status==="pending" ? "" : transferStatusText(status);

    if(backBtn && okBtn){
      if(status==="pending"){
        backBtn.textContent="退回";
        okBtn.textContent="确认收款";
        backBtn.style.display="";
        okBtn.style.display="";
        backBtn.onclick=function(){handleTransferAction("reject")};
        okBtn.onclick=function(){handleTransferAction("accept")};
      }else{
        backBtn.textContent="关闭";
        backBtn.style.display="none";
        okBtn.textContent="我知道了";
        okBtn.style.display="";
        okBtn.onclick=function(){closeTransferDetail()};
      }
    }

    document.getElementById("bbTransferDetailMask").classList.add("show");
  };

  window.handleTransferAction=function(action){
    const index=window.bbCurrentTransferIndex;
    const msg=(state.chatMessages||[])[index];
    if(!msg || msg.type!=="transfer") return;

    const nextStatus=action==="accept" ? "received" : "returned";
    const handledAt=Date.now();

    msg.transferStatus=nextStatus;
    msg.transferHandledAt=handledAt;

    // 新版保存时会省略 chatMessages，因此必须同步到当前真实会话记录。
    if(state.activeChatId&&state.chatRecords){
      const records=Array.isArray(state.chatRecords[state.activeChatId])
        ?state.chatRecords[state.activeChatId]
        :[];

      let stored=null;
      if(msg.id){
        stored=records.find(item=>item&&item.id===msg.id);
      }
      if(!stored&&records[index]&&records[index].type==="transfer"){
        stored=records[index];
      }

      if(stored){
        stored.transferStatus=nextStatus;
        stored.transferHandledAt=handledAt;
      }else{
        state.chatRecords[state.activeChatId]=state.chatMessages;
      }
    }

    // 导入角色或临时角色使用另一条记录键时，也同步一次。
    const role=window.currentChatPersona;
    if(role&&role.id&&state.chatRecords){
      const roleRecords=state.chatRecords[role.id];
      if(Array.isArray(roleRecords)){
        const stored=msg.id
          ?roleRecords.find(item=>item&&item.id===msg.id)
          :roleRecords[index];
        if(stored&&stored.type==="transfer"){
          stored.transferStatus=nextStatus;
          stored.transferHandledAt=handledAt;
        }
      }
    }

    if(typeof saveLocal==="function") saveLocal();
    if(typeof renderChatMessages==="function") renderChatMessages();
    if(typeof renderChatList==="function") renderChatList();

    closeTransferDetail();

    if(typeof showToast==="function"){
      showToast(action==="accept" ? "已确认收款" : "已退回");
    }
  };

  document.addEventListener("click",function(e){
    const card=e.target.closest(".bb-transfer-card");
    if(card && card.dataset.transferIndex){
      e.preventDefault();
      e.stopPropagation();
      openTransferDetail(Number(card.dataset.transferIndex));
      return;
    }

    const mask=e.target.closest("#bbTransferDetailMask");
    if(mask && e.target===mask){
      closeTransferDetail();
    }
  },true);

  const oldRender=window.renderChatMessages;
  if(typeof oldRender==="function" && !oldRender.__transferP23Wrapped){
    const wrapped=function(){
      const result=oldRender.apply(this,arguments);
      decorateTransferCards();
      return result;
    };
    wrapped.__transferP23Wrapped=true;
    window.renderChatMessages=wrapped;
    setTimeout(()=>{try{window.renderChatMessages()}catch(e){}},120);
  }else{
    setTimeout(decorateTransferCards,300);
  }

  document.addEventListener("DOMContentLoaded",()=>{
    ensureTransferModalExtras();
    setTimeout(decorateTransferCards,500);
  });

  setTimeout(()=>{
    ensureTransferModalExtras();
    decorateTransferCards();
  },1200);
})();
;

/* baobao-storage-media-v183 */
(function(){
  "use strict";
  const MOMENTS_KEY="baobao_moments_posts_v3";

  async function compactOldMomentImages(){
    if(localStorage.getItem("bb_moments_media_compacted_v183")==="1")return;
    try{
      const posts=JSON.parse(localStorage.getItem(MOMENTS_KEY)||"[]");
      let changed=false;

      for(const post of posts){
        if(!post||!Array.isArray(post.images))continue;
        for(let i=0;i<post.images.length;i++){
          const src=post.images[i];
          if(typeof src==="string"&&src.startsWith("data:image/")&&src.length>115000){
            post.images[i]=await compressImageToBudget(src,{
              maxDim:760,quality:.66,maxChars:115000,minDim:420
            });
            changed=true;
          }
        }
      }

      if(changed)localStorage.setItem(MOMENTS_KEY,JSON.stringify(posts));
      localStorage.setItem("bb_moments_media_compacted_v183","1");
      if(typeof renderMomentsFeed==="function")renderMomentsFeed();
    }catch(e){
      console.warn("旧朋友圈图片整理失败：",e);
    }
  }

  document.addEventListener("DOMContentLoaded",()=>{
    try{saveLocal()}catch(e){}
    setTimeout(()=>baobaoCompactExistingMedia(),350);
    setTimeout(()=>compactOldMomentImages(),900);
  });
})();
;

/* baobao-transfer-ai-semantic-v1 */
(function(){
  "use strict";

  function previewTransfer(msg){
    const amount=Number(msg&&(msg.amount||msg.content)||0);
    const money=Number.isFinite(amount)?amount.toFixed(2):"0.00";
    const status=msg&&msg.transferStatus;
    if(status==="received"||status==="已收款")return "[已收款] ¥"+money;
    if(status==="returned"||status==="已退回")return "[已退回] ¥"+money;
    return "[转账] ¥"+money;
  }

  window.BaobaoTransferSemantic={
    preview:previewTransfer,
    forAI:function(msg){
      return typeof window.baobaoMessageForAI==="function"
        ?window.baobaoMessageForAI(msg)
        :previewTransfer(msg);
    }
  };
})();
;

/* baobao-transfer-status-final-v1 */
(function(){
  "use strict";

  function normalize(status){
    if(status==="received"||status==="已收款")return "received";
    if(status==="returned"||status==="已退回")return "returned";
    return "pending";
  }

  function syncAllTransferStatuses(){
    if(typeof state==="undefined")return;

    const groups=[];
    if(Array.isArray(state.chatMessages))groups.push(state.chatMessages);
    if(state.chatRecords){
      Object.values(state.chatRecords).forEach(arr=>{
        if(Array.isArray(arr)&&!groups.includes(arr))groups.push(arr);
      });
    }

    const byId=new Map();

    groups.forEach(arr=>arr.forEach(msg=>{
      if(!msg||msg.type!=="transfer")return;
      msg.transferStatus=normalize(msg.transferStatus);
      if(msg.id){
        const previous=byId.get(msg.id);
        if(!previous||previous==="pending"||msg.transferStatus!=="pending"){
          byId.set(msg.id,msg.transferStatus);
        }
      }
    }));

    groups.forEach(arr=>arr.forEach(msg=>{
      if(msg&&msg.type==="transfer"&&msg.id&&byId.has(msg.id)){
        msg.transferStatus=byId.get(msg.id);
      }
    }));
  }

  const oldRender=window.renderChatMessages;
  if(typeof oldRender==="function"&&!oldRender.__transferStatusFinal){
    const wrapped=function(){
      syncAllTransferStatuses();
      return oldRender.apply(this,arguments);
    };
    wrapped.__transferStatusFinal=true;
    window.renderChatMessages=wrapped;
  }

  document.addEventListener("DOMContentLoaded",()=>{
    syncAllTransferStatuses();
    setTimeout(()=>{
      syncAllTransferStatuses();
      if(typeof renderChatMessages==="function")renderChatMessages();
    },500);
  });
})();
;

/* baobao-message-multiselect-v1-script */
(function(){
  "use strict";

  let multiMode=false;
  const selected=new Set();

  function room(){
    return document.getElementById("chatRoom");
  }

  function messages(){
    return Array.isArray(state.chatMessages)?state.chatMessages:[];
  }

  function selectable(index){
    const msg=messages()[index];
    if(!msg)return false;
    if(msg.hiddenSystem&&!msg.antiReconCard)return false;
    return true;
  }

  function ensureToolbar(){
    const chatRoom=room();
    if(!chatRoom)return null;

    let bar=document.getElementById("bbMessageMultiToolbar");
    if(bar)return bar;

    bar=document.createElement("div");
    bar.id="bbMessageMultiToolbar";
    bar.className="bb-message-multi-toolbar";
    bar.innerHTML=
      '<button class="bb-message-multi-cancel" onclick="cancelMessageMultiSelect()">取消</button>'+
      '<button class="bb-message-multi-all" id="bbMessageMultiAll" onclick="toggleSelectAllMessages()">全选</button>'+
      '<div class="bb-message-multi-count" id="bbMessageMultiCount">已选 0 条</div>'+
      '<button class="bb-message-multi-delete" id="bbMessageMultiDelete" onclick="deleteSelectedMessages()" disabled>删除</button>';

    chatRoom.appendChild(bar);
    return bar;
  }

  function updateToolbar(){
    ensureToolbar();
    const count=document.getElementById("bbMessageMultiCount");
    const del=document.getElementById("bbMessageMultiDelete");
    const all=document.getElementById("bbMessageMultiAll");

    if(count)count.textContent="已选 "+selected.size+" 条";
    if(del){
      del.disabled=selected.size===0;
      del.textContent=selected.size?"删除 "+selected.size:"删除";
    }

    const indexes=messages().map((_,i)=>i).filter(selectable);
    const allSelected=indexes.length>0&&indexes.every(i=>selected.has(i));
    if(all)all.textContent=allSelected?"取消全选":"全选";
  }

  function decorateRows(){
    const wrap=document.getElementById("chatMsgs");
    if(!wrap)return;

    wrap.querySelectorAll("[data-msg-row]").forEach(row=>{
      const index=Number(row.getAttribute("data-msg-row"));
      row.querySelector(".bb-message-select-circle")?.remove();
      row.classList.remove("bb-message-selected");

      if(!multiMode||!selectable(index))return;

      const circle=document.createElement("span");
      circle.className="bb-message-select-circle";
      row.insertBefore(circle,row.firstChild);
      row.classList.toggle("bb-message-selected",selected.has(index));
    });

    updateToolbar();
  }

  function syncCurrentConversation(){
    if(state.activeChatId&&state.chatRecords){
      state.chatRecords[state.activeChatId]=state.chatMessages;
    }

    const role=window.currentChatPersona;
    if(role&&role.id&&state.chatRecords){
      state.chatRecords[role.id]=state.chatMessages;
    }
  }

  window.startMessageMultiSelect=function(){
    const index=Number(window.activeMessageIndex);
    multiMode=true;
    selected.clear();
    if(Number.isInteger(index)&&selectable(index))selected.add(index);

    closeMessageMenu();
    room()?.classList.add("bb-message-multi-mode");
    ensureToolbar();
    decorateRows();
  };

  window.cancelMessageMultiSelect=function(){
    multiMode=false;
    selected.clear();
    room()?.classList.remove("bb-message-multi-mode");
    decorateRows();
  };

  window.toggleSelectAllMessages=function(){
    const indexes=messages().map((_,i)=>i).filter(selectable);
    const allSelected=indexes.length>0&&indexes.every(i=>selected.has(i));

    selected.clear();
    if(!allSelected)indexes.forEach(i=>selected.add(i));
    decorateRows();
  };

  function toggleIndex(index){
    if(!selectable(index))return;
    if(selected.has(index))selected.delete(index);
    else selected.add(index);
    decorateRows();
  }

  window.deleteSelectedMessages=function(){
    if(!multiMode||selected.size===0)return;

    const indexes=[...selected]
      .filter(i=>Number.isInteger(i)&&i>=0&&i<messages().length)
      .sort((a,b)=>b-a);

    const removedIds=[];
    indexes.forEach(index=>{
      const msg=state.chatMessages[index];
      if(msg&&msg.id)removedIds.push(msg.id);
      state.chatMessages.splice(index,1);
    });

    if(Array.isArray(state.favoriteMessages)&&removedIds.length){
      state.favoriteMessages=state.favoriteMessages.filter(item=>
        !item||!removedIds.includes(item.msgId)
      );
    }

    syncCurrentConversation();
    if(typeof saveLocal==="function")saveLocal();

    multiMode=false;
    selected.clear();
    room()?.classList.remove("bb-message-multi-mode");

    if(typeof renderChatMessages==="function")renderChatMessages();
    if(typeof renderChatList==="function")renderChatList();
    if(typeof showToast==="function")showToast("已删除 "+indexes.length+" 条消息");
  };

  document.addEventListener("click",function(event){
    if(!multiMode)return;

    const row=event.target&&event.target.closest&&
      event.target.closest("#chatMsgs [data-msg-row]");

    if(!row)return;

    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();

    toggleIndex(Number(row.getAttribute("data-msg-row")));
  },true);

  document.addEventListener("contextmenu",function(event){
    if(!multiMode)return;
    const row=event.target&&event.target.closest&&
      event.target.closest("#chatMsgs [data-msg-row]");
    if(row){
      event.preventDefault();
      event.stopPropagation();
    }
  },true);

  const oldOpenMenu=window.openMessageMenu;
  if(typeof oldOpenMenu==="function"&&!oldOpenMenu.__multiSelectWrapped){
    const wrapped=function(index,event){
      if(multiMode){
        toggleIndex(Number(index));
        return false;
      }
      return oldOpenMenu.apply(this,arguments);
    };
    wrapped.__multiSelectWrapped=true;
    window.openMessageMenu=wrapped;
  }

  const oldRender=window.renderChatMessages;
  if(typeof oldRender==="function"&&!oldRender.__multiSelectWrapped){
    const wrapped=function(){
      const result=oldRender.apply(this,arguments);
      ensureToolbar();
      decorateRows();
      return result;
    };
    wrapped.__multiSelectWrapped=true;
    window.renderChatMessages=wrapped;
  }

  document.addEventListener("DOMContentLoaded",()=>{
    ensureToolbar();
    setTimeout(decorateRows,400);
  });

  window.BaobaoMessageMultiSelect={
    active:()=>multiMode,
    selected:()=>[...selected]
  };
})();
;

