/* baobao-anti-recon-physical-gate-v1 */
(function(){
  "use strict";

  const ENTRY_SELECTOR=[
    '[data-bb-recon-entry="1"]',
    '.bb-anti-recon-tool',
    '.anti-recon-tool',
    '.ar2-tool',
    '.anti-recon-settings-entry'
  ].join(",");

  const SECRET={};
  let pressedEntry=null;
  let pressedUntil=0;
  let authorizedPanelUntil=0;

  function now(){return Date.now()}

  function visible(el){
    if(!el||!el.isConnected)return false;
    const style=getComputedStyle(el);
    if(style.display==="none"||style.visibility==="hidden"||style.pointerEvents==="none")return false;
    const rect=el.getBoundingClientRect();
    return rect.width>0&&rect.height>0;
  }

  function topmostMatches(entry,x,y){
    if(!entry||!Number.isFinite(x)||!Number.isFinite(y))return false;
    const top=document.elementFromPoint(x,y);
    return !!top&&(top===entry||entry.contains(top));
  }

  function exactEntry(target){
    const entry=target&&target.closest&&target.closest(ENTRY_SELECTOR);
    return visible(entry)?entry:null;
  }

  function clearPress(){
    pressedEntry=null;
    pressedUntil=0;
  }

  function closeSettings(){
    const panel=document.getElementById("antiReconV2Settings");
    if(panel){
      panel.classList.remove("show");
      panel.setAttribute("aria-hidden","true");
    }
  }

  function syncSettings(){
    const master=localStorage.getItem("baobao_anti_recon_master_v188")==="1";
    let cfg={auto:master,grab:true,memory:true,suspicion:18};
    try{
      cfg=Object.assign(cfg,JSON.parse(localStorage.getItem("baobao_anti_recon_v2")||"{}"));
    }catch(e){}
    cfg.auto=master;

    [
      ["ar2AutoSwitch",master],
      ["ar2GrabSwitch",!!cfg.grab],
      ["ar2MemorySwitch",!!cfg.memory]
    ].forEach(([id,on])=>{
      const el=document.getElementById(id);
      if(el)el.classList.toggle("on",on);
    });

    const suspicion=document.getElementById("ar2SuspicionText");
    if(suspicion)suspicion.textContent=Math.round(Number(cfg.suspicion||0))+" / 100";
  }

  // 仅 pointerdown/touchstart 的真实落点可发放一次性许可。
  function recordPhysicalPress(event){
    const entry=exactEntry(event.target);
    if(!entry){
      clearPress();
      return;
    }

    const point=event.touches&&event.touches[0]
      ?event.touches[0]
      :event;

    const x=Number(point.clientX);
    const y=Number(point.clientY);

    if(!topmostMatches(entry,x,y)){
      clearPress();
      return;
    }

    entry.dataset.bbReconEntry="1";
    pressedEntry=entry;
    pressedUntil=now()+650;
  }

  document.addEventListener("pointerdown",recordPhysicalPress,true);
  document.addEventListener("touchstart",recordPhysicalPress,true);

  // 任意非入口的点击都会立即清除残留许可。
  document.addEventListener("click",function(event){
    if(!exactEntry(event.target)){
      clearPress();
    }
  },true);

  function openWithSecret(secret,entry){
    if(secret!==SECRET)return false;

    const valid=
      entry&&
      entry===pressedEntry&&
      now()<=pressedUntil&&
      visible(entry);

    clearPress();

    if(!valid){
      closeSettings();
      return false;
    }

    if(typeof window.closeBaobaoTools==="function")window.closeBaobaoTools();

    syncSettings();
    const panel=document.getElementById("antiReconV2Settings");
    if(!panel)return false;

    authorizedPanelUntil=now()+30*60*1000;
    panel.classList.add("show");
    panel.setAttribute("aria-hidden","false");
    return true;
  }

  window.baobaoOpenAntiReconExplicit=function(entry,event){
    if(event){
      event.stopPropagation();
    }
    return openWithSecret(SECRET,entry);
  };

  // 所有旧代码若直接调用 openAntiRecon()，一律拒绝。
  const deniedOpen=function(){
    closeSettings();
    return false;
  };
  deniedOpen.__antiReconStrictGate=true;
  deniedOpen.__messageClickFinalGate=true;
  deniedOpen.__personaImportGuarded=true;
  deniedOpen.__physicalGate=true;
  window.openAntiRecon=deniedOpen;

  // 防止旧函数引用或其他脚本直接给面板加 show。
  function watchPanel(){
    const panel=document.getElementById("antiReconV2Settings");
    if(!panel||panel.__physicalGateWatched)return;
    panel.__physicalGateWatched=true;

    new MutationObserver(()=>{
      if(panel.classList.contains("show")&&now()>authorizedPanelUntil){
        panel.classList.remove("show");
        panel.setAttribute("aria-hidden","true");
      }
    }).observe(panel,{attributes:true,attributeFilter:["class"]});
  }

  // 把所有已有/后生成的反侦察入口都切换到显式函数。
  function bindEntries(){
    document.querySelectorAll(ENTRY_SELECTOR).forEach(entry=>{
      entry.dataset.bbReconEntry="1";
      if(entry.__bbPhysicalReconBound)return;
      entry.__bbPhysicalReconBound=true;
      entry.onclick=function(event){
        return window.baobaoOpenAntiReconExplicit(entry,event);
      };
    });
  }

  function install(){
    // 旧脚本会定时尝试重新包装，因此每次都恢复最终拒绝函数。
    if(window.openAntiRecon!==deniedOpen)window.openAntiRecon=deniedOpen;
    bindEntries();
    watchPanel();
  }

  document.addEventListener("DOMContentLoaded",()=>{
    closeSettings();
    install();
    setTimeout(install,300);
    setTimeout(install,1000);
  });

  const root=document.querySelector(".phone")||document.documentElement;
  if(root){
    new MutationObserver(bindEntries).observe(root,{childList:true,subtree:true});
  }

  setInterval(install,3500);

  window.BaobaoAntiReconPhysicalGate={
    close:closeSettings,
    clear:clearPress,
    version:"1.0"
  };
})();
;

/* baobao-anti-recon-master-v188 */
(function(){
  "use strict";
  const MASTER="baobao_anti_recon_master_v188";

  function enabled(){
    return localStorage.getItem(MASTER)==="1";
  }

  function migrate(){
    if(localStorage.getItem(MASTER)===null){
      localStorage.setItem(MASTER,"0");
    }

    if(!enabled()){
      localStorage.removeItem("baobao_ar3_pending");

      try{
        const v1=JSON.parse(localStorage.getItem("baobao_anti_recon_v1")||"{}");
        v1.allow=false;
        localStorage.setItem("baobao_anti_recon_v1",JSON.stringify(v1));
      }catch(e){}

      try{
        const v2=JSON.parse(localStorage.getItem("baobao_anti_recon_v2")||"{}");
        v2.auto=false;
        localStorage.setItem("baobao_anti_recon_v2",JSON.stringify(v2));
      }catch(e){}
    }

    if(typeof window.baobaoSyncAntiReconMasterUI==="function"){
      window.baobaoSyncAntiReconMasterUI();
    }
  }

  document.addEventListener("DOMContentLoaded",()=>{
    migrate();
    setTimeout(migrate,500);
  });

  window.BaobaoAntiReconMaster={
    enabled,
    set:function(on){
      localStorage.setItem(MASTER,on?"1":"0");
      migrate();
    }
  };
})();
;

