/* baobao-sms-app-v190-script */
(function(){
  "use strict";

  const SMS_KEY="baobao_sms_threads_v190";
  const PENDING_KEY="baobao_sms_pending_appeals_v190";
  const SETTINGS_KEY="baobao_sms_settings_v248";
  let activePersonaId=null;
  const replying=new Set();

  function esc(value){
    return typeof escapeHtml==="function"
      ?escapeHtml(String(value==null?"":value))
      :String(value==null?"":value)
        .replace(/&/g,"&amp;").replace(/</g,"&lt;")
        .replace(/>/g,"&gt;").replace(/"/g,"&quot;");
  }

  function personas(){
    return Array.isArray(state.personas)?state.personas:[];
  }

  function personaById(id){
    return personas().find(p=>String(p.id)===String(id));
  }

  function loadStore(){
    try{
      const data=JSON.parse(localStorage.getItem(SMS_KEY)||"{}");
      if(!data||typeof data!=="object")return {};
      return data;
    }catch(e){
      return {};
    }
  }

  function saveStore(store){
    try{
      Object.values(store).forEach(thread=>{
        if(thread&&Array.isArray(thread.messages)){
          thread.messages=thread.messages.slice(-240);
        }
      });
      localStorage.setItem(SMS_KEY,JSON.stringify(store));
      return true;
    }catch(e){
      console.warn("短信保存失败：",e);
      if(typeof showToast==="function")showToast("短信存储空间不足",true);
      return false;
    }
  }

  function loadSettings(){
    try{
      const raw=JSON.parse(localStorage.getItem(SETTINGS_KEY)||"{}");
      return {
        historyRounds:Math.min(100,Math.max(5,Number(raw.historyRounds)||50)),
        bubbleColor:raw.bubbleColor==="green"?"green":"blue"
      };
    }catch(e){
      return {historyRounds:50,bubbleColor:"blue"};
    }
  }

  function saveSettings(settings){
    localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings||loadSettings()));
    applySmsSettings();
  }

  function applySmsSettings(){
    const app=document.getElementById("baobaoSmsApp");
    if(!app)return;
    const settings=loadSettings();
    app.dataset.bubbleColor=settings.bubbleColor;
    const rounds=document.getElementById("smsHistoryRounds");
    const output=document.getElementById("smsHistoryRoundsValue");
    if(rounds)rounds.value=String(settings.historyRounds);
    if(output)output.textContent=settings.historyRounds+"轮";
    document.querySelectorAll("[data-sms-color]").forEach(btn=>{
      btn.classList.toggle("active",btn.dataset.smsColor===settings.bubbleColor);
    });
  }

  function threadFor(id,create){
    const store=loadStore();
    const key=String(id);
    if(!store[key]&&create){
      store[key]={messages:[],unread:0,updatedAt:0};
      saveStore(store);
    }
    return {store,thread:store[key]||null,key};
  }

  function phoneNumber(person){
    const seed=String(person&&person.id||person&&person.wechat||"10086");
    let hash=0;
    for(let i=0;i<seed.length;i++)hash=(hash*31+seed.charCodeAt(i))>>>0;
    const tail=String(hash%100000000).padStart(8,"0");
    return "+86 1"+String(30+(hash%60)).padStart(2,"0")+" "+tail.slice(0,4)+" "+tail.slice(4);
  }

  function avatar(person,small){
    const cls=small?"sms-avatar small":"sms-avatar";
    if(person&&person.photo){
      return '<div class="'+cls+'"><img src="'+esc(person.photo)+'" alt=""></div>';
    }
    return '<div class="'+cls+'">'+esc(String(person&&person.name||"短").slice(0,1))+'</div>';
  }

  function formatTime(time){
    if(!time)return "";
    const d=new Date(time);
    const now=new Date();
    if(d.toDateString()===now.toDateString()){
      return String(d.getHours()).padStart(2,"0")+":"+String(d.getMinutes()).padStart(2,"0");
    }
    return (d.getMonth()+1)+"/"+d.getDate();
  }

  function blockedState(personId){
    try{
      const all=JSON.parse(localStorage.getItem("bb_blacklist_states_v1")||"{}");
      return all[String(personId)]||{blockedByUser:false,blockedByRole:false};
    }catch(e){
      return {blockedByUser:false,blockedByRole:false};
    }
  }

  function currentUserMask(){
    try{
      const masks=Array.isArray(state.userMasks)?state.userMasks:[];
      return masks.find(x=>x&&x.id===state.activeUserMaskId)||null;
    }catch(e){
      return null;
    }
  }

  function ensureUI(){
    if(document.getElementById("baobaoSmsApp"))return;
    const root=document.querySelector(".phone")||document.body;
    const app=document.createElement("div");
    app.id="baobaoSmsApp";
    app.innerHTML=
      '<section class="sms-screen show" id="smsListScreen">'+
        '<div class="sms-status-space"></div>'+
        '<div class="sms-nav">'+
          '<button class="sms-nav-back" onclick="closeSmsApp()">‹</button>'+
          '<div class="sms-nav-title-wrap"><div class="sms-nav-title">短信</div><div class="sms-nav-sub">Messages · Private Line</div></div>'+
          '<button class="sms-nav-action sms-settings-action" onclick="openSmsSettings()" aria-label="短信设置">'+
            '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h10M18 7h2M4 17h2M10 17h10M14 5v4M6 15v4"/></svg>'+
          '</button>'+
        '</div>'+
        '<div class="sms-list" id="smsConversationList"></div>'+
      '</section>'+
      '<section class="sms-screen" id="smsThreadScreen">'+
        '<div class="sms-status-space"></div>'+
        '<div class="sms-thread-nav">'+
          '<button class="sms-nav-back" onclick="backToSmsList()">‹</button>'+
          '<div class="sms-thread-person" id="smsThreadPerson"></div>'+
        '</div>'+
        '<div class="sms-block-hint" id="smsBlockHint"></div>'+
        '<div class="sms-messages" id="smsMessages"></div>'+
        '<div class="sms-typing" id="smsTyping">对方正在输入短信…</div>'+
        '<div class="sms-composer">'+
          '<textarea class="sms-input" id="smsInput" rows="1" placeholder="短信/iMessage" oninput="smsInputChanged(this)"></textarea>'+
          '<button class="sms-send" id="smsSendBtn" onclick="sendSmsMessage()" aria-label="发送短信">↑</button>'+
        '</div>'+
      '</section>'+
      '<section class="sms-screen sms-settings-screen" id="smsSettingsScreen">'+
        '<div class="sms-status-space"></div>'+
        '<div class="sms-settings-nav">'+
          '<button class="sms-settings-back" onclick="closeSmsSettings()">‹</button>'+
          '<div class="sms-settings-title">聊天设置</div>'+
          '<div class="sms-settings-spacer"></div>'+
        '</div>'+
        '<div class="sms-settings-body">'+
          '<div class="sms-settings-section-label">↶ 历史消息</div>'+
          '<div class="sms-settings-card sms-history-card">'+
            '<div class="sms-settings-row-title">附带历史消息回合数</div>'+
            '<input id="smsHistoryRounds" type="range" min="5" max="100" step="5" oninput="changeSmsHistoryRounds(this.value)">'+
            '<div class="sms-settings-value" id="smsHistoryRoundsValue">50轮</div>'+
          '</div>'+
          '<div class="sms-settings-section-label">◉ 气泡颜色</div>'+
          '<div class="sms-settings-card">'+
            '<div class="sms-settings-row-title">我的消息气泡颜色</div>'+
            '<div class="sms-color-switch">'+
              '<button type="button" data-sms-color="blue" onclick="setSmsBubbleColor(\'blue\')">蓝色</button>'+
              '<button type="button" data-sms-color="green" onclick="setSmsBubbleColor(\'green\')">绿色</button>'+
            '</div>'+
          '</div>'+
          '<div class="sms-settings-section-label">▥ 数据管理</div>'+
          '<button class="sms-clear-card" type="button" onclick="clearAllSmsRecords()">'+
            '<span>清空记录</span>'+
            '<small>删除所有短信记录和相关记忆，不可恢复</small>'+
          '</button>'+
        '</div>'+
      '</section>';
    app.className="baobao-sms-app";
    root.appendChild(app);
  }

  function lastMessage(thread){
    const list=thread&&Array.isArray(thread.messages)?thread.messages:[];
    return list[list.length-1]||null;
  }

  window.renderSmsList=function(){
    ensureUI();
    const wrap=document.getElementById("smsConversationList");
    if(!wrap)return;

    const store=loadStore();
    const list=personas().map(person=>{
      const thread=store[String(person.id)]||{messages:[],unread:0,updatedAt:0};
      return {person,thread,last:lastMessage(thread)};
    }).sort((a,b)=>{
      const ta=Number(a.thread.updatedAt||0);
      const tb=Number(b.thread.updatedAt||0);
      if(tb!==ta)return tb-ta;
      return String(a.person.name||"").localeCompare(String(b.person.name||""));
    });

    let html="";
    if(!list.length){
      html+='<div class="sms-empty">还没有联系人。<br>先到 Chat → Contacts 创建角色，人设资料仍在那里管理。</div>';
      wrap.innerHTML=html;
      return;
    }

    html+=list.map(item=>{
      const person=item.person;
      const thread=item.thread;
      const last=item.last;
      const preview=last
        ?String(last.content||"").replace(/\s+/g," ").slice(0,52)
        :"还没有短信，点进去开始联系";
      return '<div class="sms-contact" onclick="openSmsThread(\''+esc(person.id)+'\')">'+
        avatar(person,true)+
        '<div class="sms-contact-main">'+
          '<div class="sms-contact-top">'+
            '<div class="sms-contact-name">'+esc(person.name||"未命名")+'</div>'+
            '<div class="sms-contact-time">'+formatTime(thread.updatedAt||last&&last.time)+'</div>'+
          '</div>'+
          '<div class="sms-contact-preview">'+esc(preview)+'</div>'+
        '</div>'+
        (thread.unread?'<div class="sms-unread">'+Math.min(99,thread.unread)+'</div>':"")+
      '</div>';
    }).join("");

    wrap.innerHTML=html;
  };

  function renderThreadPerson(person){
    const holder=document.getElementById("smsThreadPerson");
    if(!holder)return;
    holder.innerHTML=
      avatar(person,true)+
      '<div style="min-width:0"><div class="sms-thread-name">'+esc(person.name||"未命名")+'</div>'+
      '<div class="sms-thread-number">'+esc(phoneNumber(person))+'</div></div>';
  }

  function renderBlockHint(personId){
    const el=document.getElementById("smsBlockHint");
    if(!el)return;
    const stateNow=blockedState(personId);
    if(stateNow.blockedByUser){
      el.textContent="你已在微信拉黑对方。这里是独立短信通道，双方仍可以联系。";
      el.classList.add("show");
    }else{
      el.classList.remove("show");
      el.textContent="";
    }
  }

  function renderSmsMessages(){
    const wrap=document.getElementById("smsMessages");
    if(!wrap||!activePersonaId)return;

    const data=threadFor(activePersonaId,true);
    const messages=data.thread.messages||[];

    if(!messages.length){
      wrap.innerHTML='<div class="sms-empty" style="margin-top:30px">还没有短信。<br>这里与微信聊天记录互不混合。</div>';
      return;
    }

    let lastDay="";
    wrap.innerHTML=messages.map(msg=>{
      const d=new Date(msg.time||Date.now());
      const day=d.toDateString();
      let dayHtml="";
      if(day!==lastDay){
        lastDay=day;
        dayHtml='<div class="sms-day">'+(day===new Date().toDateString()?"今天":(d.getMonth()+1)+"月"+d.getDate()+"日")+'</div>';
      }

      const appeal=msg.source==="wechat_block_appeal"
        ?'<div class="sms-appeal-label">从微信拉黑后转来的短信</div>'
        :"";

      if(msg.generationFailed){
        return dayHtml+'<div class="sms-generation-failed-v304">生成失败</div>';
      }

      return dayHtml+appeal+
        '<div class="sms-row '+(msg.role==="user"?"user":"assistant")+'">'+
          '<div class="sms-message-stack">'+
            '<div class="sms-bubble">'+esc(msg.content||"")+'</div>'+
            '<div class="sms-time">'+formatTime(msg.time)+'</div>'+
          '</div>'+
        '</div>';
    }).join("");

    wrap.scrollTop=wrap.scrollHeight;
  }

  window.openSmsThread=function(id){
    ensureUI();
    activePersonaId=String(id);
    const person=personaById(activePersonaId);
    if(!person)return;

    const data=threadFor(activePersonaId,true);
    data.thread.unread=0;
    saveStore(data.store);

    document.getElementById("smsListScreen").classList.remove("show");
    document.getElementById("smsSettingsScreen")?.classList.remove("show");
    document.getElementById("smsThreadScreen").classList.add("show");
    renderThreadPerson(person);
    renderBlockHint(activePersonaId);
    applySmsSettings();
    renderSmsMessages();
    updateSmsSendButton();
    maybeDeliverPendingAppeal(activePersonaId);
    setTimeout(()=>document.getElementById("smsInput")?.focus(),80);
  };

  window.backToSmsList=function(){
    activePersonaId=null;
    document.getElementById("smsThreadScreen")?.classList.remove("show");
    document.getElementById("smsSettingsScreen")?.classList.remove("show");
    document.getElementById("smsListScreen")?.classList.add("show");
    applySmsSettings();
    renderSmsList();
  };

  window.openSmsApp=function(){
    ensureUI();
    document.getElementById("baobaoSmsApp").classList.add("show");
    document.getElementById("smsThreadScreen").classList.remove("show");
    document.getElementById("smsSettingsScreen")?.classList.remove("show");
    document.getElementById("smsListScreen").classList.add("show");
    activePersonaId=null;
    applySmsSettings();
    renderSmsList();
  };

  window.closeSmsApp=function(){
    activePersonaId=null;
    document.getElementById("baobaoSmsApp")?.classList.remove("show");
  };

  window.smsInputChanged=function(el){
    el.style.height="auto";
    el.style.height=Math.min(110,el.scrollHeight)+"px";
    updateSmsSendButton();
  };

  function appendSms(personId,role,content,extra){
    const data=threadFor(personId,true);
    const message=Object.assign({
      id:"sms_"+Date.now()+"_"+Math.random().toString(36).slice(2,7),
      role,
      content:String(content||"").trim(),
      time:Date.now()
    },extra||{});

    if(!message.content)return null;

    data.thread.messages.push(message);
    data.thread.updatedAt=message.time;

    if(role==="assistant"&&String(activePersonaId)!==String(personId)){
      data.thread.unread=Number(data.thread.unread||0)+1;
    }

    saveStore(data.store);

    if(String(activePersonaId)===String(personId)){
      renderSmsMessages();
    }else if(document.getElementById("baobaoSmsApp")?.classList.contains("show")){
      renderSmsList();
    }

    return message;
  }

  function personaContext(person){
    return [
      "姓名："+String(person.name||"未命名"),
      person.persona?("完整背景："+person.persona):"",
      person.personality?("性格和说话方式："+person.personality):"",
      person.brief?("简量人设："+person.brief):"",
      Array.isArray(person.tags)&&person.tags.length?("标签："+person.tags.join("、")):"",
      person.setting?("补充设定："+person.setting):"",
      person.prompt?("专属要求："+person.prompt):""
    ].filter(Boolean).join("\n");
  }

  function smsSafeParse(raw,fallback){
    try{return JSON.parse(raw)}catch(e){return fallback}
  }

  function smsTerms(value){
    return Array.from(new Set(String(value||"").toLowerCase().match(/[\u4e00-\u9fff]{1,4}|[a-z0-9]{2,}/g)||[]));
  }

  function roleSpeechSamples(personId){
    const wechat=state.chatRecords&&Array.isArray(state.chatRecords[personId])
      ?state.chatRecords[personId]
      :[];
    const sms=threadFor(personId,true).thread.messages||[];
    return [...wechat,...sms]
      .filter(m=>m&&m.role==="assistant"&&!m.hiddenSystem&&!m.recalled&&!m.generationFailed)
      .slice(-12)
      .map(m=>String(m.content||m.text||"").replace(/\s+/g," ").trim().slice(0,180))
      .filter(Boolean)
      .join("\n");
  }

  function smsMemoryContext(person,userText){
    const id=String(person&&person.id||"");
    const db=smsSafeParse(localStorage.getItem("baobao_memory_engine_v1"),{})||{};
    const own=db.personas&&db.personas[id]||{};
    const shared=db.shared||{};
    const query=String(userText||"").toLowerCase();
    const qWords=smsTerms(query);
    const list=[...(Array.isArray(own.memories)?own.memories:[]),...(Array.isArray(shared.memories)?shared.memories:[])];
    const ranked=list.filter(m=>m&&m.active!==false&&String(m.text||"").trim()).map(m=>{
      const text=String(m.text||"");
      const keys=[...(Array.isArray(m.keywords)?m.keywords:[]),...smsTerms(text)].map(String);
      let score=Number(m.importance||0)+(m.pinned?10:0);
      for(const word of qWords){if(word.length>=2&&(text.toLowerCase().includes(word)||keys.some(k=>String(k).toLowerCase().includes(word))))score+=8;}
      if(m.type==="relationship")score+=2;
      return {m,score};
    }).filter(x=>x.score>=8).sort((a,b)=>b.score-a.score).slice(0,7).map(x=>String(x.m.text||"").trim());
    const lines=[];
    if(String(own.summary||"").trim())lines.push("关系总结："+String(own.summary).trim().slice(0,900));
    ranked.forEach((text,i)=>lines.push((i+1)+". "+text.slice(0,500)));
    return lines.join("\n");
  }

  function smsWorldBookContext(person,userText){
    const store=smsSafeParse(localStorage.getItem("baobao_world_books_v230"),{})||{};
    const entries=Array.isArray(store.entries)?store.entries:[];
    const id=String(person&&person.id||"");
    const name=String(person&&person.name||"");
    const context=(String(userText||"")+"\n"+recentWechat(id)+"\n"+recentSms(id)).toLowerCase();
    return entries.filter(entry=>{
      if(!entry||entry.enabled===false)return false;
      const scope=String(entry.scope||"global");
      if(scope==="persona"&&String(entry.personaId||"")!==id&&String(entry.personaName||"")!==name)return false;
      if(String(entry.mode||"always")==="always")return true;
      const keys=Array.isArray(entry.keywords)?entry.keywords:String(entry.keywords||"").split(/[，,、\s]+/).filter(Boolean);
      return keys.some(key=>context.includes(String(key).toLowerCase()));
    }).sort((a,b)=>Number(b.priority||0)-Number(a.priority||0)).slice(0,8)
      .map(entry=>"〔"+String(entry.name||"世界书")+"〕\n"+String(entry.content||"").trim().slice(0,1200))
      .filter(Boolean).join("\n\n");
  }

  function strictSmsPersonaContext(person,userText){
    const id=String(person&&person.id||"");
    const samples=roleSpeechSamples(id);
    const memory=smsMemoryContext(person,userText);
    const world=smsWorldBookContext(person,userText);
    return [
      "【完整角色档案｜最高优先级】\n"+personaContext(person),
      samples?"【角色过去真实说话样本】\n"+samples:"",
      memory?"【仅属于这个角色的相关记忆】\n"+memory:"",
      world?"【当前触发的世界书】\n"+world:""
    ].filter(Boolean).join("\n\n");
  }

  function recentWechat(personId){
    const arr=state.chatRecords&&Array.isArray(state.chatRecords[personId])
      ?state.chatRecords[personId]
      :[];

    return arr.filter(m=>m&&!m.hiddenSystem&&!m.recalled)
      .slice(-14)
      .map(m=>{
        const who=m.role==="user"?"用户":"角色";
        const content=typeof window.baobaoMessageForAI==="function"
          ?window.baobaoMessageForAI(m)
          :String(m.content||"");
        return who+"："+String(content||"").replace(/\s+/g," ").slice(0,170);
      })
      .join("\n");
  }

  function recentSms(personId){
    const data=threadFor(personId,true);
    return (data.thread.messages||[]).slice(-loadSettings().historyRounds).map(m=>
      (m.role==="user"?"用户":"角色")+"："+String(m.content||"").replace(/\s+/g," ").slice(0,170)
    ).join("\n");
  }

  function maskContext(){
    const mask=currentUserMask();
    if(!mask)return "未填写";
    return [
      mask.name&&("名字："+mask.name),
      mask.alias&&("身份："+mask.alias),
      mask.summary&&("状态："+mask.summary),
      mask.bio&&("个签："+mask.bio),
      mask.note&&("设定："+mask.note)
    ].filter(Boolean).join("；");
  }

  function parseSmsReply(value){
    const cleaned=String(value||"")
      .replace(/```[\s\S]*?```/g,"")
      .replace(/^\s*(?:短信|回复|输出)[:：]\s*/i,"")
      .trim();

    let lines=cleaned.split(/\n+/)
      .map(x=>x.replace(/^\s*(?:[-•*]|\d+[.、])\s*/,"").replace(/^["“]|["”]$/g,"").trim())
      .filter(Boolean);

    if(lines.length===1&&lines[0].includes("|")){
      lines=lines[0].split("|").map(x=>x.trim()).filter(Boolean);
    }

    const merged=[];
    for(const line of lines){
      const degenerate=!/[\u4e00-\u9fffA-Za-z0-9]/.test(line);
      if(degenerate&&merged.length)merged[merged.length-1]=(merged[merged.length-1]+line).trim();
      else if(!degenerate)merged.push(line);
    }

    return merged.slice(0,3).map(x=>x.slice(0,90));
  }

  function fallbackAppeal(person){
    const raw=[
      person&&person.personality,
      person&&person.persona,
      person&&person.brief,
      Array.isArray(person&&person.tags)?person.tags.join(" "):""
    ].filter(Boolean).join(" ");

    if(/冷淡|寡言|高冷|克制/.test(raw)){
      return ["微信拉黑我了？","至少把原因说清楚。"];
    }
    if(/占有欲|强势|偏执|控制|吃醋/.test(raw)){
      return ["拉黑就当结束了？","短信回我。我们把话说清楚。"];
    }
    if(/傲娇|嘴硬|毒舌/.test(raw)){
      return ["行，微信拉黑我。","那短信总能看见吧。给我一次解释的机会。"];
    }
    if(/温柔|体贴|宠|耐心/.test(raw)){
      return ["我知道你现在不想听我说话。","可我不想就这样失去你。等你愿意的时候，回我一下好不好。"];
    }
    return ["我不想我们就这样断掉。","再给我一次把话说清楚的机会。"];
  }

  // 312.1：带自动重试的短信生成请求，尽量避免出现"生成失败"
  async function smsCompletionWithRetry(messages,timeoutMs,label,maxAttempts){
    maxAttempts = maxAttempts || 3;
    let lastErr = null;
    for(let attempt=0; attempt<maxAttempts; attempt++){
      try{
        const task=Promise.resolve().then(()=>window.sendChatCompletion(messages));
        const reply=await Promise.race([
          task,
          new Promise((_,reject)=>setTimeout(()=>reject(new Error((label||"短信")+"生成超时")),timeoutMs||30000))
        ]);
        return reply;
      }catch(e){
        lastErr = e;
        console.warn((label||"短信")+"生成失败，第"+(attempt+1)+"次尝试：",e&&e.message);
        if(attempt < maxAttempts-1){
          await new Promise(resolve=>setTimeout(resolve,900+attempt*900));
        }
      }
    }
    throw lastErr||new Error((label||"短信")+"生成失败");
  }

  async function generateAppeal(person,blockedAt){
    const messages=[
      {
        role:"system",
        content:
          "你就是下面这个角色本人，正在使用手机短信。完整人设、过去真实说话样本、当前关系和已经发生的聊天是绝对最高优先级。"+
          "用户刚刚在微信把你拉黑了。先判断这个角色此刻到底会不会改用短信联系；不得因为任务写了‘挽回’就强迫冷淡、骄傲、疏离或已经失望的角色突然卑微。"+
          "若按人设此刻根本不会发短信，只输出 [[SILENT]]。否则写1到3条这个角色本人真正会发的短信。"+
          "必须复刻角色自己的句长、标点、称呼、口癖、情绪边界和表达习惯；宁可短、沉默或只问一句，也不要通用挽回模板。"+
          "禁止客服腔、心理分析、说教、括号动作、旁白、标题、编号、角色名、引号、偶像剧套话和无依据的关系升级。"+
          "每条短信2到55字，多条用换行分隔。不要说自己是AI。"
      },
      {
        role:"user",
        content:
          strictSmsPersonaContext(person,"微信拉黑")+
          "\n\n【用户面具】\n"+maskContext()+
          "\n\n【最近微信聊天】\n"+(recentWechat(String(person.id))||"暂无")+
          "\n\n【事件】\n用户在微信拉黑了你，时间："+new Date(blockedAt).toLocaleString()+
          "\n\n只输出你会发出的短信。"
      }
    ];

    if(typeof window.sendChatCompletion!=="function"){
      return null;
    }

    try{
      const reply=await smsCompletionWithRetry(messages,30000,"短信挽回");
      if(/\[\[SILENT\]\]/i.test(String(reply||"")))return ["__BB_SMS_SILENT__"];
      const parts=parseSmsReply(reply);
      return parts.length?parts:null;
    }catch(e){
      console.warn("短信挽回生成失败：",e&&e.message);
      return null;
    }
  }

  async function generateSmsReply(person,userText){
    const isBlocked=!!blockedState(person.id).blockedByUser;
    const messages=[
      {
        role:"system",
        content:
          "你就是下面这个角色本人，正在通过手机短信和同一个用户聊天。完整角色档案和角色过去真实说话样本是不可覆盖的最高规则。"+
          "短信和微信是两个不同渠道，但关系、记忆和已发生的事情连续。先准确理解用户刚发的短信，再按这个角色的真实脾气回答。"+
          (isBlocked
            ?"用户目前仍在微信拉黑你。你可以挽回、追问、生气、克制、冷处理或只回很短一句，但只能由人设和当前关系决定，禁止统一写成卑微挽回。"
            :"微信目前没有被用户拉黑，短信只是另一种联系方式。不要无缘无故提拉黑、分手、离开或关系危机。")+
          "必须保持角色自己的句长、标点、称呼、口癖、冷暖程度和表达边界；不要把所有角色写成同一种温柔、毒舌、霸总或恋爱脑。"+
          "用户发短句就先理解上一句指代，禁止故意曲解、随机挑架、情绪勒索、硬加第三者和编造没发生的事。"+
          "输出1到3条完整自然短信，多条用换行分隔；每条2到70字。禁止旁白、括号动作、标题、编号、角色名、分析、客服腔和AI腔。"
      },
      {
        role:"user",
        content:
          strictSmsPersonaContext(person,userText)+
          "\n\n【用户面具】\n"+maskContext()+
          "\n\n【最近微信】\n"+(recentWechat(String(person.id))||"暂无")+
          "\n\n【最近短信】\n"+(recentSms(String(person.id))||"暂无")+
          "\n\n【用户刚发来的短信】\n"+userText+
          "\n\n只输出角色的短信回复。"
      }
    ];

    if(typeof window.sendChatCompletion!=="function"){
      return null;
    }

    try{
      const reply=await smsCompletionWithRetry(messages,30000,"短信回复");
      const parts=parseSmsReply(reply);
      return parts.length?parts:null;
    }catch(e){
      console.warn("短信回复生成失败：",e&&e.message);
      return null;
    }
  }

  const smsReplyRetryTimers={};
  async function replyToSms(personId,userText){
    const person=personaById(personId);
    if(!person||replying.has(String(personId)))return;

    replying.add(String(personId));
    if(String(activePersonaId)===String(personId)){
      document.getElementById("smsTyping")?.classList.add("show");
      document.getElementById("smsSendBtn").disabled=true;
    }

    const replies=await generateSmsReply(person,userText);

    if(String(activePersonaId)===String(personId)){
      document.getElementById("smsTyping")?.classList.remove("show");
      document.getElementById("smsSendBtn").disabled=false;
    }

    if(!Array.isArray(replies)||!replies.length){
      if(String(activePersonaId)===String(personId)&&typeof showToast==="function"){
        showToast("网络不太稳定，正在重试…");
      }
      replying.delete(String(personId));
      if(String(activePersonaId)===String(personId))updateSmsSendButton();
      clearTimeout(smsReplyRetryTimers[String(personId)]);
      smsReplyRetryTimers[String(personId)]=setTimeout(()=>{
        replyToSms(personId,userText);
      },12000+Math.random()*8000);
      return;
    }

    for(let i=0;i<replies.length;i++){
      if(i)await new Promise(resolve=>setTimeout(resolve,650+Math.random()*650));
      appendSms(personId,"assistant",replies[i],{source:"sms_reply"});
    }

    replying.delete(String(personId));
    if(String(activePersonaId)===String(personId)){
      updateSmsSendButton();
    }
    if(typeof showToast==="function"&&String(activePersonaId)!==String(personId)){
      showToast((person.name||"角色")+"给你发了短信");
    }
  }

  function latestUnansweredSms(personId){
    const data=threadFor(personId,true);
    const messages=data.thread.messages||[];
    for(let i=messages.length-1;i>=0;i--){
      const msg=messages[i];
      if(!msg)continue;
      if(msg.role==="assistant")return null;
      if(msg.role==="user")return msg;
    }
    return null;
  }

  function updateSmsSendButton(){
    const button=document.getElementById("smsSendBtn");
    const input=document.getElementById("smsInput");
    if(!button)return;
    const hasText=!!String(input&&input.value||"").trim();
    const waiting=!!(activePersonaId&&latestUnansweredSms(activePersonaId));
    if(hasText){
      button.textContent="↑";
      button.dataset.mode="send";
      button.disabled=false;
      button.setAttribute("aria-label","发送短信");
    }else if(waiting){
      button.textContent="•••";
      button.dataset.mode="reply";
      button.disabled=replying.has(String(activePersonaId));
      button.setAttribute("aria-label","让对方回复");
    }else{
      button.textContent="↑";
      button.dataset.mode="idle";
      button.disabled=true;
      button.setAttribute("aria-label","发送短信");
    }
  }

  window.sendSmsMessage=function(){
    if(!activePersonaId)return;
    const input=document.getElementById("smsInput");
    const text=String(input&&input.value||"").trim();

    if(text){
      input.value="";
      input.style.height="auto";
      appendSms(activePersonaId,"user",text,{source:"user_sms"});
      updateSmsSendButton();
      return;
    }

    const latest=latestUnansweredSms(activePersonaId);
    if(!latest||replying.has(String(activePersonaId)))return;
    updateSmsSendButton();
    replyToSms(activePersonaId,String(latest.content||""));
  };

  window.openSmsSettings=function(){
    ensureUI();
    document.getElementById("smsListScreen")?.classList.remove("show");
    document.getElementById("smsThreadScreen")?.classList.remove("show");
    document.getElementById("smsSettingsScreen")?.classList.add("show");
    applySmsSettings();
  };

  window.closeSmsSettings=function(){
    document.getElementById("smsSettingsScreen")?.classList.remove("show");
    document.getElementById("smsListScreen")?.classList.add("show");
    renderSmsList();
  };

  window.changeSmsHistoryRounds=function(value){
    const settings=loadSettings();
    settings.historyRounds=Math.min(100,Math.max(5,Number(value)||50));
    saveSettings(settings);
  };

  window.setSmsBubbleColor=function(color){
    const settings=loadSettings();
    settings.bubbleColor=color==="green"?"green":"blue";
    saveSettings(settings);
  };

  window.clearAllSmsRecords=function(){
    if(!confirm("确定清空所有短信记录吗？清空后无法恢复。"))return;
    localStorage.removeItem(SMS_KEY);
    localStorage.removeItem(PENDING_KEY);
    activePersonaId=null;
    renderSmsList();
    if(typeof showToast==="function")showToast("短信记录已清空");
  };

  function loadPending(){
    try{return JSON.parse(localStorage.getItem(PENDING_KEY)||"{}")}catch(e){return {}}
  }

  function savePending(data){
    localStorage.setItem(PENDING_KEY,JSON.stringify(data||{}));
  }

  function maybeDeliverPendingAppeal(personId){
    const key=String(personId||"");
    if(!key)return;
    const pending=loadPending();
    const blockedAt=Number(pending[key]||0);
    if(!blockedAt)return;
    const guard="appeal:"+key;
    if(replying.has(guard))return;
    replying.add(guard);
    if(String(activePersonaId)===key)document.getElementById("smsTyping")?.classList.add("show");
    setTimeout(async()=>{
      try{
        await deliverAppeal(key,blockedAt);
      }finally{
        replying.delete(guard);
        if(String(activePersonaId)===key){
          document.getElementById("smsTyping")?.classList.remove("show");
          updateSmsSendButton();
        }
      }
    },180);
  }

  // 312.1：生成失败时不放弃，稍后在后台自动重试，直到成功送达
  const appealRetryTimers={};
  function scheduleAppealRetry(personId,blockedAt){
    const key=String(personId);
    clearTimeout(appealRetryTimers[key]);
    appealRetryTimers[key]=setTimeout(()=>{
      const pending=loadPending();
      if(Number(pending[key]||0)===Number(blockedAt||0)){
        maybeDeliverPendingAppeal(key);
      }
    },15000+Math.random()*10000);
  }

  async function deliverAppeal(personId,blockedAt){
    const person=personaById(personId);
    if(!person)return;

    const stateNow=blockedState(personId);
    if(!stateNow.blockedByUser||Number(stateNow.blockedAt||0)!==Number(blockedAt||0)){
      const pending=loadPending();
      delete pending[String(personId)];
      savePending(pending);
      return;
    }

    const data=threadFor(personId,true);
    const already=(data.thread.messages||[]).some(msg=>
      msg&&msg.source==="wechat_block_appeal"&&Number(msg.blockedAt||0)===Number(blockedAt||0)
    );
    if(already){
      const pending=loadPending();
      delete pending[String(personId)];
      savePending(pending);
      return;
    }

    const replies=await generateAppeal(person,blockedAt);
    if(Array.isArray(replies)&&replies[0]==="__BB_SMS_SILENT__"){
      const silentPending=loadPending();
      delete silentPending[String(personId)];
      savePending(silentPending);
      return;
    }
    if(!Array.isArray(replies)||!replies.length){
      // 312.1：不再写入"生成失败"气泡；保留待处理标记，稍后自动重试
      if(typeof showToast==="function"&&String(activePersonaId)===String(personId)){
        showToast("网络不太稳定，正在重试…");
      }
      scheduleAppealRetry(personId,blockedAt);
      return;
    }
    for(let i=0;i<replies.length;i++){
      if(i)await new Promise(resolve=>setTimeout(resolve,700+Math.random()*750));
      appendSms(personId,"assistant",replies[i],{
        source:"wechat_block_appeal",
        blockedAt:Number(blockedAt||0)
      });
    }

    const pending=loadPending();
    delete pending[String(personId)];
    savePending(pending);

    if(typeof showToast==="function"){
      showToast((person.name||"角色")+"改用短信联系你了");
    }
  }

  window.baobaoScheduleSmsAppeal=function(personId,blockedAt){
    const key=String(personId);
    const pending=loadPending();
    pending[key]=Number(blockedAt||Date.now());
    savePending(pending);
    // 312.1：不需要用户先点进对应短信会话，直接在后台生成并推送
    maybeDeliverPendingAppeal(key);
  };

  function restorePendingAppeals(){
    // 312.1：应用启动时把所有待处理的挽回短信都在后台补发一遍
    const pending=loadPending();
    Object.keys(pending).forEach(key=>{
      if(Number(pending[key]))maybeDeliverPendingAppeal(key);
    });
    if(document.getElementById("baobaoSmsApp")?.classList.contains("show"))renderSmsList();
  }

  function migrateDesktopApp(){
    if(!Array.isArray(state.page1Apps))return;
    state.page1Apps.forEach(app=>{
      if(app&&app.id==="persona"){
        app.label="短信";
        app.action="sms";
      }
    });
    if(typeof renderPages==="function")renderPages();
    if(typeof saveLocal==="function")saveLocal();
  }

  document.addEventListener("DOMContentLoaded",()=>{
    ensureUI();
    applySmsSettings();
    migrateDesktopApp();
    restorePendingAppeals();
  });

  setTimeout(()=>{
    ensureUI();
    migrateDesktopApp();
  },600);

  window.BaobaoSms={
    open:window.openSmsApp,
    thread:window.openSmsThread,
    append:appendSms,
    scheduleAppeal:window.baobaoScheduleSmsAppeal,
    version:"1.0"
  };
})();
;

/* baobao-offline-mode-v191-script */
(function(){
  "use strict";

  const STORE_KEY="baobao_offline_mode_v191";
  let activePersonaId="";
  let activeSessionId="";
  let busy=false;

  function esc(value){
    return typeof escapeHtml==="function"
      ?escapeHtml(String(value==null?"":value))
      :String(value==null?"":value)
        .replace(/&/g,"&amp;")
        .replace(/</g,"&lt;")
        .replace(/>/g,"&gt;")
        .replace(/"/g,"&quot;");
  }

  function persona(){
    return window.currentChatPersona ||
      ((state.personas||[]).find(p=>String(p.id)===String(state.activeChatId))) ||
      null;
  }

  function loadStore(){
    try{
      const data=JSON.parse(localStorage.getItem(STORE_KEY)||"{}");
      return data&&typeof data==="object"?data:{};
    }catch(e){
      return {};
    }
  }

  function saveStore(store){
    try{
      Object.values(store).forEach(bucket=>{
        if(!bucket||!Array.isArray(bucket.sessions))return;
        bucket.sessions=bucket.sessions.slice(-18);
        bucket.sessions.forEach(session=>{
          session.entries=Array.isArray(session.entries)
            ?session.entries.slice(-120)
            :[];
        });
      });
      localStorage.setItem(STORE_KEY,JSON.stringify(store));
      return true;
    }catch(e){
      console.warn("线下模式保存失败：",e);
      if(typeof showToast==="function")showToast("线下模式存储空间不足",true);
      return false;
    }
  }

  function makeSession(){
    const now=Date.now();
    return {
      id:"offline_"+now+"_"+Math.random().toString(36).slice(2,7),
      title:"新的线下剧情",
      location:"未设定地点",
      sceneTime:"当前",
      createdAt:now,
      updatedAt:now,
      entries:[]
    };
  }

  function ensureBucket(personaId){
    const store=loadStore();
    const key=String(personaId);
    if(!store[key]){
      const first=makeSession();
      store[key]={activeSessionId:first.id,sessions:[first]};
      saveStore(store);
    }
    const bucket=store[key];
    if(!Array.isArray(bucket.sessions)||!bucket.sessions.length){
      const first=makeSession();
      bucket.sessions=[first];
      bucket.activeSessionId=first.id;
      saveStore(store);
    }
    if(!bucket.sessions.some(s=>s.id===bucket.activeSessionId)){
      bucket.activeSessionId=bucket.sessions[bucket.sessions.length-1].id;
      saveStore(store);
    }
    return {store,bucket,key};
  }

  function currentSession(){
    if(!activePersonaId)return null;
    const data=ensureBucket(activePersonaId);
    const id=activeSessionId||data.bucket.activeSessionId;
    return data.bucket.sessions.find(s=>s.id===id)||data.bucket.sessions[0]||null;
  }

  function updateSession(mutator){
    if(!activePersonaId)return null;
    const data=ensureBucket(activePersonaId);
    const index=data.bucket.sessions.findIndex(s=>s.id===(activeSessionId||data.bucket.activeSessionId));
    if(index<0)return null;
    const session=data.bucket.sessions[index];
    mutator(session,data);
    session.updatedAt=Date.now();
    data.bucket.activeSessionId=session.id;
    activeSessionId=session.id;
    saveStore(data.store);
    return session;
  }

  function ensureUI(){
    if(document.getElementById("baobaoOfflineMode"))return;
    const root=document.querySelector(".phone")||document.body;
    const page=document.createElement("div");
    page.id="baobaoOfflineMode";
    page.innerHTML=
      '<div class="bb-offline-status-space"></div>'+
      '<header class="bb-offline-head">'+
        '<button class="bb-offline-back" onclick="closeOfflineMode()">‹</button>'+
        '<div class="bb-offline-title-wrap">'+
          '<div class="bb-offline-title" id="bbOfflineTitle">线下模式</div>'+
          '<div class="bb-offline-scene-meta" id="bbOfflineSceneMeta"></div>'+
        '</div>'+
        '<div class="bb-offline-head-actions">'+
          '<button class="bb-offline-icon-btn" onclick="openOfflineHistory()" title="历史">'+
            '<svg viewBox="0 0 24 24"><path d="M4 4v5h5"/><path d="M5.4 8.8A8 8 0 1 1 4 14"/><path d="M12 7v5l3 2"/></svg>'+
          '</button>'+
          '<button class="bb-offline-icon-btn" onclick="openOfflineSettings()" title="场景设置">'+
            '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l-1.9 1.9a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.02 1.56h-2.68a1.7 1.7 0 0 0-1.02-1.56 1.7 1.7 0 0 0-1.88.34l-1.9-1.9A1.7 1.7 0 0 0 7.8 15a1.7 1.7 0 0 0-1.56-1.02V11.3A1.7 1.7 0 0 0 7.8 10a1.7 1.7 0 0 0-.34-1.88l1.9-1.9a1.7 1.7 0 0 0 1.88.34A1.7 1.7 0 0 0 12.26 5h2.68a1.7 1.7 0 0 0 1.02 1.56 1.7 1.7 0 0 0 1.88-.34l1.9 1.9A1.7 1.7 0 0 0 19.4 10a1.7 1.7 0 0 0 1.56 1.3v2.68A1.7 1.7 0 0 0 19.4 15Z"/></svg>'+
          '</button>'+
          '<button class="bb-offline-icon-btn" onclick="newOfflineScene()" title="新场景">＋</button>'+
        '</div>'+
      '</header>'+
      '<main class="bb-offline-feed" id="bbOfflineFeed"></main>'+
      '<div class="bb-offline-loading" id="bbOfflineLoading">正在继续这段线下剧情…</div>'+
      '<footer class="bb-offline-composer">'+
        '<div class="bb-offline-input-wrap">'+
          '<textarea id="bbOfflineInput" rows="1" placeholder="在线下剧情模式中输入…" oninput="offlineInputResize(this)"></textarea>'+
          '<button class="bb-offline-continue" id="bbOfflineContinueBtn" onclick="continueOfflineScene()">续</button>'+
        '</div>'+
        '<button class="bb-offline-send" id="bbOfflineSendBtn" onclick="sendOfflineInput()" title="发送">'+
          '<svg viewBox="0 0 24 24"><path d="m4 12 16-8-6.5 16-2.5-6.5z"/><path d="M11 13.5 20 4"/></svg>'+
        '</button>'+
      '</footer>'+
      '<div class="bb-offline-modal-mask" id="bbOfflineSettingsMask" onclick="if(event.target===this)closeOfflineSheet(\'settings\')">'+
        '<div class="bb-offline-sheet">'+
          '<div class="bb-offline-sheet-title">线下场景设置</div>'+
          '<label class="bb-offline-form-label">这一页的标题</label>'+
          '<input class="bb-offline-form-input" id="bbOfflineSceneTitleInput" type="text" placeholder="例如：放学后的雨">'+
          '<label class="bb-offline-form-label">地点</label>'+
          '<input class="bb-offline-form-input" id="bbOfflineLocationInput" type="text" placeholder="例如：学校门口">'+
          '<label class="bb-offline-form-label">时间</label>'+
          '<input class="bb-offline-form-input" id="bbOfflineTimeInput" type="text" placeholder="例如：傍晚 18:20">'+
          '<div class="bb-offline-sheet-actions">'+
            '<button class="bb-offline-cancel" onclick="closeOfflineSheet(\'settings\')">取消</button>'+
            '<button class="bb-offline-save" onclick="saveOfflineSettings()">保存</button>'+
          '</div>'+
        '</div>'+
      '</div>'+
      '<div class="bb-offline-modal-mask" id="bbOfflineHistoryMask" onclick="if(event.target===this)closeOfflineSheet(\'history\')">'+
        '<div class="bb-offline-sheet">'+
          '<div class="bb-offline-sheet-title">线下记录</div>'+
          '<div id="bbOfflineHistoryList"></div>'+
          '<div class="bb-offline-sheet-actions">'+
            '<button class="bb-offline-cancel" onclick="closeOfflineSheet(\'history\')">关闭</button>'+
          '</div>'+
        '</div>'+
      '</div>';
    root.appendChild(page);
  }

  function avatarHtml(person){
    if(person&&person.photo){
      return '<div class="bb-offline-avatar"><img src="'+esc(person.photo)+'" alt=""></div>';
    }
    return '<div class="bb-offline-avatar">'+esc(String(person&&person.name||"线").slice(0,1))+'</div>';
  }

  function userAvatarHtml(){
    const photo=state.userProfile&&state.userProfile.photo;
    if(photo){
      return '<div class="bb-offline-avatar"><img src="'+esc(photo)+'" alt=""></div>';
    }
    return '<div class="bb-offline-avatar">我</div>';
  }

  function formatClock(time){
    const d=new Date(time||Date.now());
    return String(d.getHours()).padStart(2,"0")+":"+String(d.getMinutes()).padStart(2,"0");
  }

  function normalizeBlocks(blocks){
    if(!Array.isArray(blocks))return [];
    return blocks.map(block=>({
      type:block&&block.type==="thought"?"thought":"narrative",
      text:String(block&&block.text||"").trim()
    })).filter(block=>block.text);
  }

  function renderOffline(){
    ensureUI();
    const person=persona();
    const session=currentSession();
    if(!person||!session)return;

    document.getElementById("bbOfflineTitle").textContent=person.name||"线下模式";
    document.getElementById("bbOfflineSceneMeta").textContent=
      [session.title,session.location,session.sceneTime].filter(Boolean).join(" · ");

    const feed=document.getElementById("bbOfflineFeed");
    const entries=Array.isArray(session.entries)?session.entries:[];

    if(!entries.length){
      feed.innerHTML=
        '<div class="bb-offline-empty">'+
          '<b style="color:#58575d">线下剧情框架已建立</b><br>'+
          '在底部输入你说的话、动作或想推进的场景。<br>'+
          '正文会使用深色文字，角色不说出口的心理描写会使用浅灰斜体。'+
        '</div>';
      return;
    }

    let floor=0;
    feed.innerHTML=entries.map(entry=>{
      floor++;
      const isUser=entry.role==="user";
      const blocks=isUser
        ?[{type:"narrative",text:String(entry.text||"")}]
        :normalizeBlocks(entry.blocks);

      return '<article class="bb-offline-entry '+(isUser?"bb-offline-user-entry":"")+'">'+
        '<div class="bb-offline-entry-head">'+
          (isUser?userAvatarHtml():avatarHtml(person))+
          '<div class="bb-offline-who">'+
            '<div class="bb-offline-name">'+esc(isUser?"我":(person.name||"角色"))+'</div>'+
            '<div class="bb-offline-handle">@'+esc(isUser?"User":String(person.name||"Offline").replace(/\s+/g,""))+'</div>'+
          '</div>'+
          '<div class="bb-offline-floor">#'+floor+' Floor</div>'+
        '</div>'+
        blocks.map(block=>
          '<div class="bb-offline-block '+block.type+'">'+
            esc(block.text).replace(/\n/g,"<br>")+
          '</div>'
        ).join("")+
        '<div class="bb-offline-entry-foot">'+
          '<span>'+formatClock(entry.time)+'</span>'+
          '<span>'+(isUser?"你的行动":"线下剧情")+'</span>'+
        '</div>'+
      '</article>';
    }).join("");

    requestAnimationFrame(()=>{feed.scrollTop=feed.scrollHeight});
  }

  function fullPersonaContext(person){
    return [
      "姓名："+String(person.name||"未命名"),
      person.persona?("完整背景："+person.persona):"",
      person.personality?("性格与说话方式："+person.personality):"",
      person.brief?("简量人设："+person.brief):"",
      person.setting?("补充设定："+person.setting):"",
      person.description?("描述："+person.description):"",
      person.prompt?("专属要求："+person.prompt):"",
      Array.isArray(person.tags)&&person.tags.length?("标签："+person.tags.join("、")):""
    ].filter(Boolean).join("\n");
  }

  function recentWechat(personId){
    const arr=state.chatRecords&&Array.isArray(state.chatRecords[personId])
      ?state.chatRecords[personId]
      :[];
    return arr
      .filter(msg=>msg&&!msg.hiddenSystem&&!msg.recalled)
      .slice(-10)
      .map(msg=>{
        const who=msg.role==="user"?"用户":"角色";
        const content=typeof window.baobaoMessageForAI==="function"
          ?window.baobaoMessageForAI(msg)
          :String(msg.content||"");
        return who+"："+String(content||"").replace(/\s+/g," ").slice(0,160);
      })
      .join("\n");
  }

  function recentOfflineText(session){
    return (session.entries||[]).slice(-10).map(entry=>{
      if(entry.role==="user")return "用户行动："+String(entry.text||"");
      return normalizeBlocks(entry.blocks).map(block=>
        (block.type==="thought"?"角色内心（用户不知道）":"场景正文")+"："+block.text
      ).join("\n");
    }).join("\n");
  }

  function parseOfflineReply(raw){
    const value=String(raw||"")
      .replace(/```(?:json|text)?/gi,"")
      .replace(/```/g,"")
      .trim();

    if(!value)return [];

    const marker=/\[(正文|心里|心理|内心)\]\s*([\s\S]*?)(?=\[(?:正文|心里|心理|内心)\]|$)/g;
    const blocks=[];
    let match;

    while((match=marker.exec(value))){
      const type=match[1]==="正文"?"narrative":"thought";
      const part=String(match[2]||"").trim();
      if(part)blocks.push({type,text:part});
    }

    if(blocks.length)return blocks;

    const thoughtMatch=value.match(/(?:<thought>|【心里】)([\s\S]*?)(?:<\/thought>|【\/心里】)/i);
    if(thoughtMatch){
      const before=value.slice(0,thoughtMatch.index).trim();
      const after=value.slice(thoughtMatch.index+thoughtMatch[0].length).trim();
      if(before)blocks.push({type:"narrative",text:before});
      blocks.push({type:"thought",text:thoughtMatch[1].trim()});
      if(after)blocks.push({type:"narrative",text:after});
      return blocks.filter(x=>x.text);
    }

    return [{type:"narrative",text:value}];
  }

  function fallbackBlocks(person,userText,continueOnly){
    const name=String(person&&person.name||"他");
    const action=String(userText||"").trim();

    return [
      {
        type:"narrative",
        text:action
          ?name+"安静地看着你，像是在认真分辨你这句话里的每一点情绪。周围的声音并没有停下，可这一小块距离忽然变得很近。"
          :name+"没有急着打破沉默，只是顺着刚才未说完的情绪继续留在你身边。"
      },
      {
        type:"thought",
        text:continueOnly
          ?"再等一下。也许她下一秒就会愿意把真正想说的话告诉我。"
          :"她这样说的时候到底在想什么？我不想逼得太紧，却也不想装作毫不在意。"
      },
      {
        type:"narrative",
        text:"“我在听。”他低声说，语气比平时慢了一些，“你继续说。”"
      }
    ];
  }

  async function requestOfflineReply(userText,continueOnly){
    const person=persona();
    const session=currentSession();
    if(!person||!session)return [];

    if(typeof window.sendChatCompletion!=="function"){
      return fallbackBlocks(person,userText,continueOnly);
    }

    const messages=[
      {
        role:"system",
        content:
          "你正在创作沉浸式“线下剧情模式”，必须严格扮演角色本人。"+
          "这不是微信聊天，不要使用聊天气泡口吻；要写成连贯的现实场景、动作、对白与氛围。"+
          "普通场景、动作和说出口的对白必须写在[正文]下面。"+
          "角色没有说出口、用户无法直接知道的真实心理必须单独写在[心里]下面。"+
          "心里描写不能伪装成旁白，也不能让用户角色凭空知道。"+
          "只允许输出[正文]和[心里]标记，不得输出分析、标题、说明或选项。"+
          "每次写2到5个段落，避免空洞华丽辞藻，动作与对白必须符合完整人设、关系和当前场景。"+
          "不要替用户决定重要行动，不要擅自让用户说话。"
      },
      {
        role:"user",
        content:
          "【角色完整人设】\n"+fullPersonaContext(person)+
          "\n\n【当前场景】\n标题："+session.title+
          "\n地点："+session.location+
          "\n时间："+session.sceneTime+
          "\n\n【最近微信内容，仅用于记住关系和上下文】\n"+(recentWechat(String(person.id))||"暂无")+
          "\n\n【当前线下剧情】\n"+(recentOfflineText(session)||"刚刚进入场景，还没有正文")+
          "\n\n【用户本次输入】\n"+(
            continueOnly
              ?"用户没有新增台词或动作，请自然续写上一段，不要突然跳场景。"
              :String(userText||"")
          )+
          "\n\n严格按以下格式输出：\n[正文]\n场景、动作与对白\n[心里]\n角色没有说出口的真实想法\n[正文]\n自然继续。"
      }
    ];

    try{
      const task=Promise.resolve().then(()=>
        window.sendChatCompletion(messages)
      );
      const reply=await Promise.race([
        task,
        new Promise((_,reject)=>
          setTimeout(()=>reject(new Error("线下剧情生成超时")),120000)
        )
      ]);
      const blocks=parseOfflineReply(reply);
      return blocks.length?blocks:fallbackBlocks(person,userText,continueOnly);
    }catch(e){
      console.warn("线下剧情生成失败：",e&&e.message);
      return fallbackBlocks(person,userText,continueOnly);
    }
  }

  function setBusy(value){
    busy=!!value;
    document.getElementById("bbOfflineLoading")?.classList.toggle("show",busy);
    const send=document.getElementById("bbOfflineSendBtn");
    const cont=document.getElementById("bbOfflineContinueBtn");
    if(send)send.disabled=busy;
    if(cont)cont.disabled=busy;
  }

  async function advanceOffline(userText,continueOnly){
    if(busy)return;
    const trimmed=String(userText||"").trim();
    if(!continueOnly&&!trimmed)return;

    if(!continueOnly){
      updateSession(session=>{
        session.entries.push({
          id:"offline_user_"+Date.now(),
          role:"user",
          text:trimmed,
          time:Date.now()
        });
      });
      renderOffline();
    }

    setBusy(true);
    const blocks=await requestOfflineReply(trimmed,continueOnly);
    updateSession(session=>{
      session.entries.push({
        id:"offline_role_"+Date.now(),
        role:"assistant",
        blocks:normalizeBlocks(blocks),
        time:Date.now()
      });
    });
    setBusy(false);
    renderOffline();
  }

  window.openOfflineMode=function(){
    ensureUI();
    const person=persona();
    if(!person){
      if(typeof showToast==="function")showToast("请先进入一个角色的私聊",true);
      return;
    }

    if(typeof window.closeBaobaoTools==="function")window.closeBaobaoTools();
    const tools=document.getElementById("tools");
    if(tools)tools.style.display="none";

    activePersonaId=String(person.id||state.activeChatId||person.name||"default");
    const data=ensureBucket(activePersonaId);
    activeSessionId=data.bucket.activeSessionId;

    document.getElementById("baobaoOfflineMode").classList.add("show");
    renderOffline();
  };

  window.closeOfflineMode=function(){
    document.getElementById("baobaoOfflineMode")?.classList.remove("show");
    closeOfflineSheet("settings");
    closeOfflineSheet("history");
    setBusy(false);
  };

  window.offlineInputResize=function(el){
    el.style.height="auto";
    el.style.height=Math.min(116,el.scrollHeight)+"px";
  };

  window.sendOfflineInput=function(){
    const input=document.getElementById("bbOfflineInput");
    const value=String(input&&input.value||"").trim();
    if(!value)return;
    input.value="";
    input.style.height="auto";
    advanceOffline(value,false);
  };

  window.continueOfflineScene=function(){
    advanceOffline("",true);
  };

  window.openOfflineSettings=function(){
    const session=currentSession();
    if(!session)return;
    document.getElementById("bbOfflineSceneTitleInput").value=session.title||"";
    document.getElementById("bbOfflineLocationInput").value=session.location||"";
    document.getElementById("bbOfflineTimeInput").value=session.sceneTime||"";
    document.getElementById("bbOfflineSettingsMask").classList.add("show");
  };

  window.saveOfflineSettings=function(){
    updateSession(session=>{
      session.title=String(document.getElementById("bbOfflineSceneTitleInput").value||"新的线下剧情").trim();
      session.location=String(document.getElementById("bbOfflineLocationInput").value||"未设定地点").trim();
      session.sceneTime=String(document.getElementById("bbOfflineTimeInput").value||"当前").trim();
    });
    closeOfflineSheet("settings");
    renderOffline();
    if(typeof showToast==="function")showToast("线下场景已保存");
  };

  window.openOfflineHistory=function(){
    const data=ensureBucket(activePersonaId);
    const list=document.getElementById("bbOfflineHistoryList");
    list.innerHTML=data.bucket.sessions.slice().reverse().map(session=>
      '<div class="bb-offline-history-item '+(session.id===activeSessionId?"active":"")+'" onclick="loadOfflineSession(\''+esc(session.id)+'\')">'+
        '<div class="bb-offline-history-name">'+esc(session.title||"未命名场景")+'</div>'+
        '<div class="bb-offline-history-meta">'+
          esc([session.location,session.sceneTime,(session.entries||[]).length+"层"].filter(Boolean).join(" · "))+
        '</div>'+
      '</div>'
    ).join("");
    document.getElementById("bbOfflineHistoryMask").classList.add("show");
  };

  window.loadOfflineSession=function(id){
    const data=ensureBucket(activePersonaId);
    if(!data.bucket.sessions.some(s=>s.id===id))return;
    data.bucket.activeSessionId=id;
    activeSessionId=id;
    saveStore(data.store);
    closeOfflineSheet("history");
    renderOffline();
  };

  window.newOfflineScene=function(){
    if(busy)return;
    const session=currentSession();
    if(session&&session.entries&&session.entries.length){
      if(!confirm("新建一段线下剧情吗？当前记录会保留在历史中。"))return;
    }

    const data=ensureBucket(activePersonaId);
    const next=makeSession();
    data.bucket.sessions.push(next);
    data.bucket.activeSessionId=next.id;
    activeSessionId=next.id;
    saveStore(data.store);
    renderOffline();
    openOfflineSettings();
  };

  window.closeOfflineSheet=function(type){
    const id=type==="history"?"bbOfflineHistoryMask":"bbOfflineSettingsMask";
    document.getElementById(id)?.classList.remove("show");
  };

  function ensureToolEntry(){
    const grid=document.querySelector("#bbToolSheet .bb-tool-grid");
    if(!grid)return;
    let item=grid.querySelector(".bb-offline-tool");
    if(!item){
      item=document.createElement("div");
      item.className="bb-tool-item bb-offline-tool";
      item.onclick=function(){
        window.openOfflineMode();
      };
      item.innerHTML=
        '<div class="bb-tool-icon">'+
          '<svg viewBox="0 0 24 24" style="width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round">'+
            '<path d="M4 5h16v14H4z"/><path d="M8 9h8M8 13h6"/>'+
          '</svg>'+
        '</div>线下';
      grid.appendChild(item);
    }
  }

  document.addEventListener("DOMContentLoaded",()=>{
    ensureUI();
    ensureToolEntry();
  });

  setTimeout(()=>{
    ensureUI();
    ensureToolEntry();
  },600);

  setInterval(ensureToolEntry,6000);

  window.BaobaoOfflineMode={
    open:window.openOfflineMode,
    render:renderOffline,
    version:"1.0-framework"
  };
})();
;

/* baobao-offline-v192-script */
(function(){
  "use strict";
  const STORE_KEY='baobao_offline_mode_v191';
  let activePersonaId='';
  let activeSessionId='';
  let busy=false;

  function esc(v){
    const s=String(v==null?'':v);
    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function $(id){return document.getElementById(id)}
  function persona(){
    return window.currentChatPersona || ((window.state&&Array.isArray(state.personas)?state.personas:[]).find(p=>String(p.id)===String(state.activeChatId))) || null;
  }
  function currentUserMask(){
    const masks=window.state&&Array.isArray(state.userMasks)?state.userMasks:[];
    if(!masks.length) return null;
    return masks.find(m=>m&&m.id===state.activeUserMaskId) || masks[0] || null;
  }
  function userAvatarSrc(){
    const mask=currentUserMask();
    const wp=state.wechatProfile||{};
    return (mask&&mask.avatar) || wp.avatar || state.charAvatar || state.avatar || '';
  }
  function userDisplayName(){
    const mask=currentUserMask();
    const wp=state.wechatProfile||{};
    return (mask&&mask.name) || wp.name || state.name || '我';
  }
  function loadStore(){
    try{ const x=JSON.parse(localStorage.getItem(STORE_KEY)||'{}'); return x&&typeof x==='object'?x:{} }catch(e){ return {} }
  }
  function saveStore(store){
    try{
      Object.values(store).forEach(bucket=>{
        if(!bucket||!Array.isArray(bucket.sessions)) return;
        bucket.sessions=bucket.sessions.slice(-18);
        bucket.sessions.forEach(session=>{ session.entries=Array.isArray(session.entries)?session.entries.slice(-120):[]; });
      });
      localStorage.setItem(STORE_KEY,JSON.stringify(store));
      return true;
    }catch(e){
      console.warn('线下模式保存失败',e);
      if(typeof showToast==='function') showToast('线下模式存储空间不足',true);
      return false;
    }
  }
  function makeSession(){
    const now=Date.now();
    return {id:'offline_'+now+'_'+Math.random().toString(36).slice(2,7),title:'新的线下剧情',location:'未设定地点',sceneTime:'当前',createdAt:now,updatedAt:now,entries:[]};
  }
  function ensureBucket(personaId){
    const store=loadStore();
    const key=String(personaId);
    if(!store[key]){ const first=makeSession(); store[key]={activeSessionId:first.id,sessions:[first]}; }
    const bucket=store[key];
    if(!Array.isArray(bucket.sessions)||!bucket.sessions.length){ const first=makeSession(); bucket.sessions=[first]; bucket.activeSessionId=first.id; }
    if(!bucket.sessions.some(s=>s.id===bucket.activeSessionId)) bucket.activeSessionId=bucket.sessions[bucket.sessions.length-1].id;
    saveStore(store);
    return {store,bucket};
  }
  function currentSession(){
    if(!activePersonaId) return null;
    const data=ensureBucket(activePersonaId);
    const id=activeSessionId||data.bucket.activeSessionId;
    return data.bucket.sessions.find(s=>s.id===id) || data.bucket.sessions[0] || null;
  }
  function updateSession(mutator){
    if(!activePersonaId) return null;
    const data=ensureBucket(activePersonaId);
    const idx=data.bucket.sessions.findIndex(s=>s.id===(activeSessionId||data.bucket.activeSessionId));
    if(idx<0) return null;
    const session=data.bucket.sessions[idx];
    mutator(session,data);
    session.updatedAt=Date.now();
    data.bucket.activeSessionId=session.id;
    activeSessionId=session.id;
    saveStore(data.store);
    return session;
  }
  function ensurePage(){
    let page=$('baobaoOfflineMode');
    if(!page){
      page=document.createElement('div');
      page.id='baobaoOfflineMode';
      (document.querySelector('.phone')||document.body).appendChild(page);
    }
    if(page.dataset.v192==='1') return page;
    page.dataset.v192='1';
    page.className='bb-offline-v192';
    page.innerHTML=''
      +'<div class="bb-offline-status-space"></div>'
      +'<header class="bb-offline-head">'
      +'  <button class="bb-offline-back" onclick="closeOfflineMode()">‹</button>'
      +'  <div class="bb-offline-title-wrap">'
      +'    <div class="bb-offline-title" id="bbOfflineTitle">线下模式</div>'
      +'    <div class="bb-offline-scene-meta" id="bbOfflineSceneMeta"></div>'
      +'  </div>'
      +'  <div class="bb-offline-head-actions">'
      +'    <button class="bb-offline-icon-btn" onclick="openOfflineHistory()" title="历史"><svg viewBox="0 0 24 24"><path d="M4 4v5h5"/><path d="M5.4 8.8A8 8 0 1 1 4 14"/><path d="M12 7v5l3 2"/></svg></button>'
      +'    <button class="bb-offline-icon-btn" onclick="openOfflineSettings()" title="场景设置"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l-1.9 1.9a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1.02 1.56h-2.68a1.7 1.7 0 0 0-1.02-1.56 1.7 1.7 0 0 0-1.88.34l-1.9-1.9A1.7 1.7 0 0 0 7.8 15a1.7 1.7 0 0 0-1.56-1.02V11.3A1.7 1.7 0 0 0 7.8 10a1.7 1.7 0 0 0-.34-1.88l1.9-1.9a1.7 1.7 0 0 0 1.88.34A1.7 1.7 0 0 0 12.26 5h2.68a1.7 1.7 0 0 0 1.02 1.56 1.7 1.7 0 0 0 1.88-.34l1.9 1.9A1.7 1.7 0 0 0 19.4 10a1.7 1.7 0 0 0 1.56 1.3v2.68A1.7 1.7 0 0 0 19.4 15Z"/></svg></button>'
      +'    <button class="bb-offline-icon-btn" onclick="newOfflineScene()" title="新场景">＋</button>'
      +'  </div>'
      +'</header>'
      +'<main class="bb-offline-feed" id="bbOfflineFeed"></main>'
      +'<div class="bb-offline-loading" id="bbOfflineLoading">正在继续这段线下剧情…</div>'
      +'<footer class="bb-offline-composer">'
      +'  <div class="bb-offline-input-wrap">'
      +'    <textarea id="bbOfflineInput" rows="1" placeholder="在线下剧情模式中输入…" oninput="offlineInputResize(this)"></textarea>'
      +'    <button class="bb-offline-continue" id="bbOfflineContinueBtn" onclick="continueOfflineScene()">续</button>'
      +'  </div>'
      +'  <button class="bb-offline-send" id="bbOfflineSendBtn" onclick="sendOfflineInput()" title="发送"><svg viewBox="0 0 24 24"><path d="m4 12 16-8-6.5 16-2.5-6.5z"/><path d="M11 13.5 20 4"/></svg></button>'
      +'</footer>'
      +'<div class="bb-offline-modal-mask" id="bbOfflineSettingsMask" onclick="if(event.target===this)closeOfflineSheet(\'settings\')"><div class="bb-offline-sheet"><div class="bb-offline-sheet-title">线下场景设置</div><label class="bb-offline-form-label">这一页的标题</label><input class="bb-offline-form-input" id="bbOfflineSceneTitleInput" type="text" placeholder="例如：放学后的雨"><label class="bb-offline-form-label">地点</label><input class="bb-offline-form-input" id="bbOfflineLocationInput" type="text" placeholder="例如：学校门口"><label class="bb-offline-form-label">时间</label><input class="bb-offline-form-input" id="bbOfflineTimeInput" type="text" placeholder="例如：傍晚 18:20"><div class="bb-offline-sheet-actions"><button class="bb-offline-cancel" onclick="closeOfflineSheet(\'settings\')">取消</button><button class="bb-offline-save" onclick="saveOfflineSettings()">保存</button></div></div></div>'
      +'<div class="bb-offline-modal-mask" id="bbOfflineHistoryMask" onclick="if(event.target===this)closeOfflineSheet(\'history\')"><div class="bb-offline-sheet"><div class="bb-offline-sheet-title">线下记录</div><div id="bbOfflineHistoryList"></div><div class="bb-offline-sheet-actions"><button class="bb-offline-cancel" onclick="closeOfflineSheet(\'history\')">关闭</button></div></div></div>';
    return page;
  }
  function avatarHTML(src,fallback){
    return '<div class="bb-offline-avatar">'+(src?'<img src="'+esc(src)+'" alt="">':esc((fallback||'我').slice(0,1)))+'</div>';
  }
  function formatClock(time){ const d=new Date(time||Date.now()); return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0') }
  function normalizeBlocks(blocks){ return Array.isArray(blocks)?blocks.map(b=>({type:b&&b.type==='thought'?'thought':'narrative',text:String(b&&b.text||'').trim()})).filter(b=>b.text):[] }
  function renderOffline(){
    ensurePage();
    const person=persona(), session=currentSession();
    if(!person||!session) return;
    $('bbOfflineTitle').textContent=person.name||'线下模式';
    $('bbOfflineSceneMeta').textContent=[session.title,session.location,session.sceneTime].filter(Boolean).join(' · ');
    const feed=$('bbOfflineFeed');
    const entries=Array.isArray(session.entries)?session.entries:[];
    if(!entries.length){
      feed.innerHTML='<div class="bb-offline-empty"><b style="color:#585450">线下剧情框架已建立</b><br>在底部输入你说的话、动作或想推进的场景。<br>我把页面重新细化过了，头像也会优先同步线上微信/面具头像。</div>';
      return;
    }
    let floor=0;
    const meName=userDisplayName(), meAvatar=userAvatarSrc();
    feed.innerHTML=entries.map(entry=>{
      floor++;
      const isUser=entry.role==='user';
      const blocks=isUser?[{type:'narrative',text:String(entry.text||'')}]:normalizeBlocks(entry.blocks);
      return '<article class="bb-offline-entry '+(isUser?'bb-offline-user-entry':'')+'">'
        +'<div class="bb-offline-entry-head">'
        +(isUser?avatarHTML(meAvatar,meName):avatarHTML(person.photo||person.avatar||'',person.name||'他'))
        +'<div class="bb-offline-who"><div class="bb-offline-name">'+esc(isUser?meName:(person.name||'角色'))+'</div><div class="bb-offline-handle">@'+esc(isUser?'User':String(person.name||'Offline').replace(/\s+/g,''))+'</div></div>'
        +'<div class="bb-offline-floor">#'+floor+' Floor</div></div>'
        +blocks.map(block=>'<div class="bb-offline-block '+block.type+'">'+esc(block.text).replace(/\n/g,'<br>')+'</div>').join('')
        +'<div class="bb-offline-entry-foot"><span>'+formatClock(entry.time)+'</span><span>'+(isUser?'你的行动':'线下剧情')+'</span></div></article>';
    }).join('');
    requestAnimationFrame(()=>{feed.scrollTop=feed.scrollHeight;});
  }
  function fullPersonaContext(person){
    return [
      '姓名：'+String(person.name||'未命名'),
      person.persona?('完整背景：'+person.persona):'',
      person.personality?('性格与说话方式：'+person.personality):'',
      person.brief?('简量人设：'+person.brief):'',
      person.setting?('补充设定：'+person.setting):'',
      person.description?('描述：'+person.description):'',
      person.prompt?('专属要求：'+person.prompt):'',
      Array.isArray(person.tags)&&person.tags.length?('标签：'+person.tags.join('、')):''
    ].filter(Boolean).join('\n');
  }
  function recentWechat(personId){
    const arr=state.chatRecords&&Array.isArray(state.chatRecords[personId])?state.chatRecords[personId]:[];
    return arr.filter(msg=>msg&&!msg.hiddenSystem&&!msg.recalled).slice(-10).map(msg=>{
      const who=msg.role==='user'?'用户':'角色';
      const content=typeof window.baobaoMessageForAI==='function'?window.baobaoMessageForAI(msg):String(msg.content||'');
      return who+'：'+String(content||'').replace(/\s+/g,' ').slice(0,160);
    }).join('\n');
  }
  function recentOfflineText(session){
    return (session.entries||[]).slice(-10).map(entry=>{
      if(entry.role==='user') return '用户行动：'+String(entry.text||'');
      return normalizeBlocks(entry.blocks).map(block=>(block.type==='thought'?'角色内心（用户不知道）':'场景正文')+'：'+block.text).join('\n');
    }).join('\n');
  }
  function parseOfflineReply(raw){
    const value=String(raw||'').replace(/```(?:json|text)?/gi,'').replace(/```/g,'').trim();
    if(!value) return [];
    const marker=/\[(正文|心里|心理|内心)\]\s*([\s\S]*?)(?=\[(?:正文|心里|心理|内心)\]|$)/g;
    const blocks=[]; let match;
    while((match=marker.exec(value))){ const type=match[1]==='正文'?'narrative':'thought'; const part=String(match[2]||'').trim(); if(part) blocks.push({type:type,text:part}); }
    if(blocks.length) return blocks;
    return [{type:'narrative',text:value}];
  }
  function fallbackBlocks(person,userText,continueOnly){
    const name=String(person&&person.name||'他');
    const action=String(userText||'').trim();
    return [
      {type:'narrative',text:action?name+'安静地看着你，像是在认真分辨你这句话里的每一点情绪。周围的声音没有停下，可这一小块距离忽然变得很近。':name+'没有急着打破沉默，只是顺着刚才未说完的情绪继续留在你身边。'},
      {type:'thought',text:continueOnly?'再等一下。也许她下一秒就会愿意把真正想说的话告诉我。':'她这样说的时候到底在想什么？我不想逼得太紧，却也不想装作毫不在意。'},
      {type:'narrative',text:'“我在听。”他低声说，语气比平时慢了一些，“你继续说。”'}
    ];
  }
  async function requestOfflineReply(userText,continueOnly){
    const person=persona(), session=currentSession();
    if(!person||!session) return [];
    if(typeof window.sendChatCompletion!=='function') return fallbackBlocks(person,userText,continueOnly);
    const messages=[
      {role:'system',content:'你正在创作沉浸式“线下剧情模式”，必须严格扮演角色本人。这不是微信聊天，不要使用聊天气泡口吻；要写成连贯的现实场景、动作、对白与氛围。普通场景、动作和说出口的对白必须写在[正文]下面。角色没有说出口、用户无法直接知道的真实心理必须单独写在[心里]下面。心里描写不能伪装成旁白，也不能让用户角色凭空知道。只允许输出[正文]和[心里]标记，不得输出分析、标题、说明或选项。每次写2到5个段落，避免空洞华丽辞藻，动作与对白必须符合完整人设、关系和当前场景。不要替用户决定重要行动，不要擅自让用户说话。'},
    ];
    if(window.state && Array.isArray(state.offlinePresets)){
      const activePresets = state.offlinePresets.filter(p=>p && p.enabled && p.content);
      if(activePresets.length){
        const combined = activePresets.map(p=>p.content).join('\n\n');
        messages.push({role:'system',content:'【剧情预设，写作时必须严格遵守】\n'+combined});
      }
    }
    messages.push({role:'user',content:'【角色完整人设】\n'+fullPersonaContext(person)+'\n\n【当前场景】\n标题：'+session.title+'\n地点：'+session.location+'\n时间：'+session.sceneTime+'\n\n【最近微信内容，仅用于记住关系和上下文】\n'+(recentWechat(String(person.id))||'暂无')+'\n\n【当前线下剧情】\n'+(recentOfflineText(session)||'刚刚进入场景，还没有正文')+'\n\n【用户本次输入】\n'+(continueOnly?'用户没有新增台词或动作，请自然续写上一段，不要突然跳场景。':String(userText||''))+'\n\n严格按以下格式输出：\n[正文]\n场景、动作与对白\n[心里]\n角色没有说出口的真实想法\n[正文]\n自然继续。'});
    try{
      const task=Promise.resolve().then(()=>window.sendChatCompletion(messages));
      const reply=await Promise.race([task,new Promise((_,reject)=>setTimeout(()=>reject(new Error('线下剧情生成超时')),120000))]);
      const blocks=parseOfflineReply(reply);
      return blocks.length?blocks:fallbackBlocks(person,userText,continueOnly);
    }catch(e){ console.warn('线下剧情生成失败：',e&&e.message); if(typeof window.showToast==='function') showToast('AI 生成失败，已显示占位内容：'+(e&&e.message||'未知错误'), true); return fallbackBlocks(person,userText,continueOnly); }
  }
  function setBusy(v){
    busy=!!v;
    $('bbOfflineLoading')&&$('bbOfflineLoading').classList.toggle('show',busy);
    $('bbOfflineSendBtn')&&($('bbOfflineSendBtn').disabled=busy);
    $('bbOfflineContinueBtn')&&($('bbOfflineContinueBtn').disabled=busy);
  }
  async function advanceOffline(userText,continueOnly){
    if(busy) return;
    const trimmed=String(userText||'').trim();
    if(!continueOnly&&!trimmed) return;
    if(!continueOnly){ updateSession(session=>{ session.entries.push({id:'offline_user_'+Date.now(),role:'user',text:trimmed,time:Date.now()}); }); renderOffline(); }
    setBusy(true);
    const blocks=await requestOfflineReply(trimmed,continueOnly);
    updateSession(session=>{ session.entries.push({id:'offline_role_'+Date.now(),role:'assistant',blocks:normalizeBlocks(blocks),time:Date.now()}); });
    setBusy(false);
    renderOffline();
  }
  window.openOfflineMode=function(){
    ensurePage();
    const person=persona();
    if(!person){ if(typeof showToast==='function') showToast('请先进入一个角色的私聊',true); return; }
    if(typeof window.closeBaobaoTools==='function') window.closeBaobaoTools();
    const tools=$('tools'); if(tools) tools.style.display='none';
    activePersonaId=String(person.id||state.activeChatId||person.name||'default');
    const data=ensureBucket(activePersonaId); activeSessionId=data.bucket.activeSessionId;
    const page=$('baobaoOfflineMode'); page.classList.add('show','bb-offline-v192');
    renderOffline();
  };
  window.closeOfflineMode=function(){ const p=$('baobaoOfflineMode'); if(p) p.classList.remove('show'); closeOfflineSheet('settings'); closeOfflineSheet('history'); setBusy(false); };
  window.offlineInputResize=function(el){ el.style.height='auto'; el.style.height=Math.min(116,el.scrollHeight)+'px'; };
  window.sendOfflineInput=function(){ const input=$('bbOfflineInput'); const value=String(input&&input.value||'').trim(); if(!value) return; input.value=''; input.style.height='auto'; advanceOffline(value,false); };
  window.continueOfflineScene=function(){ advanceOffline('',true); };
  window.openOfflineSettings=function(){ const session=currentSession(); if(!session) return; $('bbOfflineSceneTitleInput').value=session.title||''; $('bbOfflineLocationInput').value=session.location||''; $('bbOfflineTimeInput').value=session.sceneTime||''; $('bbOfflineSettingsMask').classList.add('show'); };
  window.saveOfflineSettings=function(){ updateSession(session=>{ session.title=String($('bbOfflineSceneTitleInput').value||'新的线下剧情').trim(); session.location=String($('bbOfflineLocationInput').value||'未设定地点').trim(); session.sceneTime=String($('bbOfflineTimeInput').value||'当前').trim(); }); closeOfflineSheet('settings'); renderOffline(); if(typeof showToast==='function') showToast('线下场景已保存'); };
  window.openOfflineHistory=function(){ const data=ensureBucket(activePersonaId); $('bbOfflineHistoryList').innerHTML=data.bucket.sessions.slice().reverse().map(session=>'<div class="bb-offline-history-item '+(session.id===activeSessionId?'active':'')+'" onclick="loadOfflineSession(\''+esc(session.id)+'\')"><div class="bb-offline-history-name">'+esc(session.title||'未命名场景')+'</div><div class="bb-offline-history-meta">'+esc([session.location,session.sceneTime,(session.entries||[]).length+'层'].filter(Boolean).join(' · '))+'</div></div>').join(''); $('bbOfflineHistoryMask').classList.add('show'); };
  window.loadOfflineSession=function(id){ const data=ensureBucket(activePersonaId); if(!data.bucket.sessions.some(s=>s.id===id)) return; data.bucket.activeSessionId=id; activeSessionId=id; saveStore(data.store); closeOfflineSheet('history'); renderOffline(); };
  window.newOfflineScene=function(){ if(busy) return; const session=currentSession(); if(session&&session.entries&&session.entries.length&&!confirm('新建一段线下剧情吗？当前记录会保留在历史中。')) return; const data=ensureBucket(activePersonaId); const next=makeSession(); data.bucket.sessions.push(next); data.bucket.activeSessionId=next.id; activeSessionId=next.id; saveStore(data.store); renderOffline(); openOfflineSettings(); };
  window.closeOfflineSheet=function(type){ const id=type==='history'?'bbOfflineHistoryMask':'bbOfflineSettingsMask'; $(id)&&$(id).classList.remove('show'); };
  document.addEventListener('DOMContentLoaded',ensurePage);
  setTimeout(ensurePage,600);
  window.BaobaoOfflineMode={open:window.openOfflineMode,render:renderOffline,version:'1.1-pretty'};
})();
;

