  function drawDemoQr(canvas){
    const size=29;
    const ctx=canvas.getContext("2d");
    canvas.width=290;
    canvas.height=290;
    ctx.fillStyle="#fff";
    ctx.fillRect(0,0,290,290);
    const cell=10;
    const offset=0;

    function finder(x,y){
      ctx.fillStyle="#111";
      ctx.fillRect(x*cell,y*cell,7*cell,7*cell);
      ctx.fillStyle="#fff";
      ctx.fillRect((x+1)*cell,(y+1)*cell,5*cell,5*cell);
      ctx.fillStyle="#111";
      ctx.fillRect((x+2)*cell,(y+2)*cell,3*cell,3*cell);
    }
    finder(1,1);
    finder(21,1);
    finder(1,21);

    let seed=20260720;
    function random(){
      seed=(seed*9301+49297)%233280;
      return seed/233280;
    }
    ctx.fillStyle="#111";
    for(let y=0;y<size;y++){
      for(let x=0;x<size;x++){
        const inFinder=
          (x>=1&&x<=7&&y>=1&&y<=7)||
          (x>=21&&x<=27&&y>=1&&y<=7)||
          (x>=1&&x<=7&&y>=21&&y<=27);
        if(!inFinder&&random()>.52){
          ctx.fillRect(offset+x*cell,offset+y*cell,cell,cell);
        }
      }
    }
  }

