  function drawQr(canvas){
    if(!canvas)return;
    const ctx=canvas.getContext("2d");
    canvas.width=290;
    canvas.height=290;
    ctx.fillStyle="#fff";
    ctx.fillRect(0,0,290,290);
    ctx.fillStyle="#111";
    for(let y=0;y<29;y++){
      for(let x=0;x<29;x++){
        if(((x*17+y*31+x*y)%7)<3){
          ctx.fillRect(x*10,y*10,10,10);
        }
      }
    }
  }

